AIHR_PUBLIC_DATABASE_REF = "configured_ncs_database"
AIHR_PUBLIC_WORKSPACE_REF = "configured_workspace"
AIHR_LOCAL_DATABASE_PATH_RE = re.compile(
    r"(^|[\\/])data[\\/]processed[\\/][^\\/]+\.db(?:-(?:wal|shm|journal))?$",
    re.IGNORECASE,
)
AIHR_WINDOWS_ABSOLUTE_PATH_RE = re.compile(r"^[A-Za-z]:[\\/]|^\\\\")
AIHR_PUBLIC_WORKSPACE_KEYS = {
    "project_root",
    "root_path",
    "workspace",
    "workspace_path",
}
NCS_FULL_MAJOR_COUNT = 24
QUALIFICATION_COLLECTION_FORBIDDEN_STATUS_UPDATES = (
    "human_reviewed",
    "accepted",
    "reviewed",
)


def _aihr_public_path_text(
    value: Any,
    *,
    workspace_roots: tuple[str, ...] = (),
) -> str:
    text = str(value or "")
    if not text:
        return ""
    normalized = text.strip().replace("\\", "/").rstrip("/")
    if AIHR_LOCAL_DATABASE_PATH_RE.search(normalized):
        return AIHR_PUBLIC_DATABASE_REF
    root_texts = {
        str(ROOT).replace("\\", "/").rstrip("/"),
        str(ROOT.resolve()).replace("\\", "/").rstrip("/"),
        *(
            str(root).replace("\\", "/").rstrip("/")
            for root in workspace_roots
            if str(root).strip()
        ),
    }
    for root_text in root_texts:
        if not root_text:
            continue
        if normalized.lower() == root_text.lower():
            return AIHR_PUBLIC_WORKSPACE_REF
        prefix = f"{root_text}/"
        if normalized.lower().startswith(prefix.lower()):
            return normalized[len(prefix) :]
    if AIHR_WINDOWS_ABSOLUTE_PATH_RE.match(text.strip()):
        return PureWindowsPath(text).name
    path = Path(text)
    if path.is_absolute():
        try:
            return path.resolve(strict=False).relative_to(ROOT.resolve()).as_posix()
        except (OSError, ValueError):
            return path.name
    return text


def _aihr_sanitize_public_path_fields(
    value: Any,
    *,
    workspace_roots: tuple[str, ...] = (),
) -> Any:
    if isinstance(value, dict):
        discovered_roots = tuple(
            str(child)
            for key, child in value.items()
            if str(key).lower() in AIHR_PUBLIC_WORKSPACE_KEYS
            and isinstance(child, (str, Path))
            and str(child).strip()
        )
        active_workspace_roots = tuple(dict.fromkeys((*workspace_roots, *discovered_roots)))
        sanitized: dict[str, Any] = {}
        for key, child in value.items():
            key_text = str(key)
            key_lower = key_text.lower()
            if key_lower in AIHR_PUBLIC_WORKSPACE_KEYS:
                sanitized["workspace_ref"] = AIHR_PUBLIC_WORKSPACE_REF
                continue
            if key_lower in AIHR_LOCAL_PATH_KEY_MARKERS:
                sanitized["database_ref"] = AIHR_PUBLIC_DATABASE_REF
                continue
            if (
                isinstance(child, str)
                and (
                    key_lower == "path"
                    or key_lower == "reports_dir"
                    or key_lower.endswith("_path")
                    or key_lower.endswith("_paths")
                    or _aihr_local_path_text_markers(child)
                )
            ):
                sanitized[key_text] = _aihr_public_path_text(
                    child,
                    workspace_roots=active_workspace_roots,
                )
            else:
                sanitized[key_text] = _aihr_sanitize_public_path_fields(
                    child,
                    workspace_roots=active_workspace_roots,
                )
        return sanitized
    if isinstance(value, list):
        return [
            _aihr_public_path_text(item, workspace_roots=workspace_roots)
            if isinstance(item, str) and _aihr_local_path_text_markers(item)
            else _aihr_sanitize_public_path_fields(
                item,
                workspace_roots=workspace_roots,
            )
            for item in value
        ]
    return value


def _provenance_status_display_from_presence(presence: dict[str, Any]) -> str:
    return (
        "packet_backed_status"
        if presence.get("packet_backed_provenance")
        else "legacy_status_needs_reconfirmation"
    )

CHECKPOINT_ARTIFACT_STEM_RE = re.compile(
    r"(?:checkpoint|safe_ops_checkpoint|db_readiness_checkpoint|work_checkpoint)"
)


def _path_mtime(path: Path) -> float:
    try:
        return path.stat().st_mtime
    except OSError:
        return 0.0


def _embedded_artifact_date(path: Path) -> int:
    for part in reversed(path.stem.split("_")):
        if len(part) == 8 and part.isdigit():
            return int(part)
    return 0


def _artifact_variant_rank(path: Path) -> int:
    stem = path.stem.lower()
    if re.search(r"_(?:latest|current)$", stem):
        return 3
    if stem.endswith("_public"):
        return 2
    if re.search(r"_20\d{6}$", stem):
        return 1
    return 0


def _aihr_artifact_date_suffix(path: Path) -> str:
    match = re.search(r"(_\d{8}(?:_[A-Za-z0-9]+)*)$", path.stem)
    return match.group(1) if match else ""


def _checkpoint_generated_at_timestamp(path: Path) -> float:
    if path.suffix.lower() != ".json" or not CHECKPOINT_ARTIFACT_STEM_RE.search(path.stem):
        return -1.0
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return -1.0
    if not isinstance(payload, dict):
        return -1.0
    value = payload.get("generated_at")
    if not value:
        return -1.0
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return -1.0
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc).timestamp()


def _dated_artifact_sort_key(path: Path) -> tuple[int, int, float, float]:
    generated_at = _checkpoint_generated_at_timestamp(path)
    return (
        _embedded_artifact_date(path),
        _artifact_variant_rank(path),
        generated_at if generated_at >= 0 else -1.0,
        _path_mtime(path),
    )


def _latest_report_path(*patterns: str, fallback: Path) -> Path:
    reports_dir = fallback.parent
    candidates = [
        path
        for pattern in patterns
        for path in reports_dir.glob(pattern)
        if path.is_file()
    ]
    if not candidates:
        return fallback
    return max(candidates, key=_dated_artifact_sort_key)


def _latest_report_path_recursive(*patterns: str, fallback: Path) -> Path:
    reports_dir = fallback.parent
    candidates = [
        path
        for pattern in patterns
        for path in reports_dir.rglob(pattern)
        if path.is_file()
    ]
    if not candidates:
        return fallback
    return max(candidates, key=_dated_artifact_sort_key)


def _preferred_latest_report_path(*patterns: str, fallback: Path) -> Path:
    reports_dir = fallback.parent
    candidates = [
        (pattern_index, path)
        for pattern_index, pattern in enumerate(patterns)
        for path in reports_dir.glob(pattern)
        if path.is_file()
    ]
    if candidates:
        return max(
            candidates,
            key=lambda item: (
                _embedded_artifact_date(item[1]),
                -item[0],
                _artifact_variant_rank(item[1]),
                _checkpoint_generated_at_timestamp(item[1]),
                _path_mtime(item[1]),
            ),
        )[1]
    return fallback


def _latest_same_date_report_path(
    reports_dir: Path,
    artifact_date: int,
    *patterns: str,
) -> Path | None:
    if artifact_date <= 0:
        return None
    candidates = [
        path
        for pattern in patterns
        for path in reports_dir.glob(pattern)
        if path.is_file() and _embedded_artifact_date(path) == artifact_date
    ]
    if not candidates:
        return None
    return max(candidates, key=_dated_artifact_sort_key)


def _configure_utf8_stdio_early() -> None:
    for stream_name in ("stdout", "stderr"):
        stream = getattr(sys, stream_name, None)
        reconfigure = getattr(stream, "reconfigure", None)
        if callable(reconfigure):
            try:
                reconfigure(encoding="utf-8")
            except (OSError, ValueError):
                pass


def _run_hrd_guide_preprocess_fast_path(argv: list[str]) -> None:
    if len(argv) < 2 or argv[1] != "preprocess-hrd-guide-reference":
        return
    _configure_utf8_stdio_early()
    from ncs_mcp.hrd_guide_reference import (
        DEFAULT_HRD_GUIDE_CHUNKS_FILENAME,
        DEFAULT_HRD_GUIDE_INDEX_FILENAME,
        DEFAULT_HRD_GUIDE_MARKDOWN_FILENAME,
        DEFAULT_HRD_GUIDE_RAW_FILENAME,
        preprocess_hrd_guide_reference,
    )

    parser = argparse.ArgumentParser(
        description="Copy and index the 2026 NCS HRD guide Markdown as a framework reference."
    )
    parser.add_argument(
        "--source",
        type=Path,
        default=ROOT / "docs" / "reference" / DEFAULT_HRD_GUIDE_RAW_FILENAME,
    )
    parser.add_argument(
        "--reference-dir",
        type=Path,
        default=ROOT / "docs" / "reference",
    )
    parser.add_argument(
        "--index-out",
        type=Path,
        default=ROOT / "docs" / "reference" / DEFAULT_HRD_GUIDE_INDEX_FILENAME,
    )
    parser.add_argument(
        "--markdown-out",
        type=Path,
        default=ROOT / "docs" / "reference" / DEFAULT_HRD_GUIDE_MARKDOWN_FILENAME,
    )
    parser.add_argument(
        "--chunks-out",
        type=Path,
        default=ROOT / "docs" / "reference" / DEFAULT_HRD_GUIDE_CHUNKS_FILENAME,
    )
    parser.add_argument("--no-copy-source", action="store_true")
    parser.add_argument("--chunk-chars", type=int, default=2200)
    parser.add_argument("--overlap-chars", type=int, default=250)
    args = parser.parse_args(argv[2:])
    result = preprocess_hrd_guide_reference(
        source_path=args.source,
        reference_dir=args.reference_dir,
        index_path=args.index_out,
        markdown_path=args.markdown_out,
        chunks_path=args.chunks_out,
        copy_source=not args.no_copy_source,
        chunk_chars=args.chunk_chars,
        overlap_chars=args.overlap_chars,
    )
    print(json.dumps(result, ensure_ascii=False, indent=2))
    raise SystemExit(0)


_run_hrd_guide_preprocess_fast_path(sys.argv)

