def aihr_alias_artifact_path(out_dir: Path, base_name: str) -> Path:
    parts = base_name.rsplit("_", 1)
    if len(parts) == 2 and len(parts[1]) == 8 and parts[1].isdigit():
        return out_dir / f"{parts[0]}_alias_{parts[1]}.json"
    return out_dir / f"{base_name}_alias.json"


def aihr_internal_artifact_path(out_dir: Path, base_name: str) -> Path:
    parts = base_name.rsplit("_", 1)
    if len(parts) == 2 and len(parts[1]) == 8 and parts[1].isdigit():
        return out_dir / f"{parts[0]}_internal_{parts[1]}.json"
    return out_dir / f"{base_name}_internal.json"


def aihr_alias_internal_artifact_path(out_dir: Path, base_name: str) -> Path:
    alias_stem = aihr_alias_artifact_path(out_dir, base_name).stem
    parts = alias_stem.rsplit("_", 1)
    if len(parts) == 2 and len(parts[1]) == 8 and parts[1].isdigit():
        return out_dir / f"{parts[0]}_internal_{parts[1]}.json"
    return out_dir / f"{alias_stem}_internal.json"


