def write_ksa_term_review_workflow_manifest_markdown(manifest: dict[str, Any], out_path: Path) -> None:
    def _md_cell(value: Any) -> str:
        return str(value if value is not None else "").replace("|", "\\|").replace("\n", " ")

    def _artifact_line(label: str, key: str) -> str:
        value = (manifest.get("artifacts") or {}).get(key)
        return f"- {label}: `{_md_cell(value)}`"

    summary = manifest.get("summary") if isinstance(manifest.get("summary"), dict) else {}
    safety = manifest.get("safety_contract") if isinstance(manifest.get("safety_contract"), dict) else {}
    first_queue = summary.get("first_review_queue") if isinstance(summary.get("first_review_queue"), list) else []
    lines = [
        "# KSA Term Review Workflow Manifest",
        "",
        f"- ok: `{manifest.get('ok')}`",
        f"- schema: `{manifest.get('schema')}`",
        f"- generated_at: `{manifest.get('generated_at')}`",
        f"- status_update_allowed: `{manifest.get('status_update_allowed')}`",
        f"- db_writes: `{manifest.get('db_writes')}`",
        f"- approval_claim: `{manifest.get('approval_claim')}`",
        f"- source_payload_exposed: `{safety.get('source_payload_exposed')}`",
        "",
        "## Summary",
        "",
        f"- impact_group_count: `{summary.get('impact_group_count')}`",
        f"- minimal_review_item_count: `{summary.get('minimal_review_item_count')}`",
        f"- concept_review_group_count: `{summary.get('concept_review_group_count')}`",
        f"- decision_blank_count: `{summary.get('decision_blank_count')}`",
        f"- suggested_decision_counts: `{json.dumps(summary.get('suggested_decision_counts') or {}, ensure_ascii=False)}`",
        f"- represented_transition_penalty_concept_count: `{summary.get('represented_transition_penalty_concept_count')}`",
        f"- job_base_auxiliary_group_count: `{summary.get('job_base_auxiliary_group_count')}`",
        "",
        "## First Review Queue",
        "",
        "| # | Concept | Suggested | Confidence | Score | Terms |",
        "| ---: | --- | --- | --- | ---: | ---: |",
    ]
    for index, item in enumerate(first_queue, start=1):
        lines.append(
            "| {index} | `{concept_id}` {concept_name} | `{suggested}` | `{confidence}` | {score} | {terms} |".format(
                index=index,
                concept_id=_md_cell(item.get("concept_id")),
                concept_name=_md_cell(item.get("concept_name")),
                suggested=_md_cell(item.get("suggested_decision")),
                confidence=_md_cell(item.get("suggested_decision_confidence")),
                score=int(item.get("max_priority_score") or 0),
                terms=int(item.get("item_count") or 0),
            )
        )
    if not first_queue:
        lines.append("| 0 | none |  |  | 0 | 0 |")
    lines.extend(
        [
        "",
        "## Artifacts",
        "",
        _artifact_line("Manifest JSON", "manifest"),
        _artifact_line("Impact JSON", "impact_report"),
        _artifact_line("Impact Markdown", "impact_markdown"),
        _artifact_line("Minimal Slice JSON", "minimal_review_slice"),
        _artifact_line("Minimal Slice JSONL", "minimal_review_jsonl"),
        _artifact_line("Minimal Slice CSV", "minimal_review_csv"),
        _artifact_line("Minimal Slice Markdown", "minimal_review_markdown"),
        _artifact_line("Manifest Markdown", "manifest_markdown"),
        "",
        "## Safety Contract",
        "",
        f"- raw_source_mutation_allowed: `{safety.get('raw_source_mutation_allowed')}`",
        f"- trusted_status_write_allowed: `{safety.get('trusted_status_write_allowed')}`",
        f"- forbidden_automatic_statuses: `{', '.join(safety.get('forbidden_automatic_statuses') or [])}`",
        f"- preferred_decision_unit: `{_md_cell(safety.get('preferred_decision_unit'))}`",
        f"- evidence_role: `{_md_cell(safety.get('evidence_role'))}`",
        f"- scoring_role: `{_md_cell(safety.get('scoring_role'))}`",
        f"- suggested_decision_policy: `{_md_cell(safety.get('suggested_decision_policy'))}`",
        "",
        "## Operator Steps",
        "",
        ]
    )
    for step in manifest.get("operator_steps") or []:
        lines.append(f"- {_md_cell(step)}")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def write_ksa_term_review_operator_packet_markdown(packet: dict[str, Any], out_path: Path) -> None:
    def _md_cell(value: Any) -> str:
        return str(value if value is not None else "").replace("|", "\\|").replace("\n", " ")

    readiness = packet.get("readiness_summary") if isinstance(packet.get("readiness_summary"), dict) else {}
    workflow_summary = packet.get("workflow_summary") if isinstance(packet.get("workflow_summary"), dict) else {}
    artifacts = packet.get("artifacts") if isinstance(packet.get("artifacts"), dict) else {}
    lines = [
        "# KSA Term Review Operator Packet",
        "",
        f"- ok: `{packet.get('ok')}`",
        f"- schema: `{packet.get('schema')}`",
        f"- generated_at: `{packet.get('generated_at')}`",
        f"- status_update_allowed: `{packet.get('status_update_allowed')}`",
        f"- db_writes: `{packet.get('db_writes')}`",
        f"- approval_claim: `{packet.get('approval_claim')}`",
        f"- source_payload_exposed: `{packet.get('source_payload_exposed')}`",
        f"- raw_source_mutation_allowed: `{packet.get('raw_source_mutation_allowed')}`",
        f"- trusted_status_write_allowed: `{packet.get('trusted_status_write_allowed')}`",
        f"- ready_for_minimal_human_review: `{readiness.get('ready_for_minimal_human_review')}`",
        f"- ready_for_guarded_action_plan_review: `{readiness.get('ready_for_guarded_action_plan_review')}`",
        f"- next_step: `{_md_cell(readiness.get('next_step'))}`",
        "",
        "## Review Scope",
        "",
        f"- concept_review_group_count: `{workflow_summary.get('concept_review_group_count')}`",
        f"- decision_blank_count: `{workflow_summary.get('decision_blank_count')}`",
        f"- suggested_decision_counts: `{json.dumps(workflow_summary.get('suggested_decision_counts') or {}, ensure_ascii=False)}`",
        f"- pending_decision_count: `{readiness.get('pending_decision_count')}`",
        f"- action_count: `{readiness.get('action_count')}`",
        "",
        "## Artifacts",
        "",
        "| Artifact | Path |",
        "| --- | --- |",
    ]
    for key, value in artifacts.items():
        lines.append(f"| `{_md_cell(key)}` | `{_md_cell(value)}` |")
    lines.extend(
        [
            "",
            "## Operator Steps",
            "",
        ]
    )
    for step in packet.get("operator_steps") or []:
        lines.append(f"- {_md_cell(step)}")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def write_ksa_definition_review_operator_packet_markdown(packet: dict[str, Any], out_path: Path) -> None:
    def _md_cell(value: Any) -> str:
        return str(value if value is not None else "").replace("|", "\\|").replace("\n", " ")

    summary = packet.get("summary") if isinstance(packet.get("summary"), dict) else {}
    artifacts = packet.get("artifacts") if isinstance(packet.get("artifacts"), dict) else {}
    safety = packet.get("safety_contract") if isinstance(packet.get("safety_contract"), dict) else {}
    first_queue = summary.get("first_review_queue") if isinstance(summary.get("first_review_queue"), list) else []
    lines = [
        "# KSA Definition Review Operator Packet",
        "",
        f"- ok: `{packet.get('ok')}`",
        f"- schema: `{packet.get('schema')}`",
        f"- generated_at: `{packet.get('generated_at')}`",
        f"- status_update_allowed: `{packet.get('status_update_allowed')}`",
        f"- db_writes: `{packet.get('db_writes')}`",
        f"- approval_claim: `{packet.get('approval_claim')}`",
        f"- human_decision_required: `{packet.get('human_decision_required')}`",
        "",
        "## Summary",
        "",
        f"- promotion_candidate_rows_scanned: `{summary.get('promotion_candidate_rows_scanned')}`",
        f"- promotable_definition_candidates: `{summary.get('promotable_definition_candidates')}`",
        f"- skipped_boilerplate_definition_candidates: `{summary.get('skipped_boilerplate_definition_candidates')}`",
        f"- priority_report_row_count: `{summary.get('priority_report_row_count')}`",
        f"- review_pack_row_count: `{summary.get('review_pack_row_count')}`",
        f"- review_csv_record_count: `{summary.get('review_csv_record_count')}`",
        f"- decision_blank_count: `{summary.get('decision_blank_count')}`",
        f"- recommended_review_action_counts: `{json.dumps(summary.get('recommended_review_action_counts') or {}, ensure_ascii=False)}`",
        f"- review_focus_counts: `{json.dumps(summary.get('review_focus_counts') or {}, ensure_ascii=False)}`",
        "",
        "## First Review Queue",
        "",
        "| # | Concept | Type | Appearances | Units | Majors | Action | Draft Policy |",
        "| ---: | --- | --- | ---: | ---: | ---: | --- | --- |",
    ]
    for index, item in enumerate(first_queue, start=1):
        lines.append(
            "| {index} | `{concept_id}` {concept_name} | {concept_type} | {appearance_count} | {unit_count} | {major_count} | `{action}` | `{policy}` |".format(
                index=index,
                concept_id=_md_cell(item.get("concept_id")),
                concept_name=_md_cell(item.get("concept_name")),
                concept_type=_md_cell(item.get("concept_type")),
                appearance_count=int(item.get("appearance_count") or 0),
                unit_count=int(item.get("unit_count") or 0),
                major_count=int(item.get("major_count") or 0),
                action=_md_cell(item.get("recommended_review_action")),
                policy=_md_cell(item.get("draft_review_policy")),
            )
        )
    if not first_queue:
        lines.append("| 0 | none |  | 0 | 0 | 0 |  |  |")
    lines.extend(
        [
            "",
            "## Artifacts",
            "",
            "| Artifact | Path |",
            "| --- | --- |",
        ]
    )
    for key, value in artifacts.items():
        lines.append(f"| `{_md_cell(key)}` | `{_md_cell(value)}` |")
    lines.extend(
        [
            "",
            "## Safety Contract",
            "",
            f"- raw_source_mutation_allowed: `{safety.get('raw_source_mutation_allowed')}`",
            f"- trusted_status_write_allowed: `{safety.get('trusted_status_write_allowed')}`",
            f"- status_update_allowed: `{safety.get('status_update_allowed')}`",
            f"- db_writes: `{safety.get('db_writes')}`",
            f"- approval_claim: `{safety.get('approval_claim')}`",
            f"- forbidden_automatic_statuses: `{', '.join(safety.get('forbidden_automatic_statuses') or [])}`",
            f"- draft_definition_policy: `{_md_cell(safety.get('draft_definition_policy'))}`",
            "",
            "## Operator Steps",
            "",
        ]
    )
    for step in packet.get("operator_steps") or []:
        lines.append(f"- {_md_cell(step)}")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _connect_readonly_sqlite(db_path: Path) -> sqlite3.Connection:
    if not db_path.exists():
        raise FileNotFoundError(f"SQLite DB does not exist: {db_path}")
    conn = sqlite3.connect(f"{db_path.resolve().as_uri()}?mode=ro", uri=True, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout = 30000")
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def _table_exists(conn: sqlite3.Connection, table_name: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?",
        (table_name,),
    ).fetchone()
    return row is not None


def _table_columns(conn: sqlite3.Connection, table_name: str) -> set[str]:
    return {str(row["name"]) for row in conn.execute(f"PRAGMA table_info({table_name})")}


def build_ksa_immutability_audit(
    conn: sqlite3.Connection,
    *,
    baseline_sha256: str | None = None,
    baseline_raw_text_multiset_sha256: str | None = None,
    sample_limit: int = 10,
) -> dict[str, Any]:
    sample_limit = max(0, sample_limit)
    generated_at = datetime.now(timezone.utc).isoformat()
    safety = {
        "status_update_allowed": False,
        "db_writes": False,
        "approval_claim": False,
        "raw_source_mutation_allowed": False,
        "trusted_status_write_allowed": False,
        "human_decision_required_for_status_update": True,
        "forbidden_automatic_statuses": list(QUALIFICATION_COLLECTION_FORBIDDEN_STATUS_UPDATES),
    }
    report: dict[str, Any] = {
        "schema": "ncs_ksa_immutability_audit_v1",
        "ok": True,
        "generated_at": generated_at,
        "report_only": True,
        **safety,
        "safety": safety,
        "baseline": {
            "provided": bool(baseline_sha256 or baseline_raw_text_multiset_sha256),
            "sha256": baseline_sha256,
            "matches_current": None,
            "raw_text_multiset_sha256": baseline_raw_text_multiset_sha256,
            "raw_text_multiset_matches_current": None,
            "source_text_matches_current": None,
        },
        "tables": {
            "ksa_items": _table_exists(conn, "ksa_items"),
            "ontology_concepts": _table_exists(conn, "ontology_concepts"),
        },
        "issues": [],
    }

    if not report["tables"]["ksa_items"]:
        report["ok"] = False
        report["issues"].append("missing_table:ksa_items")
        report["ksa_items"] = {
            "row_count": 0,
            "hash_algorithm": "sha256",
            "ordered_source_columns": [],
            "sha256": None,
        }
        return report

    required_ksa_columns = {
        "ksa_id",
        "element_id",
        "ksa_type_code",
        "ksa_type_name",
        "ksa_no",
        "ksa_text_raw",
    }
    missing_ksa_columns = sorted(required_ksa_columns - _table_columns(conn, "ksa_items"))
    if missing_ksa_columns:
        report["ok"] = False
        report["issues"].extend(f"missing_column:ksa_items.{column}" for column in missing_ksa_columns)
        report["ksa_items"] = {
            "row_count": 0,
            "hash_algorithm": "sha256",
            "ordered_source_columns": [
                "ksa_id",
                "element_id",
                "ksa_type_code",
                "ksa_type_name",
                "ksa_no",
                "ksa_text_raw",
            ],
            "sha256": None,
            "missing_columns": missing_ksa_columns,
        }
        return report

    digest = hashlib.sha256()
    row_count = 0
    for row in conn.execute(
        """
        SELECT
            ksa_id,
            element_id,
            ksa_type_code,
            ksa_type_name,
            ksa_no,
            ksa_text_raw
        FROM ksa_items
        ORDER BY ksa_id
        """
    ):
        row_count += 1
        values = [
            row["ksa_id"],
            row["element_id"],
            row["ksa_type_code"],
            row["ksa_type_name"],
            row["ksa_no"],
            row["ksa_text_raw"],
        ]
        digest.update(
            json.dumps(values, ensure_ascii=False, separators=(",", ":"), default=str).encode("utf-8")
        )
        digest.update(b"\n")
    ksa_sha256 = f"sha256:{digest.hexdigest()}"
    raw_text_digest = hashlib.sha256()
    for row in conn.execute(
        """
        SELECT
            ksa_type_code,
            ksa_type_name,
            ksa_no,
            ksa_text_raw
        FROM ksa_items
        ORDER BY
            COALESCE(ksa_type_code, ''),
            COALESCE(ksa_type_name, ''),
            COALESCE(ksa_no, ''),
            COALESCE(ksa_text_raw, '')
        """
    ):
        values = [
            row["ksa_type_code"],
            row["ksa_type_name"],
            row["ksa_no"],
            row["ksa_text_raw"],
        ]
        raw_text_digest.update(
            json.dumps(values, ensure_ascii=False, separators=(",", ":"), default=str).encode("utf-8")
        )
        raw_text_digest.update(b"\n")
    raw_text_multiset_sha256 = f"sha256:{raw_text_digest.hexdigest()}"
    report["ksa_items"] = {
        "row_count": row_count,
        "hash_algorithm": "sha256",
        "ordered_source_columns": [
            "ksa_id",
            "element_id",
            "ksa_type_code",
            "ksa_type_name",
            "ksa_no",
            "ksa_text_raw",
        ],
        "sha256": ksa_sha256,
        "raw_text_multiset_sha256": raw_text_multiset_sha256,
        "raw_text_multiset_columns": [
            "ksa_type_code",
            "ksa_type_name",
            "ksa_no",
            "ksa_text_raw",
        ],
        "immutability_note": (
            "Compare this hash with a prior audit artifact to prove ksa_items.ksa_text_raw "
            "and row identity fields are unchanged."
        ),
        "raw_text_multiset_note": (
            "This hash excludes surrogate IDs and proves the raw KSA text/type/no multiset "
            "is unchanged across logically equivalent rebuilds."
        ),
    }
    if baseline_sha256:
        report["baseline"]["matches_current"] = baseline_sha256 == ksa_sha256
    if baseline_raw_text_multiset_sha256:
        report["baseline"]["raw_text_multiset_matches_current"] = (
            baseline_raw_text_multiset_sha256 == raw_text_multiset_sha256
        )
    source_text_matches_current = (
        report["baseline"]["matches_current"] is True
        or report["baseline"]["raw_text_multiset_matches_current"] is True
    )
    report["baseline"]["source_text_matches_current"] = source_text_matches_current
    if not source_text_matches_current:
        report["ok"] = False
        if baseline_sha256 and report["baseline"]["matches_current"] is False:
            report["issues"].append("baseline_hash_mismatch:ksa_items")
        if (
            baseline_raw_text_multiset_sha256
            and report["baseline"]["raw_text_multiset_matches_current"] is False
        ):
            report["issues"].append("baseline_hash_mismatch:ksa_items.raw_text_multiset")
    else:
        if baseline_sha256 and report["baseline"]["matches_current"] is False:
            report["warnings"] = report.get("warnings", [])
            report["warnings"].append("baseline_row_identity_hash_mismatch_raw_text_matches")
    if not (baseline_sha256 or baseline_raw_text_multiset_sha256):
        report["ok"] = False
        report["issues"].append("baseline_hash_missing:ksa_items")

    trusted_statuses = tuple(QUALIFICATION_COLLECTION_FORBIDDEN_STATUS_UPDATES)
    boilerplate_sql = """
        CASE
            WHEN definition_source IN (
                'term_definition_template',
                'term_definition_candidate_template',
                'ksa_definition_template',
                'generated_template',
                'ksa_meaning_candidates.term_definition_template',
                'ksa_meaning_candidate_promotion'
            )
                THEN 1
            WHEN concept_type = 'knowledge'
                 AND definition LIKE '%' || '업무 판단과 문제 해결에 필요한 관련 원리, 기준, 절차, 사례에 대한 지식.' || '%'
                THEN 1
            WHEN concept_type = 'skill'
                 AND definition LIKE '%' || '업무 상황에서 관련 절차나 도구를 활용해 과업을 수행하는 능력.' || '%'
                THEN 1
            WHEN concept_type = 'attitude'
                 AND definition LIKE '%' || '업무 수행 과정에서 품질, 협업, 책임성을 유지하기 위한 태도.' || '%'
                THEN 1
            WHEN concept_type = 'attitude'
                 AND definition LIKE '%' || '업무 수행 과정에서 해당 행동 기준을 일관되게 실천하려는 의지.' || '%'
                THEN 1
            ELSE 0
        END
    """
    if report["tables"]["ontology_concepts"]:
        required_concept_columns = {
            "concept_id",
            "concept_name",
            "concept_type",
            "definition",
            "definition_source",
            "definition_status",
            "review_status",
        }
        missing_concept_columns = sorted(
            required_concept_columns - _table_columns(conn, "ontology_concepts")
        )
        if missing_concept_columns:
            report["ok"] = False
            report["issues"].extend(
                f"missing_column:ontology_concepts.{column}"
                for column in missing_concept_columns
            )
            report["ontology_definitions"] = {
                "total_concepts": None,
                "concepts_with_definition": None,
                "boilerplate_definition_count": None,
                "boilerplate_trusted_status_count": None,
                "draft_or_template_trusted_status_count": None,
                "trusted_statuses_checked": list(trusted_statuses),
                "trusted_boilerplate_samples": [],
                "missing_columns": missing_concept_columns,
            }
            return report
        counts = conn.execute(
            f"""
            SELECT
                COUNT(*) AS total_concepts,
                SUM(CASE WHEN TRIM(COALESCE(definition, '')) <> '' THEN 1 ELSE 0 END) AS concepts_with_definition,
                SUM({boilerplate_sql}) AS boilerplate_definition_count,
                SUM(
                    CASE
                        WHEN {boilerplate_sql} = 1
                         AND (
                             COALESCE(definition_status, '') IN ({','.join('?' for _ in trusted_statuses)})
                             OR COALESCE(review_status, '') IN ({','.join('?' for _ in trusted_statuses)})
                         )
                        THEN 1
                        ELSE 0
                    END
                ) AS boilerplate_trusted_status_count,
                SUM(
                    CASE
                        WHEN (
                            COALESCE(definition_source, '') LIKE '%draft%'
                            OR COALESCE(definition_source, '') LIKE '%template%'
                            OR COALESCE(definition_source, '') LIKE '%candidate%'
                        )
                         AND (
                             COALESCE(definition_status, '') IN ({','.join('?' for _ in trusted_statuses)})
                             OR COALESCE(review_status, '') IN ({','.join('?' for _ in trusted_statuses)})
                         )
                        THEN 1
                        ELSE 0
                    END
                ) AS draft_or_template_trusted_status_count
            FROM ontology_concepts
            """,
            trusted_statuses + trusted_statuses + trusted_statuses + trusted_statuses,
        ).fetchone()
        trusted_samples = [
            dict(row)
            for row in conn.execute(
                f"""
                SELECT
                    concept_id,
                    concept_name,
                    concept_type,
                    definition_status,
                    review_status,
                    definition_source
                FROM ontology_concepts
                WHERE {boilerplate_sql} = 1
                  AND (
                      COALESCE(definition_status, '') IN ({','.join('?' for _ in trusted_statuses)})
                      OR COALESCE(review_status, '') IN ({','.join('?' for _ in trusted_statuses)})
                  )
                ORDER BY concept_id
                LIMIT ?
                """,
                trusted_statuses + trusted_statuses + (sample_limit,),
            )
        ]
        ontology_summary = {
            "total_concepts": int(counts["total_concepts"] or 0),
            "concepts_with_definition": int(counts["concepts_with_definition"] or 0),
            "boilerplate_definition_count": int(counts["boilerplate_definition_count"] or 0),
            "boilerplate_trusted_status_count": int(counts["boilerplate_trusted_status_count"] or 0),
            "draft_or_template_trusted_status_count": int(
                counts["draft_or_template_trusted_status_count"] or 0
            ),
            "trusted_statuses_checked": list(trusted_statuses),
            "trusted_boilerplate_samples": trusted_samples,
        }
        report["ontology_definitions"] = ontology_summary
        if ontology_summary["boilerplate_trusted_status_count"]:
            report["ok"] = False
            report["issues"].append("boilerplate_definition_has_trusted_status")
        if ontology_summary["draft_or_template_trusted_status_count"]:
            report["ok"] = False
            report["issues"].append("draft_or_template_definition_has_trusted_status")
    else:
        report["ok"] = False
        report["ontology_definitions"] = {
            "total_concepts": 0,
            "concepts_with_definition": 0,
            "boilerplate_definition_count": 0,
            "boilerplate_trusted_status_count": 0,
            "draft_or_template_trusted_status_count": 0,
            "trusted_statuses_checked": list(trusted_statuses),
            "trusted_boilerplate_samples": [],
        }
        report["issues"].append("missing_table:ontology_concepts")

    return report


def write_ksa_immutability_audit_markdown(report: dict[str, Any], out_path: Path) -> None:
    ksa = report.get("ksa_items") or {}
    ontology = report.get("ontology_definitions") or {}
    safety = report.get("safety") or {}
    baseline = report.get("baseline") or {}
    lines = [
        "# KSA Immutability Audit",
        "",
        f"- schema: `{report.get('schema')}`",
        f"- ok: `{report.get('ok')}`",
        f"- report_only: `{report.get('report_only')}`",
        f"- generated_at: `{report.get('generated_at')}`",
        "",
        "## KSA Source Hash",
        "",
        f"- row_count: `{ksa.get('row_count')}`",
        f"- hash_algorithm: `{ksa.get('hash_algorithm')}`",
        f"- sha256: `{ksa.get('sha256')}`",
        f"- ordered_source_columns: `{', '.join(ksa.get('ordered_source_columns') or [])}`",
        f"- raw_text_multiset_sha256: `{ksa.get('raw_text_multiset_sha256')}`",
        f"- raw_text_multiset_columns: `{', '.join(ksa.get('raw_text_multiset_columns') or [])}`",
        f"- baseline_provided: `{baseline.get('provided')}`",
        f"- baseline_matches_current: `{baseline.get('matches_current')}`",
        f"- baseline_raw_text_multiset_matches_current: `{baseline.get('raw_text_multiset_matches_current')}`",
        f"- baseline_source_text_matches_current: `{baseline.get('source_text_matches_current')}`",
        "",
        "## Definition Promotion Guard",
        "",
        f"- total_concepts: `{ontology.get('total_concepts')}`",
        f"- concepts_with_definition: `{ontology.get('concepts_with_definition')}`",
        f"- boilerplate_definition_count: `{ontology.get('boilerplate_definition_count')}`",
        f"- boilerplate_trusted_status_count: `{ontology.get('boilerplate_trusted_status_count')}`",
        f"- draft_or_template_trusted_status_count: `{ontology.get('draft_or_template_trusted_status_count')}`",
        "",
        "## Safety Contract",
        "",
        f"- raw_source_mutation_allowed: `{safety.get('raw_source_mutation_allowed')}`",
        f"- trusted_status_write_allowed: `{safety.get('trusted_status_write_allowed')}`",
        f"- status_update_allowed: `{safety.get('status_update_allowed')}`",
        f"- db_writes: `{safety.get('db_writes')}`",
        f"- approval_claim: `{safety.get('approval_claim')}`",
        f"- forbidden_automatic_statuses: `{', '.join(safety.get('forbidden_automatic_statuses') or [])}`",
        "",
        "## Issues",
        "",
    ]
    issues = report.get("issues") or []
    if issues:
        lines.extend(f"- `{issue}`" for issue in issues)
    else:
        lines.append("- none")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _ontology_major_artifact_path(out_dir: Path, prefix: str, major_code: str, date_stamp: str, suffix: str) -> Path:
    return out_dir / f"{prefix}{major_code}_{suffix}_{date_stamp}.csv" if suffix == "pairs" else out_dir / f"{prefix}{major_code}_{date_stamp}.{suffix}"


def _ontology_transferability_top_scope(report: dict[str, Any]) -> dict[str, Any]:
    scope = (report.get("scopes") or [{}])[0]
    groups = ((scope.get("education_system") or {}).get("groups") or {}) if isinstance(scope, dict) else {}
    hubs = groups.get("common_transfer_hub") or (scope.get("average_by_unit") if isinstance(scope, dict) else []) or []
    return {
        "scope_label": scope.get("scope_label") if isinstance(scope, dict) else "",
        "score_summary": scope.get("score_summary") if isinstance(scope, dict) else {},
        "top_hubs": [item.get("unit_name") for item in hubs[:5] if isinstance(item, dict) and item.get("unit_name")],
    }


def _major_name_for_code(conn: sqlite3.Connection, major_code: str) -> str:
    row = conn.execute(
        """
        SELECT major_name
        FROM classifications
        WHERE major_code = ?
          AND TRIM(COALESCE(major_name, '')) <> ''
        ORDER BY major_name
        LIMIT 1
        """,
        (major_code,),
    ).fetchone()
    return str(row["major_name"]) if row and row["major_name"] is not None else major_code


def build_ontology_transferability_major_run(
    conn: sqlite3.Connection,
    *,
    out_dir: Path,
    date_stamp: str,
    major_codes: list[str] | None = None,
    artifact_prefix: str = "ontology_transferability_major",
    limit_scopes_per_major: int | None = None,
    min_units: int = 2,
    max_units_per_scope: int | None = None,
    top_pairs: int = 10,
    top_units: int = 12,
) -> dict[str, Any]:
    out_dir.mkdir(parents=True, exist_ok=True)
    selected_major_codes = major_codes or available_major_codes(conn)
    results: list[dict[str, Any]] = []
    started = time.perf_counter()
    for major_code in selected_major_codes:
        major_started = time.perf_counter()
        json_path = _ontology_major_artifact_path(out_dir, artifact_prefix, major_code, date_stamp, "json")
        markdown_path = _ontology_major_artifact_path(out_dir, artifact_prefix, major_code, date_stamp, "md")
        pair_csv_path = _ontology_major_artifact_path(out_dir, artifact_prefix, major_code, date_stamp, "pairs")
        result: dict[str, Any] = {
            "major_code": major_code,
            "major_name": _major_name_for_code(conn, major_code),
            "json_path": str(json_path),
            "markdown_path": str(markdown_path),
            "pair_csv_path": str(pair_csv_path),
        }
        try:
            report = build_ontology_adjusted_education_systems(
                conn,
                major_code=major_code,
                limit_scopes=limit_scopes_per_major,
                min_units=min_units,
                max_units_per_scope=max_units_per_scope,
                top_pairs=top_pairs,
                top_units=top_units,
            )
            write_ontology_transferability_pairs_csv(report, pair_csv_path)
            report.setdefault("summary", {})["pair_csv_available"] = True
            report["summary"]["pair_csv_path"] = str(pair_csv_path)
            write_ontology_transferability_json(report, json_path)
            write_ontology_transferability_markdown(report, markdown_path)
            result.update(
                {
                    "returncode": 0,
                    "seconds": round(time.perf_counter() - major_started, 3),
                    "summary": report.get("summary") or {},
                    "top_scope": _ontology_transferability_top_scope(report),
                }
            )
        except Exception as exc:  # pragma: no cover - exercised through failure manifests in downstream tools.
            result.update(
                {
                    "returncode": 1,
                    "seconds": round(time.perf_counter() - major_started, 3),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                    },
                }
            )
        results.append(result)
    ok = all(int(item.get("returncode") or 0) == 0 for item in results)
    return {
        "schema": MAJOR_RUN_SCHEMA_VERSION,
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "ok": ok,
        "result_count": len(results),
        "total_major_count": len(selected_major_codes),
        "seconds": round(time.perf_counter() - started, 3),
        "parameters": {
            "date_stamp": date_stamp,
            "artifact_prefix": artifact_prefix,
            "limit_scopes_per_major": limit_scopes_per_major,
            "min_units": min_units,
            "max_units_per_scope": max_units_per_scope,
            "top_pairs": top_pairs,
            "top_units": top_units,
            "role_overlay": "not_applied_in_batch_profiles",
        },
        "results": results,
    }


def write_ontology_transferability_major_run_markdown(report: dict[str, Any], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    results = report.get("results") or []
    completed = sum(1 for item in results if int(item.get("returncode") or 0) == 0)
    lines = [
        "# NCS Ontology Transferability Major Run",
        "",
        f"- Schema: `{report.get('schema')}`",
        f"- Generated at: `{report.get('generated_at')}`",
        f"- Completed majors: {completed} / {report.get('total_major_count')}",
        f"- OK: {report.get('ok')}",
        f"- Seconds: {report.get('seconds')}",
        "",
        "| Major | Name | Return | Seconds | Scopes | Units | Pairs | Top Scope |",
        "|---|---|---:|---:|---:|---:|---:|---|",
    ]
    for item in results:
        summary = item.get("summary") or {}
        top_scope = item.get("top_scope") or {}
        lines.append(
            "| {major} | {name} | {returncode} | {seconds} | {scopes} | {units} | {pairs} | {top_scope} |".format(
                major=item.get("major_code") or "",
                name=item.get("major_name") or "",
                returncode=item.get("returncode", ""),
                seconds=item.get("seconds", ""),
                scopes=summary.get("scope_count", ""),
                units=summary.get("unit_count", ""),
                pairs=summary.get("directed_pair_count", ""),
                top_scope=top_scope.get("scope_label") or "",
            )
        )
    failures = [item for item in results if int(item.get("returncode") or 0) != 0]
    if failures:
        lines.extend(["", "## Failures", ""])
        for item in failures:
            error = item.get("error") or {}
            lines.append(
                f"- `{item.get('major_code')}` {item.get('major_name')}: "
                f"{error.get('type') or 'Error'} - {error.get('message') or ''}"
            )
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def _dashboard_url(base_url: str, path: str) -> str:
    return base_url.rstrip("/") + "/" + path.lstrip("/")


def _http_exception_detail(exc: Exception) -> dict[str, Any]:
    if isinstance(exc, HTTPError):
        try:
            body = exc.read().decode("utf-8", errors="replace")
        except Exception:
            body = ""
        return {
            "error": "http_error",
            "status": exc.code,
            "reason": exc.reason,
            "body_preview": body[:1000],
        }
    if isinstance(exc, URLError):
        return {"error": "url_error", "reason": str(exc.reason)}
    return {"error": type(exc).__name__, "reason": str(exc)}


def _http_get_text(url: str, *, timeout: float) -> tuple[int, str]:
    with urlopen(url, timeout=timeout) as response:
        return int(getattr(response, "status", 200)), response.read().decode("utf-8", errors="replace")


def _http_get_json(url: str, *, timeout: float) -> tuple[int, dict[str, Any]]:
    status, body = _http_get_text(url, timeout=timeout)
    payload = json.loads(body)
    if not isinstance(payload, dict):
        raise ValueError(f"Expected JSON object from {url}.")
    return status, payload


def _http_post_json(url: str, payload: dict[str, Any], *, timeout: float) -> tuple[int, dict[str, Any]]:
    request = Request(
        url,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={"Content-Type": "application/json; charset=utf-8"},
        method="POST",
    )
    with urlopen(request, timeout=timeout) as response:
        data = json.loads(response.read().decode("utf-8", errors="replace"))
        if not isinstance(data, dict):
            raise ValueError(f"Expected JSON object from {url}.")
        return int(getattr(response, "status", 200)), data


def _check_result(name: str, ok: bool, detail: str, **extra: Any) -> dict[str, Any]:
    result = {"name": name, "ok": ok, "detail": detail}
    result.update(extra)
    return result


def _missing_aihr_matrix_fields(rows: list[Any]) -> list[str]:
    required_dict_fields = {
        "job_scope",
        "target_level_band",
        "education_type",
        "required_optional_basis",
        "delivery_operation",
        "planner_grouping",
        "task_ksa_basis",
        "course_link",
        "course_scope_fit",
        "facility_constraint_fit",
        "specificity_warning",
        "duplicate_or_generic_warning",
        "mapping_strength",
        "mapping_strength_warning",
        "decision_state",
        "evidence_chain",
        "human_review",
    }
    required_value_fields = {"required_optional"}
    required_course_fit_fields = {"level", "hours", "methods", "facilities"}
    required_task_ksa_fields = {
        "basis_types",
        "target_scope_ksa",
        "gap_ksa",
        "training_goal_ksa",
        "covered_elements",
    }
    required_facility_fit_fields = {
        "status",
        "requested",
        "available",
        "matched",
        "missing",
        "rationale",
    }
    required_human_review_fields = {"severity", "prompt", "action", "review_board_hint", "flags"}
    required_decision_state_fields = {
        "schema",
        "status",
        "decision_required",
        "system_suggestion",
        "allowed_decisions",
        "approval_claim",
        "message",
    }
    required_evidence_chain_fields = {"schema", "chain_order", "links", "completeness", "message"}
    required_course_link_fields = {
        "course_name",
        "training_course_id",
        "mapping_chain",
        "evidence_directness",
        "need_classification",
        "basis_types",
        "course_scope_fit",
        "why_recommended",
    }
    missing: list[str] = []
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, dict):
            missing.append(f"row_{index}:not_object")
            continue
        for field in sorted(required_dict_fields):
            if not isinstance(row.get(field), dict):
                missing.append(f"row_{index}:{field}")
        for field in sorted(required_value_fields):
            if row.get(field) in (None, ""):
                missing.append(f"row_{index}:{field}")
        task_ksa_basis = row.get("task_ksa_basis")
        if isinstance(task_ksa_basis, dict):
            for field in sorted(required_task_ksa_fields - set(task_ksa_basis)):
                missing.append(f"row_{index}:task_ksa_basis.{field}")
        course_link = row.get("course_link")
        if isinstance(course_link, dict):
            for field in sorted(required_course_link_fields - set(course_link)):
                missing.append(f"row_{index}:course_link.{field}")
        facility_fit = row.get("facility_constraint_fit")
        if isinstance(facility_fit, dict):
            for field in sorted(required_facility_fit_fields - set(facility_fit)):
                missing.append(f"row_{index}:facility_constraint_fit.{field}")
        human_review = row.get("human_review")
        if isinstance(human_review, dict):
            for field in sorted(required_human_review_fields - set(human_review)):
                missing.append(f"row_{index}:human_review.{field}")
        decision_state = row.get("decision_state")
        if isinstance(decision_state, dict):
            for field in sorted(required_decision_state_fields - set(decision_state)):
                missing.append(f"row_{index}:decision_state.{field}")
            if decision_state.get("schema") != "aihr_training_row_decision_state_v1":
                missing.append(f"row_{index}:decision_state.schema:{decision_state.get('schema')}")
            if decision_state.get("status") != "pending_human_decision":
                missing.append(f"row_{index}:decision_state.status:{decision_state.get('status')}")
            if decision_state.get("approval_claim") is not False:
                missing.append(f"row_{index}:decision_state.approval_claim")
        evidence_chain = row.get("evidence_chain")
        if isinstance(evidence_chain, dict):
            for field in sorted(required_evidence_chain_fields - set(evidence_chain)):
                missing.append(f"row_{index}:evidence_chain.{field}")
            if evidence_chain.get("schema") != "aihr_course_evidence_chain_v1":
                missing.append(f"row_{index}:evidence_chain.schema:{evidence_chain.get('schema')}")
            if not isinstance(evidence_chain.get("links"), list) or not evidence_chain.get("links"):
                missing.append(f"row_{index}:evidence_chain.links")
        course_fit = row.get("course_fit")
        if not isinstance(course_fit, dict):
            missing.append(f"row_{index}:course_fit")
            continue
        for field in sorted(required_course_fit_fields - set(course_fit)):
            missing.append(f"row_{index}:course_fit.{field}")
        facility_status = (
            str(facility_fit.get("status") or "")
            if isinstance(facility_fit, dict)
            else ""
        )
        allows_sparse_delivery = facility_status in {"unknown", "not_requested"}
        for field in sorted(required_course_fit_fields & set(course_fit)):
            value = course_fit.get(field)
            if field in {"methods", "facilities"}:
                if not isinstance(value, list):
                    missing.append(f"row_{index}:course_fit.{field}_value")
                elif not [item for item in value if str(item).strip()] and not allows_sparse_delivery:
                    missing.append(f"row_{index}:course_fit.{field}_value")
            elif value is None or value == "":
                missing.append(f"row_{index}:course_fit.{field}_value")
    return missing


def _missing_aihr_plan_fields(payload: dict[str, Any]) -> list[str]:
    scope_baseline = payload.get("scope_baseline")
    scope_missing: list[str] = []
    if not isinstance(scope_baseline, dict):
        scope_missing.append("scope_baseline")
    else:
        if scope_baseline.get("schema") != "aihr_scope_baseline_v1":
            scope_missing.append(f"scope_baseline.schema:{scope_baseline.get('schema')}")
        for field in (
            "guide_stage",
            "purpose",
            "current",
            "target",
            "ncs_scope_relation",
            "exact_ksa_overlap_ratio",
            "ontology_adjusted_transferability_ratio",
            "adjusted_transferability_components",
            "human_review",
        ):
            if field not in scope_baseline:
                scope_missing.append(f"scope_baseline.{field}")
        for role in ("current", "target"):
            entry = scope_baseline.get(role) if isinstance(scope_baseline.get(role), dict) else None
            if not isinstance(entry, dict):
                scope_missing.append(f"scope_baseline.{role}")
                continue
            for field in ("requested_query", "resolved_scope", "match_level", "unit_count", "scope_resolution_basis"):
                if field not in entry:
                    scope_missing.append(f"scope_baseline.{role}.{field}")
    annual_plan = payload.get("annual_operation_plan")
    if not isinstance(annual_plan, dict):
        scope_missing.append("annual_operation_plan")
    else:
        if annual_plan.get("schema") != "aihr_annual_operation_plan_seed_v1":
            scope_missing.append(f"annual_operation_plan.schema:{annual_plan.get('schema')}")
        for field in (
            "guide_stage",
            "status",
            "purpose",
            "target_population",
            "requested_constraints",
            "summary",
            "rows",
            "review_gate",
            "export_fields",
        ):
            if field not in annual_plan:
                scope_missing.append(f"annual_operation_plan.{field}")
        review_gate = (
            annual_plan.get("review_gate")
            if isinstance(annual_plan.get("review_gate"), dict)
            else {}
        )
        if review_gate.get("approval_claim") is not False:
            scope_missing.append("annual_operation_plan.review_gate.approval_claim")
        rows = annual_plan.get("rows")
        if not isinstance(rows, list):
            scope_missing.append("annual_operation_plan.rows")
        else:
            required_row_fields = {
                "sequence",
                "recommended_window",
                "phase",
                "course_name",
                "need_classification",
                "decision_status",
                "human_review_severity",
                "evidence_chain_status",
                "constraint_status",
                "review_flags",
                "scheduling_rationale",
            }
            for index, row in enumerate(rows, start=1):
                if not isinstance(row, dict):
                    scope_missing.append(f"annual_operation_plan.row_{index}")
                    continue
                for field in sorted(required_row_fields - set(row)):
                    scope_missing.append(f"annual_operation_plan.row_{index}.{field}")
    course_intake = payload.get("course_intake_requirements")
    if not isinstance(course_intake, dict):
        scope_missing.append("course_intake_requirements")
    else:
        if course_intake.get("schema") != "aihr_course_intake_requirements_v1":
            scope_missing.append(f"course_intake_requirements.schema:{course_intake.get('schema')}")
        for field in (
            "guide_stage",
            "status",
            "purpose",
            "target_population",
            "requested_constraints",
            "required_fields",
            "optional_fields",
            "mapping_policy",
            "prefill_from_recommendations",
            "review_gate",
        ):
            if field not in course_intake:
                scope_missing.append(f"course_intake_requirements.{field}")
        required_fields = course_intake.get("required_fields")
        if not isinstance(required_fields, list) or not required_fields:
            scope_missing.append("course_intake_requirements.required_fields")
        else:
            required_field_names = {
                "course_name",
                "course_goal",
                "target_learners",
                "content_outline",
                "ncs_scope_or_unit",
                "performance_criteria_or_task",
                "ksa_evidence",
                "level",
                "hours",
                "methods",
                "facilities",
                "assessment_method",
            }
            field_names = {
                str(item.get("field"))
                for item in required_fields
                if isinstance(item, dict) and item.get("field")
            }
            for field in sorted(required_field_names - field_names):
                scope_missing.append(f"course_intake_requirements.required_fields.{field}")
        mapping_policy = (
            course_intake.get("mapping_policy")
            if isinstance(course_intake.get("mapping_policy"), dict)
            else {}
        )
        if mapping_policy.get("title_only_mapping_allowed") is not False:
            scope_missing.append("course_intake_requirements.mapping_policy.title_only_mapping_allowed")
        if mapping_policy.get("framework_reference_is_not_scoring_source") is not True:
            scope_missing.append("course_intake_requirements.mapping_policy.framework_reference_is_not_scoring_source")
        if mapping_policy.get("human_review_required_before_approval") is not True:
            scope_missing.append("course_intake_requirements.mapping_policy.human_review_required_before_approval")
        review_gate = (
            course_intake.get("review_gate")
            if isinstance(course_intake.get("review_gate"), dict)
            else {}
        )
        if review_gate.get("approval_claim") is not False:
            scope_missing.append("course_intake_requirements.review_gate.approval_claim")
    inventory_template = payload.get("training_course_inventory_template")
    if not isinstance(inventory_template, dict):
        scope_missing.append("training_course_inventory_template")
    else:
        if inventory_template.get("schema") != "aihr_training_course_inventory_template_v1":
            scope_missing.append(
                f"training_course_inventory_template.schema:{inventory_template.get('schema')}"
            )
        for field in (
            "guide_stage",
            "status",
            "purpose",
            "target_population",
            "requested_constraints",
            "columns",
            "required_columns",
            "row_template",
            "prefill_rows",
            "validation_rules",
            "review_gate",
        ):
            if field not in inventory_template:
                scope_missing.append(f"training_course_inventory_template.{field}")
        expected_columns = {
            "source_type",
            "course_name",
            "course_goal",
            "target_learners",
            "content_outline",
            "ncs_scope_or_unit",
            "performance_criteria_or_task",
            "ksa_evidence",
            "level",
            "hours",
            "methods",
            "facilities",
            "education_type",
            "required_optional_basis",
            "assessment_method",
            "duplicate_or_generic_risk",
            "review_state",
        }
        columns = inventory_template.get("columns")
        if not isinstance(columns, list) or not columns:
            scope_missing.append("training_course_inventory_template.columns")
        else:
            column_names = {
                str(item.get("column"))
                for item in columns
                if isinstance(item, dict) and item.get("column")
            }
            for field in sorted(expected_columns - column_names):
                scope_missing.append(f"training_course_inventory_template.columns.{field}")
        required_columns = inventory_template.get("required_columns")
        if not isinstance(required_columns, list) or not required_columns:
            scope_missing.append("training_course_inventory_template.required_columns")
        else:
            for field in sorted(expected_columns - {str(item) for item in required_columns}):
                scope_missing.append(f"training_course_inventory_template.required_columns.{field}")
        review_gate = (
            inventory_template.get("review_gate")
            if isinstance(inventory_template.get("review_gate"), dict)
            else {}
        )
        if review_gate.get("approval_claim") is not False:
            scope_missing.append("training_course_inventory_template.review_gate.approval_claim")
    necessity_review = payload.get("training_necessity_review")
    if not isinstance(necessity_review, dict):
        scope_missing.append("training_necessity_review")
    else:
        if necessity_review.get("schema") != "aihr_training_necessity_review_v1":
            scope_missing.append(
                f"training_necessity_review.schema:{necessity_review.get('schema')}"
            )
        for field in (
            "guide_stage",
            "status",
            "purpose",
            "target_population",
            "requested_constraints",
            "review_dimensions",
            "summary",
            "rows",
            "validation_rules",
            "review_gate",
        ):
            if field not in necessity_review:
                scope_missing.append(f"training_necessity_review.{field}")
        summary = (
            necessity_review.get("summary")
            if isinstance(necessity_review.get("summary"), dict)
            else {}
        )
        for field in (
            "row_count",
            "review_required_rows",
            "approval_blocked_rows",
            "job_linkage_status_counts",
            "level_fit_status_counts",
            "delivery_feasibility_status_counts",
            "duplicate_or_generic_status_counts",
            "performance_contribution_status_counts",
            "required_optional_counts",
            "decision_state_counts",
        ):
            if field not in summary:
                scope_missing.append(f"training_necessity_review.summary.{field}")
        rows = necessity_review.get("rows")
        if not isinstance(rows, list):
            scope_missing.append("training_necessity_review.rows")
        else:
            required_row_fields = {
                "sequence",
                "course_name",
                "job_linkage",
                "level_fit",
                "required_optional_review",
                "duplicate_or_generic_review",
                "delivery_feasibility",
                "performance_contribution",
                "decision_state",
                "human_review",
                "review_flags",
                "recommended_review_action",
            }
            nested_required = {
                "job_linkage": {
                    "status",
                    "course_scope_relation",
                    "course_scope_alignment",
                    "evidence_directness",
                    "task_ksa_basis_counts",
                    "review_reason",
                },
                "level_fit": {"status", "target_level_band", "course_level", "review_reason"},
                "required_optional_review": {
                    "code",
                    "label",
                    "rationale",
                    "statutory_or_mandatory_basis",
                    "approval_claim",
                },
                "duplicate_or_generic_review": {
                    "status",
                    "codes",
                    "duplicate_or_generic_warning",
                    "specificity_warning",
                    "mapping_strength_warning",
                },
                "delivery_feasibility": {
                    "status",
                    "constraint_status",
                    "hours",
                    "methods",
                    "facilities",
                    "requested_constraints",
                    "constraint_fit",
                },
                "performance_contribution": {
                    "status",
                    "evidence_chain_status",
                    "gap_ksa",
                    "training_goal_ksa",
                    "covered_elements",
                    "review_reason",
                },
            }
            for index, row in enumerate(rows, start=1):
                if not isinstance(row, dict):
                    scope_missing.append(f"training_necessity_review.rows.row_{index}")
                    continue
                for field in sorted(required_row_fields - set(row)):
                    scope_missing.append(f"training_necessity_review.rows.row_{index}.{field}")
                for field, child_fields in nested_required.items():
                    child = row.get(field)
                    if not isinstance(child, dict):
                        scope_missing.append(f"training_necessity_review.rows.row_{index}.{field}")
                        continue
                    for child_field in sorted(child_fields - set(child)):
                        scope_missing.append(
                            f"training_necessity_review.rows.row_{index}.{field}.{child_field}"
                        )
                required_optional = row.get("required_optional_review")
                if isinstance(required_optional, dict) and required_optional.get("approval_claim") is not False:
                    scope_missing.append(
                        f"training_necessity_review.rows.row_{index}.required_optional_review.approval_claim"
                    )
        review_gate = (
            necessity_review.get("review_gate")
            if isinstance(necessity_review.get("review_gate"), dict)
            else {}
        )
        if review_gate.get("approval_claim") is not False:
            scope_missing.append("training_necessity_review.review_gate.approval_claim")
    path = payload.get("recommended_path")
    if not isinstance(path, list) or not path:
        return [*scope_missing, "recommended_path"]
    missing: list[str] = [*scope_missing]
    roles = set()
    guide_codes = set()
    for index, stage in enumerate(path, start=1):
        if not isinstance(stage, dict):
            missing.append(f"recommended_path.row_{index}")
            continue
        role = str(stage.get("role") or "")
        roles.add(role)
        guide_stage = str(stage.get("guide_stage") or "")
        if guide_stage:
            guide_codes.add(guide_stage)
        for field in ("stage", "role", "title", "guide_stage", "guide_stage_status"):
            if not stage.get(field):
                missing.append(f"recommended_path.row_{index}.{field}")
        if stage.get("guide_stage_status") not in {"ready", "needs_review"}:
            missing.append(
                f"recommended_path.row_{index}.guide_stage_status:{stage.get('guide_stage_status')}"
            )
        if not isinstance(stage.get("guide_stage_evidence"), dict):
            missing.append(f"recommended_path.row_{index}.guide_stage_evidence")
        expected_guide_stage = REQUIRED_AIHR_RECOMMENDED_PATH_GUIDE_STAGES.get(role)
        if expected_guide_stage and guide_stage != expected_guide_stage:
            missing.append(f"recommended_path.role.{role}.guide_stage:{guide_stage}")
    required_roles = set(REQUIRED_AIHR_RECOMMENDED_PATH_GUIDE_STAGES)
    for role in sorted(required_roles - roles):
        missing.append(f"recommended_path.role.{role}")
    for code in sorted(set(REQUIRED_AIHR_RECOMMENDED_PATH_GUIDE_STAGES.values()) - guide_codes):
        missing.append(f"recommended_path.guide_stage.{code}")
    return missing


