def _missing_aihr_guide_trace_fields(payload: dict[str, Any]) -> list[str]:
    trace = payload.get("training_system_guide_trace")
    if not isinstance(trace, dict):
        return ["training_system_guide_trace"]
    missing: list[str] = []
    if trace.get("schema") != AIHR_TRAINING_SYSTEM_GUIDE_TRACE_SCHEMA:
        missing.append("training_system_guide_trace.schema")
    for field in (
        "rubric_source",
        "rubric_role",
        "non_source_data_policy",
        "matrix_reconstruction_fields",
        "guide_workflow_stages",
    ):
        if field not in trace:
            missing.append(f"training_system_guide_trace.{field}")
    stages = trace.get("guide_workflow_stages")
    if not isinstance(stages, list) or not stages:
        workflow = trace.get("guide_workflow") if isinstance(trace.get("guide_workflow"), dict) else {}
        stages = workflow.get("steps") if isinstance(workflow.get("steps"), list) else []
    if not stages:
        missing.append("training_system_guide_trace.guide_workflow_stages")
    else:
        stage_codes = {
            str(item.get("code"))
            for item in stages
            if isinstance(item, dict) and item.get("code")
        }
        for code in sorted(REQUIRED_AIHR_GUIDE_WORKFLOW_STAGE_CODES - stage_codes):
            missing.append(f"training_system_guide_trace.guide_workflow_stages.{code}")
        for index, item in enumerate(stages, start=1):
            if not isinstance(item, dict):
                missing.append(f"training_system_guide_trace.guide_workflow_stages.row_{index}")
                continue
            for field in ("code", "title", "status", "evidence"):
                if field not in item:
                    missing.append(f"training_system_guide_trace.guide_workflow_stages.row_{index}.{field}")
            if item.get("status") not in {"ready", "needs_review"}:
                missing.append(
                    f"training_system_guide_trace.guide_workflow_stages.row_{index}.status:{item.get('status')}"
                )
    checks = trace.get("checks")
    if not isinstance(checks, list) or not checks:
        missing.append("training_system_guide_trace.checks")
        return missing
    codes = {
        str(item.get("code"))
        for item in checks
        if isinstance(item, dict) and item.get("code")
    }
    for code in sorted(REQUIRED_AIHR_GUIDE_TRACE_CODES - codes):
        missing.append(f"training_system_guide_trace.checks.{code}")
    for index, item in enumerate(checks, start=1):
        if not isinstance(item, dict):
            missing.append(f"training_system_guide_trace.checks.row_{index}")
            continue
        for field in ("code", "label", "status", "evidence"):
            if field not in item:
                missing.append(f"training_system_guide_trace.checks.row_{index}.{field}")
        if item.get("status") not in {"ready", "needs_review"}:
            missing.append(f"training_system_guide_trace.checks.row_{index}.status:{item.get('status')}")
    return missing


def _missing_aihr_query_route_fields(payload: dict[str, Any]) -> list[str]:
    route = payload.get("query_route")
    if not isinstance(route, dict):
        return ["query_route"]
    missing: list[str] = []
    if route.get("schema") != QUERY_ROUTE_SCHEMA:
        missing.append("query_route.schema")
    if route.get("scenario") != "education_system_design":
        missing.append(f"query_route.scenario:{route.get('scenario')}")
    if route.get("tool") != PLAN_NCS_EDUCATION_PATH_TOOL:
        missing.append(f"query_route.tool:{route.get('tool')}")
    if route.get("available") is not True:
        missing.append(f"query_route.available:{route.get('available')}")
    if not route.get("route_fingerprint"):
        missing.append("query_route.route_fingerprint")
    if "guard_flags" not in route or not isinstance(route.get("guard_flags"), list):
        missing.append("query_route.guard_flags")
    expected_chain = route.get("expected_tool_chain")
    if not isinstance(expected_chain, list) or PLAN_NCS_EDUCATION_PATH_TOOL not in expected_chain:
        missing.append(f"query_route.expected_tool_chain.{PLAN_NCS_EDUCATION_PATH_TOOL}")
    if not isinstance(expected_chain, list) or "recommend_training_transition" not in expected_chain:
        missing.append("query_route.expected_tool_chain.recommend_training_transition")
    route_contract = route.get("route_contract")
    if not isinstance(route_contract, dict):
        missing.append("query_route.route_contract")
    else:
        if route_contract.get("schema") != QUERY_ROUTE_SCHEMA:
            missing.append("query_route.route_contract.schema")
        if route_contract.get("route_first") is not True:
            missing.append("query_route.route_contract.route_first")
        if route_contract.get("primary_tool") != route.get("tool"):
            missing.append("query_route.route_contract.primary_tool")
        if route_contract.get("route_fingerprint") != route.get("route_fingerprint"):
            missing.append("query_route.route_contract.route_fingerprint")
    return missing


def _merge_count_maps(*maps: Any) -> dict[str, int]:
    merged: dict[str, int] = {}
    for mapping in maps:
        if not isinstance(mapping, dict):
            continue
        for key, value in mapping.items():
            label = str(key or "unknown")
            try:
                amount = int(value)
            except (TypeError, ValueError):
                amount = 0
            merged[label] = merged.get(label, 0) + amount
    return merged


def _count_training_necessity_actions(rows: Any) -> dict[str, int]:
    counts: dict[str, int] = {}
    if not isinstance(rows, list):
        return counts
    for row in rows:
        if not isinstance(row, dict):
            continue
        label = str(row.get("recommended_review_action") or "unknown")
        counts[label] = counts.get(label, 0) + 1
    return counts


def _training_necessity_review_summary(payload: dict[str, Any]) -> dict[str, Any]:
    review = (
        payload.get("training_necessity_review")
        if isinstance(payload.get("training_necessity_review"), dict)
        else {}
    )
    summary = review.get("summary") if isinstance(review.get("summary"), dict) else {}
    gate = review.get("review_gate") if isinstance(review.get("review_gate"), dict) else {}
    rows = review.get("rows") if isinstance(review.get("rows"), list) else []
    row_approval_claims = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        required_optional = (
            row.get("required_optional_review")
            if isinstance(row.get("required_optional_review"), dict)
            else {}
        )
        decision_state = (
            row.get("decision_state")
            if isinstance(row.get("decision_state"), dict)
            else {}
        )
        row_approval_claims.append(required_optional.get("approval_claim"))
        row_approval_claims.append(decision_state.get("approval_claim"))
    unsafe_claims = [claim for claim in row_approval_claims if claim is not False]
    return {
        "schema": review.get("schema"),
        "guide_stage": review.get("guide_stage"),
        "status": review.get("status"),
        "row_count": summary.get("row_count", len(rows)),
        "review_required_rows": summary.get("review_required_rows"),
        "approval_blocked_rows": summary.get("approval_blocked_rows"),
        "job_linkage_status_counts": summary.get("job_linkage_status_counts") or {},
        "level_fit_status_counts": summary.get("level_fit_status_counts") or {},
        "delivery_feasibility_status_counts": summary.get("delivery_feasibility_status_counts") or {},
        "duplicate_or_generic_status_counts": summary.get("duplicate_or_generic_status_counts") or {},
        "performance_contribution_status_counts": summary.get("performance_contribution_status_counts") or {},
        "required_optional_counts": summary.get("required_optional_counts") or {},
        "decision_state_counts": summary.get("decision_state_counts") or {},
        "recommended_review_action_counts": _count_training_necessity_actions(rows),
        "review_gate_status": gate.get("status"),
        "approval_claim": gate.get("approval_claim"),
        "approval_claim_safe": gate.get("approval_claim") is False and not unsafe_claims,
        "unsafe_row_approval_claim_count": len(unsafe_claims),
    }


def _annual_operation_plan_summary(payload: dict[str, Any]) -> dict[str, Any]:
    plan = (
        payload.get("annual_operation_plan")
        if isinstance(payload.get("annual_operation_plan"), dict)
        else {}
    )
    summary = plan.get("summary") if isinstance(plan.get("summary"), dict) else {}
    gate = plan.get("review_gate") if isinstance(plan.get("review_gate"), dict) else {}
    rows = plan.get("rows") if isinstance(plan.get("rows"), list) else []
    return {
        "schema": plan.get("schema"),
        "guide_stage": plan.get("guide_stage"),
        "status": plan.get("status"),
        "row_count": summary.get("row_count", len(rows)),
        "estimated_total_hours": summary.get("estimated_total_hours"),
        "hours_known_count": summary.get("hours_known_count"),
        "pending_human_decision_rows": summary.get("pending_human_decision_rows"),
        "review_required_rows": summary.get("review_required_rows"),
        "window_counts": _count_training_necessity_actions(
            [{"recommended_review_action": row.get("recommended_window")} for row in rows if isinstance(row, dict)]
        ),
        "phase_counts": _count_training_necessity_actions(
            [{"recommended_review_action": row.get("phase")} for row in rows if isinstance(row, dict)]
        ),
        "decision_status_counts": _count_training_necessity_actions(
            [{"recommended_review_action": row.get("decision_status")} for row in rows if isinstance(row, dict)]
        ),
        "constraint_status_counts": _count_training_necessity_actions(
            [{"recommended_review_action": row.get("constraint_status")} for row in rows if isinstance(row, dict)]
        ),
        "human_review_severity_counts": _count_training_necessity_actions(
            [{"recommended_review_action": row.get("human_review_severity")} for row in rows if isinstance(row, dict)]
        ),
        "review_gate_status": gate.get("status"),
        "approval_claim": gate.get("approval_claim"),
        "approval_claim_safe": gate.get("approval_claim") is False,
    }


def _as_int(value: Any) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def build_training_necessity_review_audit_from_files(paths: list[Path]) -> dict[str, Any]:
    artifact_summaries: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []
    aggregate: dict[str, Any] = {
        "artifact_count": 0,
        "row_count": 0,
        "review_required_rows": 0,
        "approval_blocked_rows": 0,
        "unsafe_row_approval_claim_count": 0,
        "job_linkage_status_counts": {},
        "level_fit_status_counts": {},
        "delivery_feasibility_status_counts": {},
        "duplicate_or_generic_status_counts": {},
        "performance_contribution_status_counts": {},
        "required_optional_counts": {},
        "decision_state_counts": {},
        "recommended_review_action_counts": {},
    }
    for path in paths:
        item: dict[str, Any] = {"path": str(path)}
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            item.update({"ok": False, "error": "file_not_found"})
            findings.append(
                {
                    "severity": "blocker",
                    "code": "artifact_missing",
                    "path": str(path),
                    "message": "Demo JSON artifact is missing.",
                }
            )
            artifact_summaries.append(item)
            continue
        except json.JSONDecodeError as exc:
            item.update({"ok": False, "error": "invalid_json", "detail": str(exc)})
            findings.append(
                {
                    "severity": "blocker",
                    "code": "artifact_invalid_json",
                    "path": str(path),
                    "message": "Demo JSON artifact could not be parsed.",
                }
            )
            artifact_summaries.append(item)
            continue
        if not isinstance(payload, dict):
            item.update({"ok": False, "error": "invalid_payload_type"})
            findings.append(
                {
                    "severity": "blocker",
                    "code": "artifact_invalid_payload",
                    "path": str(path),
                    "message": "Demo JSON artifact must contain an object payload.",
                }
            )
            artifact_summaries.append(item)
            continue
        missing_review_fields = [
            field
            for field in _missing_aihr_plan_fields(payload)
            if field.startswith("training_necessity_review")
        ]
        summary = _training_necessity_review_summary(payload)
        item.update(
            {
                "ok": not missing_review_fields and summary.get("approval_claim_safe") is True,
                "public_demo_schema": payload.get("public_demo_schema"),
                "view": payload.get("view"),
                "training_necessity_review": summary,
                "missing_training_necessity_review_fields": missing_review_fields,
            }
        )
        if missing_review_fields:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "training_necessity_review_contract_missing",
                    "path": str(path),
                    "message": "Training necessity review contract fields are missing.",
                    "fields": missing_review_fields[:20],
                }
            )
        if summary.get("approval_claim_safe") is not True:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "approval_claim_not_safe",
                    "path": str(path),
                    "message": "Automation must not claim the course list or rows are approved.",
                    "approval_claim": summary.get("approval_claim"),
                    "unsafe_row_approval_claim_count": summary.get("unsafe_row_approval_claim_count"),
                }
            )
        review_required = _as_int(summary.get("review_required_rows"))
        approval_blocked = _as_int(summary.get("approval_blocked_rows"))
        if review_required:
            findings.append(
                {
                    "severity": "review",
                    "code": "human_review_required_rows",
                    "path": str(path),
                    "message": "Rows remain gated for C1-2 human necessity review.",
                    "row_count": review_required,
                }
            )
        if approval_blocked:
            findings.append(
                {
                    "severity": "review",
                    "code": "human_confirmation_blocks_approval",
                    "path": str(path),
                    "message": "Rows are not approved until human confirmation is recorded outside this artifact.",
                    "row_count": approval_blocked,
                }
            )
        job_counts = summary.get("job_linkage_status_counts") or {}
        delivery_counts = summary.get("delivery_feasibility_status_counts") or {}
        duplicate_counts = summary.get("duplicate_or_generic_status_counts") or {}
        if _as_int(job_counts.get("needs_review")):
            findings.append(
                {
                    "severity": "review",
                    "code": "job_linkage_needs_review",
                    "path": str(path),
                    "message": "Some rows need job/task/KSA linkage confirmation.",
                    "counts": job_counts,
                }
            )
        if _as_int(delivery_counts.get("needs_review")):
            findings.append(
                {
                    "severity": "review",
                    "code": "delivery_feasibility_needs_review",
                    "path": str(path),
                    "message": "Some rows need delivery, hour, method, or facility confirmation.",
                    "counts": delivery_counts,
                }
            )
        duplicate_attention = {
            key: value for key, value in duplicate_counts.items() if key != "clear"
        }
        if duplicate_attention:
            findings.append(
                {
                    "severity": "review",
                    "code": "duplicate_or_generic_attention",
                    "path": str(path),
                    "message": "Some rows carry duplicate, generic, specificity, or mapping-strength warnings.",
                    "counts": duplicate_counts,
                }
            )
        artifact_summaries.append(item)
        aggregate["artifact_count"] += 1
        aggregate["row_count"] += _as_int(summary.get("row_count"))
        aggregate["review_required_rows"] += review_required
        aggregate["approval_blocked_rows"] += approval_blocked
        aggregate["unsafe_row_approval_claim_count"] += _as_int(
            summary.get("unsafe_row_approval_claim_count")
        )
        for key in (
            "job_linkage_status_counts",
            "level_fit_status_counts",
            "delivery_feasibility_status_counts",
            "duplicate_or_generic_status_counts",
            "performance_contribution_status_counts",
            "required_optional_counts",
            "decision_state_counts",
            "recommended_review_action_counts",
        ):
            aggregate[key] = _merge_count_maps(aggregate.get(key), summary.get(key))
    if not paths:
        findings.append(
            {
                "severity": "blocker",
                "code": "no_artifacts_supplied",
                "message": "At least one AI-HR public demo JSON artifact is required.",
            }
        )
    blocker_count = sum(1 for item in findings if item.get("severity") == "blocker")
    return {
        "ok": blocker_count == 0,
        "schema": "aihr_training_necessity_review_audit_v1",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "source_artifacts": [str(path) for path in paths],
        "aggregate": aggregate,
        "artifacts": artifact_summaries,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for item in findings if item.get("severity") == "review"),
        "review_policy": {
            "approval_claim": False,
            "db_writes": False,
            "human_decision_required_for_approval": True,
            "guide_role": "framework_reference",
        },
    }


def write_training_necessity_review_audit_markdown(report: dict[str, Any], out_path: Path) -> None:
    aggregate = report.get("aggregate") if isinstance(report.get("aggregate"), dict) else {}
    lines = [
        "# AI-HR Training Necessity Review Audit",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- blocker_count: {report.get('blocker_count')}",
        f"- review_finding_count: {report.get('review_finding_count')}",
        "",
        "## Aggregate",
        "",
        f"- artifact_count: {aggregate.get('artifact_count')}",
        f"- row_count: {aggregate.get('row_count')}",
        f"- review_required_rows: {aggregate.get('review_required_rows')}",
        f"- approval_blocked_rows: {aggregate.get('approval_blocked_rows')}",
        f"- unsafe_row_approval_claim_count: {aggregate.get('unsafe_row_approval_claim_count')}",
        f"- job_linkage_status_counts: {aggregate.get('job_linkage_status_counts')}",
        f"- delivery_feasibility_status_counts: {aggregate.get('delivery_feasibility_status_counts')}",
        f"- duplicate_or_generic_status_counts: {aggregate.get('duplicate_or_generic_status_counts')}",
        f"- decision_state_counts: {aggregate.get('decision_state_counts')}",
        f"- recommended_review_action_counts: {aggregate.get('recommended_review_action_counts')}",
        "",
        "## Artifacts",
        "",
    ]
    for item in report.get("artifacts") or []:
        summary = item.get("training_necessity_review") if isinstance(item, dict) else {}
        if not isinstance(summary, dict):
            summary = {}
        lines.append(
            "- "
            f"{item.get('path')}: ok={item.get('ok')}, "
            f"schema={summary.get('schema')}, "
            f"rows={summary.get('row_count')}, "
            f"review_required={summary.get('review_required_rows')}, "
            f"approval_blocked={summary.get('approval_blocked_rows')}, "
            f"approval_claim_safe={summary.get('approval_claim_safe')}, "
            f"missing={item.get('missing_training_necessity_review_fields')}"
        )
    lines.extend(["", "## Findings", ""])
    for finding in report.get("findings") or []:
        lines.append(
            "- "
            f"{finding.get('severity')}:{finding.get('code')} "
            f"{finding.get('message')} "
            f"path={finding.get('path')}"
        )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            f"- approval_claim: {policy.get('approval_claim')}",
            f"- db_writes: {policy.get('db_writes')}",
            f"- human_decision_required_for_approval: {policy.get('human_decision_required_for_approval')}",
            f"- guide_role: {policy.get('guide_role')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


_HANGUL_RE = re.compile(r"[\uac00-\ud7a3]")
_MOJIBAKE_RE = re.compile(
    r"\?{3,}|\ufffd|[筌野吏紐李怨]|"
    r"(?:\?[가-힣])|(?:[가-힣]\?)|(?:\?[^\s|,.:;)\]}]{1,6})"
)


def _text_readability_state(value: Any) -> str:
    if value is None:
        return "missing"
    text = str(value).strip()
    if not text:
        return "empty"
    has_hangul = bool(_HANGUL_RE.search(text))
    has_mojibake = bool(_MOJIBAKE_RE.search(text))
    if has_hangul and not has_mojibake:
        return "readable_korean"
    if has_mojibake:
        return "mojibake_or_placeholder"
    return "ascii_or_code"


def _text_is_readable_display(value: Any) -> bool:
    return _text_readability_state(value) in {"readable_korean", "ascii_or_code"}


def _career_path_display_rows(
    conn: sqlite3.Connection,
    career_path_ids: list[int],
) -> dict[int, dict[str, Any]]:
    if not career_path_ids:
        return {}
    placeholders = ",".join("?" for _ in career_path_ids)
    query = f"""
        SELECT
            cp.career_path_id,
            cp.job_name,
            cp.competency_name,
            cp.position_name,
            cp.competency_level_raw,
            cp.position_level_raw,
            cp.matched_unit_code,
            cp.review_status,
            cu.unit_name_refined,
            cu.api_unit_name,
            cu.unit_name_raw,
            cu.unit_level_raw,
            cu.api_unit_level,
            cl.major_code,
            cl.middle_code,
            cl.small_code,
            cl.sub_code,
            cl.major_name,
            cl.middle_name,
            cl.small_name,
            cl.sub_name
        FROM ncs_career_paths cp
        LEFT JOIN competency_units cu
          ON cu.unit_code = cp.matched_unit_code
        LEFT JOIN classifications cl
          ON cl.classification_id = cp.matched_classification_id
        WHERE cp.career_path_id IN ({placeholders})
    """
    rows: dict[int, dict[str, Any]] = {}
    for row in conn.execute(query, career_path_ids):
        rows[int(row["career_path_id"])] = dict(row)
    return rows


def _source_field_states(row: dict[str, Any], field_names: list[str]) -> dict[str, str]:
    return {field: _text_readability_state(row.get(field)) for field in field_names}


def _source_metadata_fields(payload: dict[str, Any]) -> dict[str, Any]:
    fields: dict[str, Any] = {}
    scope = payload.get("scope") if isinstance(payload.get("scope"), dict) else {}
    if scope:
        fields["scope.scope_name"] = scope.get("scope_name")
    provenance = (
        payload.get("human_decision_provenance")
        if isinstance(payload.get("human_decision_provenance"), dict)
        else {}
    )
    if provenance:
        fields["human_decision_provenance.instruction_summary"] = provenance.get(
            "instruction_summary"
        )
        fields["human_decision_provenance.scope_limit"] = provenance.get("scope_limit")
    for index, source in enumerate(payload.get("evidence_sources") or [], start=1):
        if not isinstance(source, dict):
            continue
        if source.get("evidence"):
            fields[f"evidence_sources[{index}].evidence"] = source.get("evidence")
    return fields


def _display_scope_from_rows(rows: dict[int, dict[str, Any]]) -> dict[str, Any]:
    first = next((row for row in rows.values() if row.get("major_code")), None)
    if first:
        sub_names = list(
            dict.fromkeys(
                str(row.get("sub_name"))
                for row in rows.values()
                if row.get("sub_name")
            )
        )
        sub_codes = list(
            dict.fromkeys(
                str(row.get("sub_code"))
                for row in rows.values()
                if row.get("sub_code")
            )
        )
        names = [
            first.get("major_name"),
            first.get("middle_name"),
            first.get("small_name"),
            " / ".join(sub_names),
        ]
        return {
            "major_code": first.get("major_code"),
            "middle_code": first.get("middle_code"),
            "small_code": first.get("small_code"),
            "sub_codes": sub_codes,
            "scope_name": " > ".join(str(name) for name in names if name),
        }
    return {}


def build_human_review_display_integrity_audit(
    source_report_path: Path,
    db_path: Path,
) -> dict[str, Any]:
    try:
        payload = json.loads(source_report_path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return {
            "ok": False,
            "schema": "aihr_human_review_display_integrity_v1",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "source_report_path": _aihr_public_path_text(source_report_path),
            "findings": [
                {
                    "severity": "blocker",
                    "code": "source_report_missing",
                    "message": "Source human-review JSON artifact is missing.",
                }
            ],
            "blocker_count": 1,
            "review_finding_count": 0,
            "review_policy": {
                "db_writes": False,
                "approval_claim": False,
                "active_scoring_source": False,
                "review_only": True,
                "non_scoring": True,
                "status_update_allowed": False,
                "human_decision_required_for_approval": True,
            },
            "approval_claim": False,
            "db_writes": False,
            "active_scoring_source": False,
            "review_only": True,
            "non_scoring": True,
            "status_update_allowed": False,
        }
    except json.JSONDecodeError as exc:
        return {
            "ok": False,
            "schema": "aihr_human_review_display_integrity_v1",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "source_report_path": _aihr_public_path_text(source_report_path),
            "findings": [
                {
                    "severity": "blocker",
                    "code": "source_report_invalid_json",
                    "message": "Source human-review JSON artifact could not be parsed.",
                    "detail": str(exc),
                }
            ],
            "blocker_count": 1,
            "review_finding_count": 0,
            "review_policy": {
                "db_writes": False,
                "approval_claim": False,
                "active_scoring_source": False,
                "review_only": True,
                "non_scoring": True,
                "status_update_allowed": False,
                "human_decision_required_for_approval": True,
            },
            "approval_claim": False,
            "db_writes": False,
            "active_scoring_source": False,
            "review_only": True,
            "non_scoring": True,
            "status_update_allowed": False,
        }
    if not isinstance(payload, dict):
        return {
            "ok": False,
            "schema": "aihr_human_review_display_integrity_v1",
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "source_report_path": _aihr_public_path_text(source_report_path),
            "findings": [
                {
                    "severity": "blocker",
                    "code": "source_report_invalid_payload",
                    "message": "Source human-review JSON artifact must contain an object.",
                }
            ],
            "blocker_count": 1,
            "review_finding_count": 0,
            "review_policy": {
                "db_writes": False,
                "approval_claim": False,
                "active_scoring_source": False,
                "review_only": True,
                "non_scoring": True,
                "status_update_allowed": False,
                "human_decision_required_for_approval": True,
            },
            "approval_claim": False,
            "db_writes": False,
            "active_scoring_source": False,
            "review_only": True,
            "non_scoring": True,
            "status_update_allowed": False,
        }

    source_rows = [row for row in payload.get("rows") or [] if isinstance(row, dict)]
    source_metadata = _source_metadata_fields(payload)
    source_metadata_states = {
        field: _text_readability_state(value)
        for field, value in source_metadata.items()
    }
    source_metadata_mojibake_fields = [
        field
        for field, state in source_metadata_states.items()
        if state == "mojibake_or_placeholder"
    ]
    career_path_ids = [
        int(row["career_path_id"])
        for row in source_rows
        if str(row.get("career_path_id") or "").isdigit()
    ]
    conn = _connect_readonly_sqlite(db_path)
    try:
        db_rows = _career_path_display_rows(conn, career_path_ids)
    finally:
        conn.close()

    display_rows: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []
    source_row_mojibake_field_count = 0
    display_not_ready_count = 0
    missing_db_row_count = 0
    field_names = [
        "job_name",
        "competency_name",
        "canonical_unit_name",
        "position_name",
        "source_file",
    ]
    for row in source_rows:
        career_path_id = row.get("career_path_id")
        try:
            row_id = int(career_path_id)
        except (TypeError, ValueError):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "career_path_id_missing",
                    "message": "A source row is missing a numeric career_path_id.",
                    "row": career_path_id,
                }
            )
            continue
        source_states = _source_field_states(row, field_names)
        source_mojibake_fields = [
            field
            for field, state in source_states.items()
            if state == "mojibake_or_placeholder"
        ]
        source_row_mojibake_field_count += len(source_mojibake_fields)
        db_row = db_rows.get(row_id)
        if not db_row:
            missing_db_row_count += 1
            findings.append(
                {
                    "severity": "blocker",
                    "code": "career_path_db_row_missing",
                    "message": "A source review row has no matching current DB career-path row.",
                    "career_path_id": row_id,
                }
            )
            continue
        display_unit_name = (
            db_row.get("unit_name_refined")
            or db_row.get("api_unit_name")
            or db_row.get("unit_name_raw")
            or db_row.get("competency_name")
        )
        display_fields = {
            "job_name": db_row.get("job_name"),
            "competency_name": db_row.get("competency_name"),
            "matched_unit_name": display_unit_name,
            "position_name": db_row.get("position_name"),
            "scope_name": " > ".join(
                str(value)
                for value in (
                    db_row.get("major_name"),
                    db_row.get("middle_name"),
                    db_row.get("small_name"),
                    db_row.get("sub_name"),
                )
                if value
            ),
        }
        display_states = _source_field_states(display_fields, list(display_fields))
        display_ready = all(
            _text_is_readable_display(display_fields.get(field))
            for field in ("job_name", "competency_name", "matched_unit_name")
        )
        if not display_ready:
            display_not_ready_count += 1
            findings.append(
                {
                    "severity": "blocker",
                    "code": "display_row_not_readable",
                    "message": "Current DB display fallback is not human-readable for a review row.",
                    "career_path_id": row_id,
                    "display_field_states": display_states,
                }
            )
        display_rows.append(
            {
                "career_path_id": row_id,
                "display_job_name": display_fields["job_name"],
                "display_competency_name": display_fields["competency_name"],
                "display_matched_unit_name": display_fields["matched_unit_name"],
                "display_position_name": display_fields["position_name"],
                "display_scope_name": display_fields["scope_name"],
                "matched_unit_code": db_row.get("matched_unit_code"),
                "competency_level": db_row.get("competency_level_raw"),
                "position_level": db_row.get("position_level_raw"),
                "unit_level": db_row.get("api_unit_level") or db_row.get("unit_level_raw"),
                "source_status_display": (
                    "proposed_status_present"
                    if row.get("proposed_review_status")
                    else "no_source_status"
                ),
                "current_db_status_display": (
                    "status_present"
                    if db_row.get("review_status")
                    else "no_db_status"
                ),
                "source_proposed_review_status_suppressed": bool(
                    row.get("proposed_review_status")
                ),
                "current_db_review_status_suppressed": bool(db_row.get("review_status")),
                "review_reason": row.get("review_reason"),
                "source_field_states": source_states,
                "source_mojibake_fields": source_mojibake_fields,
                "display_field_states": display_states,
                "display_ready": display_ready,
                "display_source": "current_sqlite_ncs_career_paths_and_canonical_unit",
            }
        )

    source_mojibake_field_count = (
        source_row_mojibake_field_count + len(source_metadata_mojibake_fields)
    )
    if source_mojibake_field_count:
        findings.append(
            {
                "severity": "review",
                "code": "source_report_contains_mojibake",
                "message": "The source JSON preserves some broken source text; use display_* fields for human review.",
                "field_count": source_mojibake_field_count,
                "metadata_fields": source_metadata_mojibake_fields,
            }
        )
    source_scope = payload.get("scope") if isinstance(payload.get("scope"), dict) else {}
    display_scope = _display_scope_from_rows(db_rows)
    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    return {
        "ok": blocker_count == 0,
        "schema": "aihr_human_review_display_integrity_v1",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "source_report_path": _aihr_public_path_text(source_report_path),
        "source_database_ref": AIHR_PUBLIC_DATABASE_REF,
        "source_schema": payload.get("schema"),
        "source_scope": source_scope,
        "display_scope": display_scope,
        "summary": {
            "row_count": len(source_rows),
            "display_row_count": len(display_rows),
            "display_ready_count": sum(1 for row in display_rows if row.get("display_ready")),
            "display_not_ready_count": display_not_ready_count,
            "missing_db_row_count": missing_db_row_count,
            "source_mojibake_field_count": source_mojibake_field_count,
            "source_row_mojibake_field_count": source_row_mojibake_field_count,
            "source_metadata_mojibake_field_count": len(source_metadata_mojibake_fields),
            "source_artifact_needs_regeneration": source_mojibake_field_count > 0,
            "db_writes": False,
            "approval_claim": False,
            "active_scoring_source": False,
            "review_only": True,
            "non_scoring": True,
            "status_update_allowed": False,
        },
        "source_metadata_field_states": source_metadata_states,
        "source_metadata_mojibake_fields": source_metadata_mojibake_fields,
        "display_rows": display_rows,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
        "review_policy": {
            "db_writes": False,
            "approval_claim": False,
            "active_scoring_source": False,
            "review_only": True,
            "non_scoring": True,
            "status_update_allowed": False,
            "source_values_preserved": True,
            "display_fields_are_review_surface": True,
            "human_decision_required_for_approval": True,
        },
        "approval_claim": False,
        "db_writes": False,
        "active_scoring_source": False,
        "review_only": True,
        "non_scoring": True,
        "status_update_allowed": False,
    }


def write_human_review_display_integrity_markdown(
    report: dict[str, Any],
    out_path: Path,
) -> None:
    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    display_scope = (
        report.get("display_scope") if isinstance(report.get("display_scope"), dict) else {}
    )
    lines = [
        "# AI-HR Human Review Display Integrity Audit",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- source_report_path: {report.get('source_report_path')}",
        f"- source_database_ref: {report.get('source_database_ref')}",
        f"- row_count: {summary.get('row_count')}",
        f"- display_ready_count: {summary.get('display_ready_count')}",
        f"- display_not_ready_count: {summary.get('display_not_ready_count')}",
        f"- missing_db_row_count: {summary.get('missing_db_row_count')}",
        f"- source_mojibake_field_count: {summary.get('source_mojibake_field_count')}",
        f"- source_row_mojibake_field_count: {summary.get('source_row_mojibake_field_count')}",
        f"- source_metadata_mojibake_field_count: {summary.get('source_metadata_mojibake_field_count')}",
        f"- source_artifact_needs_regeneration: {summary.get('source_artifact_needs_regeneration')}",
        f"- approval_claim: {summary.get('approval_claim')}",
        f"- db_writes: {summary.get('db_writes')}",
        f"- active_scoring_source: {summary.get('active_scoring_source')}",
        f"- review_only: {summary.get('review_only')}",
        f"- non_scoring: {summary.get('non_scoring')}",
        f"- status_update_allowed: {summary.get('status_update_allowed')}",
        "",
        "## Display Scope",
        "",
        f"- code: {display_scope.get('major_code')}-{display_scope.get('middle_code')}-{display_scope.get('small_code')}-{display_scope.get('sub_code')}",
        f"- name: {display_scope.get('scope_name')}",
        "",
        "## Source Metadata Readability",
        "",
        f"- mojibake_fields: {report.get('source_metadata_mojibake_fields')}",
        "",
        "## Display Rows",
        "",
        "| id | job | competency | matched unit | source status display | current DB status display | display ready | source warnings |",
        "|---:|---|---|---|---|---|---|---|",
    ]
    for row in report.get("display_rows") or []:
        warnings = ", ".join(row.get("source_mojibake_fields") or [])
        lines.append(
            "| "
            f"{row.get('career_path_id')} | "
            f"{row.get('display_job_name')} | "
            f"{row.get('display_competency_name')} | "
            f"{row.get('display_matched_unit_name')} | "
            f"{row.get('source_status_display')} | "
            f"{row.get('current_db_status_display')} | "
            f"{row.get('display_ready')} | "
            f"{warnings} |"
        )
    lines.extend(["", "## Findings", ""])
    for finding in report.get("findings") or []:
        lines.append(
            "- "
            f"{finding.get('severity')}:{finding.get('code')} "
            f"{finding.get('message')}"
        )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            f"- approval_claim: {policy.get('approval_claim')}",
            f"- db_writes: {policy.get('db_writes')}",
            f"- source_values_preserved: {policy.get('source_values_preserved')}",
            f"- display_fields_are_review_surface: {policy.get('display_fields_are_review_surface')}",
            f"- human_decision_required_for_approval: {policy.get('human_decision_required_for_approval')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _non_empty_text(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _review_audit_rows_by_entity(
    conn: sqlite3.Connection,
    entity_type: str,
    entity_ids: list[Any],
) -> dict[str, list[dict[str, Any]]]:
    ids = [str(entity_id) for entity_id in entity_ids if entity_id is not None]
    if not ids:
        return {}
    placeholders = ",".join("?" for _ in ids)
    query = f"""
        SELECT
            entity_id,
            action,
            previous_status,
            new_status,
            reviewer_id,
            notes,
            source_decision_packet,
            source_artifact_hash,
            rationale,
            evidence_refs_json,
            created_by_tool,
            run_artifact,
            created_at
        FROM review_audit_log
        WHERE entity_type = ?
          AND entity_id IN ({placeholders})
        ORDER BY entity_id, created_at, id
    """
    grouped: dict[str, list[dict[str, Any]]] = {entity_id: [] for entity_id in ids}
    for row in conn.execute(query, (entity_type, *ids)):
        grouped.setdefault(str(row["entity_id"]), []).append(dict(row))
    return grouped


def _audit_log_presence(logs: list[dict[str, Any]]) -> dict[str, Any]:
    actions = sorted(
        {
            str(log.get("action"))
            for log in logs
            if _non_empty_text(log.get("action"))
        }
    )
    reviewer_ids = sorted(
        {
            str(log.get("reviewer_id"))
            for log in logs
            if _non_empty_text(log.get("reviewer_id"))
        }
    )
    packet_available = any(_non_empty_text(log.get("source_decision_packet")) for log in logs)
    rationale_available = any(_non_empty_text(log.get("rationale")) for log in logs)
    evidence_refs_available = any(_non_empty_text(log.get("evidence_refs_json")) for log in logs)
    tool_available = any(_non_empty_text(log.get("created_by_tool")) for log in logs)
    missing_packet_backed_fields: list[str] = []
    if not reviewer_ids:
        missing_packet_backed_fields.append("reviewer_id")
    if not packet_available:
        missing_packet_backed_fields.append("source_decision_packet")
    if not rationale_available:
        missing_packet_backed_fields.append("rationale")
    if not evidence_refs_available:
        missing_packet_backed_fields.append("evidence_refs_json")
    packet_backed = not missing_packet_backed_fields
    if packet_backed:
        provenance_state = "packet_backed"
    elif logs:
        provenance_state = "audit_log_without_packet"
    else:
        provenance_state = "no_audit_log"
    return {
        "audit_log_count": len(logs),
        "audit_actions": actions,
        "reviewer_id_count": len(reviewer_ids),
        "reviewer_ids_redacted": bool(reviewer_ids),
        "reviewer_id_redaction_policy": "redacted_in_report_artifacts",
        "source_decision_packet_available": packet_available,
        "rationale_available": rationale_available,
        "evidence_refs_available": evidence_refs_available,
        "created_by_tool_available": tool_available,
        "packet_backed_provenance": packet_backed,
        "packet_backed_missing_fields": missing_packet_backed_fields,
        "provenance_state": provenance_state,
        "latest_audit_created_at": logs[-1].get("created_at") if logs else None,
    }


def _status_counts(rows: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("review_status") or "unknown")
        counts[status] = counts.get(status, 0) + 1
    return counts


def _safe_review_status_display_counts(rows: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("review_status_display") or "unknown")
        counts[status] = counts.get(status, 0) + 1
    return counts


def _human_review_provenance_surface(
    conn: sqlite3.Connection,
    *,
    surface_name: str,
    entity_type: str,
    entity_id_key: str,
    rows: list[dict[str, Any]],
    display_keys: list[str],
) -> dict[str, Any]:
    audit_rows = _review_audit_rows_by_entity(
        conn,
        entity_type,
        [row.get(entity_id_key) for row in rows],
    )
    rendered_rows: list[dict[str, Any]] = []
    for row in rows:
        entity_id = str(row.get(entity_id_key))
        presence = _audit_log_presence(audit_rows.get(entity_id, []))
        safe_row = {key: value for key, value in row.items() if key != "review_status"}
        review_status_display = _provenance_status_display_from_presence(presence)
        display_ready = all(
            _text_is_readable_display(row.get(key))
            for key in display_keys
            if row.get(key) is not None
        )
        rendered = {
            **safe_row,
            "entity_type": entity_type,
            "entity_id": entity_id,
            "raw_review_status_suppressed": True,
            "review_status_display": review_status_display,
            "status_disposition": review_status_display,
            "status_trust": (
                "packet_backed_reconfirmation_present"
                if presence.get("packet_backed_provenance")
                else "not_trusted_until_packet_backed_reconfirmation"
            ),
            "display_ready": display_ready,
            **presence,
        }
        rendered_rows.append(rendered)
    row_count = len(rendered_rows)
    rows_with_audit_log = sum(1 for row in rendered_rows if row.get("audit_log_count"))
    rows_packet_backed = sum(1 for row in rendered_rows if row.get("packet_backed_provenance"))
    display_not_ready_count = sum(1 for row in rendered_rows if not row.get("display_ready"))
    return {
        "surface": surface_name,
        "entity_type": entity_type,
        "row_count": row_count,
        "review_status_display_counts": _safe_review_status_display_counts(rendered_rows),
        "raw_review_status_suppressed": True,
        "audit_log_row_count": sum(int(row.get("audit_log_count") or 0) for row in rendered_rows),
        "rows_with_audit_log": rows_with_audit_log,
        "rows_without_audit_log": row_count - rows_with_audit_log,
        "rows_packet_backed": rows_packet_backed,
        "rows_without_packet_backed_provenance": row_count - rows_packet_backed,
        "display_ready_count": row_count - display_not_ready_count,
        "display_not_ready_count": display_not_ready_count,
        "rows": rendered_rows,
    }


def build_human_review_provenance_surface_audit(db_path: Path) -> dict[str, Any]:
    db_uri = Path(db_path).resolve().as_uri() + "?mode=ro"
    conn = sqlite3.connect(db_uri, uri=True, timeout=30)
    conn.row_factory = sqlite3.Row
    try:
        career_rows = [
            dict(row)
            for row in conn.execute(
                """
                SELECT
                    cp.career_path_id,
                    cp.job_name,
                    cp.competency_name,
                    cp.position_name,
                    cp.competency_level_raw,
                    cp.position_level_raw,
                    cp.matched_unit_code,
                    cp.review_status,
                    cp.updated_at,
                    COALESCE(cu.unit_name_refined, cu.api_unit_name, cu.unit_name_raw) AS matched_unit_name,
                    cl.major_name,
                    cl.middle_name,
                    cl.small_name,
                    cl.sub_name
                FROM ncs_career_paths cp
                LEFT JOIN competency_units cu
                  ON cu.unit_code = cp.matched_unit_code
                LEFT JOIN classifications cl
                  ON cl.classification_id = cp.matched_classification_id
                WHERE cp.review_status IN ('reviewed', 'accepted', 'human_reviewed')
                ORDER BY cp.career_path_id
                """
            )
        ]
        alias_rows = [
            dict(row)
            for row in conn.execute(
                """
                SELECT
                    qa.alias_id,
                    qa.alias_text,
                    qa.normalized_query,
                    qa.major_code,
                    qa.middle_code,
                    qa.small_code,
                    qa.sub_code,
                    qa.unit_code,
                    qa.confidence_score,
                    qa.source_method,
                    qa.review_status,
                    qa.updated_at,
                    COALESCE(cu.unit_name_refined, cu.api_unit_name, cu.unit_name_raw) AS unit_name
                FROM ncs_query_aliases qa
                LEFT JOIN competency_units cu
                  ON cu.unit_code = qa.unit_code
                WHERE qa.review_status IN ('reviewed', 'accepted', 'human_reviewed')
                ORDER BY qa.alias_id
                """
            )
        ]
        scenario_rows = [
            dict(row)
            for row in conn.execute(
                """
                SELECT
                    scenario_id,
                    scenario_name,
                    current_query,
                    target_query,
                    major_code,
                    expected_current_match_text,
                    expected_target_match_text,
                    expected_course_names_json,
                    review_status,
                    updated_at
                FROM training_transition_gold_scenarios
                WHERE review_status IN ('reviewed', 'accepted', 'human_reviewed')
                ORDER BY scenario_id
                """
            )
        ]
        surfaces = [
            _human_review_provenance_surface(
                conn,
                surface_name="ncs_career_paths",
                entity_type="ncs_career_path",
                entity_id_key="career_path_id",
                rows=career_rows,
                display_keys=["job_name", "competency_name", "matched_unit_name"],
            ),
            _human_review_provenance_surface(
                conn,
                surface_name="ncs_query_aliases",
                entity_type="ncs_query_alias",
                entity_id_key="alias_id",
                rows=alias_rows,
                display_keys=["alias_text", "normalized_query", "unit_name"],
            ),
            _human_review_provenance_surface(
                conn,
                surface_name="training_transition_gold_scenarios",
                entity_type="training_transition_gold_scenario",
                entity_id_key="scenario_id",
                rows=scenario_rows,
                display_keys=["scenario_name", "current_query", "target_query"],
            ),
        ]
    finally:
        conn.close()

    findings: list[dict[str, Any]] = []
    for surface in surfaces:
        if surface.get("display_not_ready_count"):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "display_not_ready",
                    "surface": surface.get("surface"),
                    "row_count": surface.get("display_not_ready_count"),
                    "message": "Some human-review surface rows are not readable for display.",
                }
            )
        if surface.get("rows_without_audit_log"):
            findings.append(
                {
                    "severity": "review",
                    "code": "reviewed_rows_without_audit_log",
                    "surface": surface.get("surface"),
                    "row_count": surface.get("rows_without_audit_log"),
                    "message": "Some reviewed rows have no matching review_audit_log row.",
                }
            )
        if surface.get("rows_without_packet_backed_provenance"):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "reviewed_rows_without_packet_backed_provenance",
                    "surface": surface.get("surface"),
                    "row_count": surface.get("rows_without_packet_backed_provenance"),
                    "message": "Some reviewed rows lack packet-backed provenance and must be reconfirmed before being treated as trusted.",
                }
            )
    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    total_rows = sum(int(surface.get("row_count") or 0) for surface in surfaces)
    rows_packet_backed = sum(int(surface.get("rows_packet_backed") or 0) for surface in surfaces)
    rows_without_packet_backed = total_rows - rows_packet_backed
    provenance_gap_present = rows_without_packet_backed > 0
    return {
        "ok": blocker_count == 0 and not provenance_gap_present,
        "schema": "aihr_human_review_provenance_surface_audit_v1",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "report_only": True,
        "status_update_allowed": False,
        "db_writes": False,
        "approval_claim": False,
        "source_database_ref": AIHR_PUBLIC_DATABASE_REF,
        "summary": {
            "surface_count": len(surfaces),
            "row_count": total_rows,
            "rows_packet_backed": rows_packet_backed,
            "rows_without_packet_backed_provenance": rows_without_packet_backed,
            "audit_log_row_count": sum(
                int(surface.get("audit_log_row_count") or 0) for surface in surfaces
            ),
            "provenance_gap_present": provenance_gap_present,
            "approval_ready": not provenance_gap_present and blocker_count == 0,
            "contract_ok": not provenance_gap_present and blocker_count == 0,
            "approval_claim": False,
            "db_writes": False,
            "status_update_allowed": False,
        },
        "surfaces": surfaces,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
        "review_policy": {
            "db_writes": False,
            "approval_claim": False,
            "source_tables": [
                "ncs_career_paths",
                "ncs_query_aliases",
                "training_transition_gold_scenarios",
                "review_audit_log",
            ],
            "packet_backed_requires": [
                "reviewer_id",
                "source_decision_packet",
                "rationale",
                "evidence_refs_json",
            ],
            "human_decision_required_for_approval": True,
        },
    }


def write_human_review_provenance_surface_markdown(
    report: dict[str, Any],
    out_path: Path,
) -> None:
    summary = report.get("summary") if isinstance(report.get("summary"), dict) else {}
    lines = [
        "# AI-HR Human Review Provenance Surface Audit",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- row_count: {summary.get('row_count')}",
        f"- rows_packet_backed: {summary.get('rows_packet_backed')}",
        f"- rows_without_packet_backed_provenance: {summary.get('rows_without_packet_backed_provenance')}",
        f"- audit_log_row_count: {summary.get('audit_log_row_count')}",
        f"- provenance_gap_present: {summary.get('provenance_gap_present')}",
        f"- approval_claim: {summary.get('approval_claim')}",
        f"- db_writes: {summary.get('db_writes')}",
        "",
    ]
    for surface in report.get("surfaces") or []:
        lines.extend(
            [
                f"## {surface.get('surface')}",
                "",
                f"- row_count: {surface.get('row_count')}",
                f"- review_status_display_counts: {surface.get('review_status_display_counts')}",
                f"- rows_with_audit_log: {surface.get('rows_with_audit_log')}",
                f"- rows_without_audit_log: {surface.get('rows_without_audit_log')}",
                f"- rows_packet_backed: {surface.get('rows_packet_backed')}",
                f"- rows_without_packet_backed_provenance: {surface.get('rows_without_packet_backed_provenance')}",
                f"- display_ready_count: {surface.get('display_ready_count')}",
                "",
                "| id | status display | display | audit actions | provenance state | packet | rationale | reviewer count | reviewer ids |",
                "|---:|---|---|---|---|---|---|---|---|",
            ]
        )
        for row in surface.get("rows") or []:
            if surface.get("surface") == "ncs_career_paths":
                display = (
                    f"{row.get('job_name')} / {row.get('competency_name')}"
                    f" -> {row.get('matched_unit_name') or row.get('matched_unit_code')}"
                )
                row_id = row.get("career_path_id")
            elif surface.get("surface") == "ncs_query_aliases":
                display = (
                    f"{row.get('alias_text')} -> {row.get('normalized_query')}"
                    f" / {row.get('unit_name') or row.get('unit_code') or ''}"
                )
                row_id = row.get("alias_id")
            else:
                display = (
                    f"{row.get('scenario_name')}: "
                    f"{row.get('current_query')} -> {row.get('target_query')}"
                )
                row_id = row.get("scenario_id")
            actions = ", ".join(row.get("audit_actions") or [])
            reviewer_ids_display = "redacted" if row.get("reviewer_ids_redacted") else ""
            lines.append(
                "| "
                f"{row_id} | "
                f"{row.get('review_status_display')} | "
                f"{display} | "
                f"{actions} | "
                f"{row.get('provenance_state')} | "
                f"{row.get('source_decision_packet_available')} | "
                f"{row.get('rationale_available')} | "
                f"{row.get('reviewer_id_count') or 0} | "
                f"{reviewer_ids_display} |"
            )
        lines.append("")
    lines.extend(["## Findings", ""])
    for finding in report.get("findings") or []:
        lines.append(
            "- "
            f"{finding.get('severity')}:{finding.get('code')} "
            f"surface={finding.get('surface')} rows={finding.get('row_count')} "
            f"{finding.get('message')}"
        )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            f"- approval_claim: {policy.get('approval_claim')}",
            f"- db_writes: {policy.get('db_writes')}",
            f"- packet_backed_requires: {policy.get('packet_backed_requires')}",
            f"- human_decision_required_for_approval: {policy.get('human_decision_required_for_approval')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


_PROVENANCE_RECONFIRM_SURFACE_TABLES = {
    "ncs_career_paths": "ncs_career_paths",
    "ncs_query_aliases": "ncs_query_aliases",
    "training_transition_gold_scenarios": "training_transition_gold_scenarios",
}
_PROVENANCE_RECONFIRM_TRUSTED_STATUSES = ("reviewed", "accepted", "human_reviewed")


def _is_provenance_reconfirm_trusted_status(status: Any) -> bool:
    return str(status or "") in _PROVENANCE_RECONFIRM_TRUSTED_STATUSES


def _provenance_reconfirm_row_display(surface: str, row: dict[str, Any]) -> str:
    if surface == "ncs_career_paths":
        return (
            f"{row.get('job_name')} / {row.get('competency_name')} -> "
            f"{row.get('matched_unit_name') or row.get('matched_unit_code')}"
        )
    if surface == "ncs_query_aliases":
        return (
            f"{row.get('alias_text')} -> {row.get('normalized_query')} / "
            f"{row.get('unit_name') or row.get('unit_code') or ''}"
        )
    return (
        f"{row.get('scenario_name')}: "
        f"{row.get('current_query')} -> {row.get('target_query')}"
    )


def _provenance_reconfirm_row_id(surface: str, row: dict[str, Any]) -> Any:
    if surface == "ncs_career_paths":
        return row.get("career_path_id")
    if surface == "ncs_query_aliases":
        return row.get("alias_id")
    return row.get("scenario_id")


def _provenance_reconfirm_row_scope(surface: str, row: dict[str, Any]) -> dict[str, Any]:
    if surface == "ncs_career_paths":
        return {
            "major_name": row.get("major_name"),
            "middle_name": row.get("middle_name"),
            "small_name": row.get("small_name"),
            "sub_name": row.get("sub_name"),
            "matched_unit_code": row.get("matched_unit_code"),
            "matched_unit_name": row.get("matched_unit_name"),
            "competency_level_raw": row.get("competency_level_raw"),
            "position_level_raw": row.get("position_level_raw"),
        }
    if surface == "ncs_query_aliases":
        return {
            "major_code": row.get("major_code"),
            "middle_code": row.get("middle_code"),
            "small_code": row.get("small_code"),
            "sub_code": row.get("sub_code"),
            "unit_code": row.get("unit_code"),
            "unit_name": row.get("unit_name"),
            "confidence_score": row.get("confidence_score"),
            "source_method": row.get("source_method"),
        }
    return {
        "major_code": row.get("major_code"),
        "expected_current_match_text": row.get("expected_current_match_text"),
        "expected_target_match_text": row.get("expected_target_match_text"),
        "expected_course_names_json": row.get("expected_course_names_json"),
    }


def _provenance_reconfirm_status_disposition(row: dict[str, Any]) -> dict[str, Any]:
    if not row.get("packet_backed_provenance"):
        return {
            "raw_review_status_suppressed": True,
            "review_status_display": "legacy_status_needs_reconfirmation",
            "status_disposition": "legacy_status_needs_reconfirmation",
            "status_trust": "not_trusted_until_packet_backed_reconfirmation",
        }
    return {
        "raw_review_status_suppressed": True,
        "review_status_display": "packet_backed_status",
        "status_disposition": "packet_backed_status",
        "status_trust": "packet_backed",
    }


def build_human_review_provenance_reconfirmation_packet(
    *,
    db_path: Path,
    limit_per_surface: int | None = None,
) -> dict[str, Any]:
    audit = build_human_review_provenance_surface_audit(db_path)
    rows: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []
    order = 1
    for surface in audit.get("surfaces") or []:
        if not isinstance(surface, dict):
            continue
        surface_name = str(surface.get("surface") or "")
        selected = [
            row
            for row in surface.get("rows") or []
            if isinstance(row, dict) and not row.get("packet_backed_provenance")
            and row.get("status_disposition") == "legacy_status_needs_reconfirmation"
        ]
        if limit_per_surface is not None:
            selected = selected[: max(limit_per_surface, 0)]
        for source_row in selected:
            target_id = _provenance_reconfirm_row_id(surface_name, source_row)
            status_disposition = _provenance_reconfirm_status_disposition(source_row)
            rows.append(
                {
                    "order": order,
                    "surface": surface_name,
                    "target_table": _PROVENANCE_RECONFIRM_SURFACE_TABLES.get(surface_name, surface_name),
                    "entity_type": source_row.get("entity_type") or surface.get("entity_type"),
                    "target_id": str(target_id),
                    **status_disposition,
                    "display": _provenance_reconfirm_row_display(surface_name, source_row),
                    "scope": _provenance_reconfirm_row_scope(surface_name, source_row),
                    "provenance_state": source_row.get("provenance_state"),
                    "audit_actions": source_row.get("audit_actions") or [],
                    "reviewer_id_count": int(source_row.get("reviewer_id_count") or 0),
                    "reviewer_ids_redacted": bool(source_row.get("reviewer_ids_redacted")),
                    "reviewer_id_redaction_policy": source_row.get("reviewer_id_redaction_policy")
                    or "redacted_in_report_artifacts",
                    "source_decision_packet_available": bool(
                        source_row.get("source_decision_packet_available")
                    ),
                    "rationale_available": bool(source_row.get("rationale_available")),
                    "evidence_refs_available": bool(source_row.get("evidence_refs_available")),
                    "created_by_tool_available": bool(source_row.get("created_by_tool_available")),
                    "latest_audit_created_at": source_row.get("latest_audit_created_at"),
                    "requested_decision": "reconfirm | downgrade_to_review_required | defer",
                    "decision_semantics": "review_input_only_not_status_update",
                    "question_ko": (
                        "\ud328\ud0b7 \uadfc\uac70\uac00 \ucda9\ubd84\ud55c\uc9c0, "
                        "review_required\ub85c \ub0ae\ucd9c\uc9c0, \ubcf4\ub958\ud560\uc9c0 "
                        "\uacb0\uc815\ud574 \uc8fc\uc138\uc694. \uc774 \uacb0\uc815\uc740 "
                        "\ubcc4\ub3c4 \uac10\uc0ac\uc640 guarded apply \uc804\uae4c\uc9c0 "
                        "\uc0c1\ud0dc \uc720\uc9c0\ub098 DB \uac31\uc2e0\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."
                    ),
                    "required_packet_fields": [
                        "reviewer_id",
                        "reviewed_at",
                        "source_decision_packet",
                        "rationale",
                        "evidence_refs_json",
                    ],
                    "approval_claim": False,
                    "db_writes": False,
                }
            )
            order += 1
    if not rows and audit.get("summary", {}).get("provenance_gap_present"):
        findings.append(
            {
                "severity": "review",
                "code": "provenance_gap_present_but_no_rows_selected",
                "message": "A provenance gap is present, but no reconfirmation rows were selected.",
            }
        )
    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    return {
        "ok": blocker_count == 0,
        "schema": "aihr_human_review_provenance_reconfirmation_packet_v1",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "source_audit_schema": audit.get("schema"),
        "source_database_ref": "configured_ncs_database",
        "row_count": len(rows),
        "limit_per_surface": limit_per_surface,
        "surface_counts": {
            str(surface.get("surface")): int(surface.get("rows_without_packet_backed_provenance") or 0)
            for surface in audit.get("surfaces") or []
            if isinstance(surface, dict)
        },
        "legacy_status_needs_reconfirmation_count": sum(
            1
            for row in rows
            if row.get("status_disposition") == "legacy_status_needs_reconfirmation"
        ),
        "review_status_display_counts": _status_counts(
            [{"review_status": row.get("review_status_display")} for row in rows]
        ),
        "selected_surface_counts": _status_counts(
            [{"review_status": row.get("surface")} for row in rows]
        ),
        "source_audit_summary": audit.get("summary") or {},
        "rows": rows,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
        "approval_claim": False,
        "db_writes": False,
        "api_calls": False,
        "status_update_allowed": False,
        "human_decision_required": True,
        "review_policy": {
            "does_not_change_existing_statuses": True,
            "requires_packet_backed_reconfirmation_before_future_trusted_import": True,
            "legacy_statuses_without_packet_are_not_trusted": True,
            "trusted_review_statuses_suppressed": True,
            "trusted_review_status_count": len(_PROVENANCE_RECONFIRM_TRUSTED_STATUSES),
            "allowed_decisions": ["reconfirm", "downgrade_to_review_required", "defer"],
            "reconfirm_is_evidence_review_only": True,
            "reconfirm_does_not_apply_or_preserve_status": True,
            "minimum_packet_fields": [
                "reviewer_id",
                "reviewed_at",
                "source_decision_packet",
                "rationale",
                "evidence_refs_json",
            ],
        },
    }


def write_human_review_provenance_reconfirmation_markdown(
    report: dict[str, Any],
    out_path: Path,
) -> None:
    lines = [
        "# AI-HR Provenance Reconfirmation Packet",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- created_at: {report.get('created_at')}",
        f"- row_count: {report.get('row_count')}",
        f"- legacy_status_needs_reconfirmation_count: {report.get('legacy_status_needs_reconfirmation_count')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- api_calls: {report.get('api_calls')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        "",
        "This packet collects human evidence decisions for legacy rows carrying trusted-status labels that lack packet-backed provenance.",
        "It performs no DB writes, does not approve existing rows, and does not preserve any status by itself.",
        "A reconfirm value is evidence-review input for a later audited guarded workflow, not an approval claim or status update.",
        "",
        "| order | surface | target | status display | display | provenance | packet | rationale | requested decision |",
        "|---:|---|---|---|---|---|---|---|---|",
    ]
    for row in report.get("rows") or []:
        if not isinstance(row, dict):
            continue
        target = f"{row.get('target_table')}:{row.get('target_id')}"
        status_display = (
            row.get("review_status_display")
            or row.get("status_disposition")
            or "review_status_suppressed"
        )
        lines.append(
            "| "
            f"{_aihr_markdown_cell(row.get('order'))} | "
            f"{_aihr_markdown_cell(row.get('surface'))} | "
            f"{_aihr_markdown_cell(target)} | "
            f"{_aihr_markdown_cell(status_display)} | "
            f"{_aihr_markdown_cell(row.get('display'))} | "
            f"{_aihr_markdown_cell(row.get('provenance_state'))} | "
            f"{_aihr_markdown_cell(row.get('source_decision_packet_available'))} | "
            f"{_aihr_markdown_cell(row.get('rationale_available'))} | "
            f"{_aihr_markdown_cell(row.get('requested_decision'))} |"
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{finding.get('message')}"
            )
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            "- A reconfirm decision still needs a specific source packet and rationale, and is not a DB write, approval claim, or status-preservation action.",
            "- Downgrade/defer decisions require a later guarded import before any DB status changes.",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


