def _query_alias_text(value: Any) -> str:
    return str(value or "").strip()


def _query_alias_norm(value: Any) -> str:
    return re.sub(r"[\s\-_./·]+", "", _query_alias_text(value)).casefold()


def _json_file_sha256(path: Path) -> str | None:
    try:
        return "sha256:" + hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError:
        return None


def _load_llm_json_bytes(data: bytes) -> Any:
    return json.loads(data.decode("utf-8-sig"))


def _load_llm_json_file(path: Path) -> Any:
    return _load_llm_json_bytes(path.read_bytes())


def _resolve_llm_preprocessing_runbook_queue_path(
    explicit_queue: Path | None,
) -> tuple[str | None, str | None]:
    if explicit_queue is not None:
        return str(explicit_queue), "explicit_cli_queue"
    readiness_path = _latest_report_path_recursive(
        "aihr_release_readiness_*.json",
        fallback=ROOT / "reports" / "aihr_release_readiness_20260624_autoresolve.json",
    )
    try:
        readiness = _load_llm_json_file(readiness_path)
    except (json.JSONDecodeError, UnicodeDecodeError, OSError):
        return None, None
    if isinstance(readiness, dict) and readiness.get("agent_work_queue_path"):
        return str(readiness["agent_work_queue_path"]), str(readiness_path)
    return None, None


def _llm_json_decode_issue(
    path: Path,
    exc: json.JSONDecodeError | UnicodeDecodeError,
) -> dict[str, Any]:
    if isinstance(exc, UnicodeDecodeError):
        return {
            "severity": "blocker",
            "code": "invalid_utf8_input",
            "path": str(path),
            "start": exc.start,
            "end": exc.end,
            "message": f"Input file could not be decoded as UTF-8: {exc.reason}",
        }
    return {
        "severity": "blocker",
        "code": "malformed_json_input",
        "path": str(path),
        "line": exc.lineno,
        "column": exc.colno,
        "message": f"Input JSON could not be parsed: {exc.msg}",
    }


