def _query_alias_gap_report_framework_reference_markers(value: Any) -> list[str]:
    markers: set[str] = set()

    def visit(item: Any, path: str) -> None:
        if isinstance(item, dict):
            for key, child in item.items():
                key_text = str(key)
                key_lower = key_text.lower()
                child_path = f"{path}.{key_text}" if path else key_text
                if key_lower in {"framework_reference", "guide_role"}:
                    markers.add(child_path)
                visit(child, child_path)
        elif isinstance(item, list):
            for index, child in enumerate(item):
                visit(child, f"{path}[{index}]")
        elif isinstance(item, str) and "framework_reference" in item.lower():
            markers.add(path or "<root>")

    visit(value, "")
    return sorted(markers)


def _query_alias_gap_report_source_findings(
    gap_report: dict[str, Any],
    *,
    source_text: str,
) -> tuple[list[dict[str, Any]], bool]:
    findings: list[dict[str, Any]] = []
    schema = _query_alias_text(gap_report.get("schema"))
    if not schema:
        findings.append(
            {
                "severity": "blocker",
                "code": "gap_report_schema_missing",
                "message": "Source gap report must declare an operational schema.",
            }
        )
    elif not schema.startswith("query_resolution_gap_report"):
        findings.append(
            {
                "severity": "blocker",
                "code": "gap_report_schema_not_allowed",
                "schema": schema,
                "message": "Source gap report schema is not an allowed query-resolution gap report schema.",
            }
        )

    source_kind = _query_alias_text(
        gap_report.get("source_kind")
        or gap_report.get("source_type")
        or gap_report.get("guide_role")
    )
    if source_kind and source_kind.lower() == "framework_reference":
        findings.append(
            {
                "severity": "blocker",
                "code": "gap_report_framework_reference_source",
                "message": "Framework-reference reports cannot be used as query alias candidate evidence.",
            }
        )
    framework_markers = _query_alias_gap_report_framework_reference_markers(gap_report)
    if framework_markers:
        findings.append(
            {
                "severity": "blocker",
                "code": "gap_report_framework_reference_marker",
                "markers": framework_markers[:20],
                "message": "Source gap report contains framework-reference markers.",
            }
        )

    sensitive_markers = _aihr_packet_artifact_sensitive_markers(source_text)
    source_payload_exposed = bool(sensitive_markers)
    if source_payload_exposed:
        findings.append(
            {
                "severity": "blocker",
                "code": "gap_report_sensitive_payload_marker",
                "sensitive_markers": sensitive_markers,
                "message": "Source gap report exposes sensitive raw payload markers.",
            }
        )
    return findings, source_payload_exposed


def _query_alias_expression_parts(value: Any) -> list[str]:
    text = _query_alias_text(value)
    if not text:
        return []
    return [part.strip() for part in text.split("->") if part.strip()]


def _query_alias_expression_pairs(
    requested_expression: Any,
    validated_expression: Any,
) -> list[dict[str, str]]:
    requested_parts = _query_alias_expression_parts(requested_expression)
    validated_parts = _query_alias_expression_parts(validated_expression)
    if requested_parts and len(requested_parts) == len(validated_parts) and len(requested_parts) > 1:
        roles = ["current", "target"]
        while len(roles) < len(requested_parts):
            roles.append(f"scope_{len(roles) + 1}")
        pairs = [
            {"role": roles[index], "alias_text": requested, "normalized_query": validated}
            for index, (requested, validated) in enumerate(zip(requested_parts, validated_parts))
        ]
    else:
        pairs = [
            {
                "role": "query",
                "alias_text": _query_alias_text(requested_expression),
                "normalized_query": _query_alias_text(validated_expression),
            }
        ]
    return [
        pair
        for pair in pairs
        if pair.get("alias_text")
        and pair.get("normalized_query")
        and _query_alias_norm(pair.get("alias_text")) != _query_alias_norm(pair.get("normalized_query"))
    ]


def _query_alias_existing_alias_summary(
    conn: sqlite3.Connection,
    *,
    alias_text: str,
    normalized_query: str,
) -> dict[str, Any]:
    try:
        rows = [
            dict(row)
            for row in conn.execute(
                """
                SELECT alias_id, review_status
                FROM ncs_query_aliases
                WHERE alias_text = ? OR normalized_query = ?
                ORDER BY alias_id
                """,
                (alias_text, normalized_query),
            )
        ]
    except sqlite3.Error as exc:
        return {
            "existing_alias_count": 0,
            "existing_alias_review_statuses": "",
            "lookup_error": str(exc),
        }
    statuses = sorted({str(row.get("review_status") or "") for row in rows if row.get("review_status")})
    return {
        "existing_alias_count": len(rows),
        "existing_alias_review_statuses": ", ".join(statuses),
        "lookup_error": None,
    }


def _query_alias_candidate_from_resolution(resolution: dict[str, Any]) -> dict[str, Any] | None:
    for candidate in resolution.get("candidates") or []:
        if not isinstance(candidate, dict):
            continue
        if candidate.get("candidate_type") in {"classification", "unit"}:
            return candidate
    return None


def _query_alias_validated_snapshot_for_role(case: dict[str, Any], role: str) -> dict[str, Any] | None:
    summary = case.get("validated_resolution_summary")
    if not isinstance(summary, dict):
        return None
    parts = [part for part in summary.get("parts") or [] if isinstance(part, dict)]
    if not parts:
        return None
    for part in parts:
        if part.get("role") == role:
            return part
    if len(parts) == 1:
        return parts[0]
    return None


def _query_alias_resolution_drift_finding(
    *,
    case_id: str,
    pair: dict[str, str],
    stored_snapshot: dict[str, Any] | None,
    current_candidate: dict[str, Any],
) -> dict[str, Any] | None:
    if not stored_snapshot:
        return None
    comparisons = [
        ("candidate_type", stored_snapshot.get("top_candidate_type"), current_candidate.get("candidate_type")),
        ("unit_code", stored_snapshot.get("top_unit_code"), current_candidate.get("unit_code")),
        ("major_code", stored_snapshot.get("top_major_code"), current_candidate.get("major_code")),
        ("sub_code", stored_snapshot.get("top_sub_code"), current_candidate.get("sub_code")),
    ]
    mismatches = [
        {"field": field, "stored": stored, "current": current}
        for field, stored, current in comparisons
        if stored not in (None, "") and current not in (None, "") and str(stored) != str(current)
    ]
    if not mismatches:
        return None
    return {
        "severity": "review",
        "code": "validated_resolution_drift",
        "case_id": case_id,
        "role": pair.get("role") or "query",
        "alias_text": pair.get("alias_text"),
        "normalized_query": pair.get("normalized_query"),
        "mismatches": mismatches,
        "message": "Validated expression resolves to a different top candidate than the stored gap-report snapshot.",
    }


def _query_alias_candidate_row(
    *,
    order: int,
    alias_text: str,
    normalized_query: str,
    candidate: dict[str, Any],
    existing: dict[str, Any],
    source_gap_report: Path,
    source_fingerprint: str | None,
    source_case_id: str,
    failure_classification: str,
) -> dict[str, Any]:
    raw_candidate_type = str(candidate.get("candidate_type") or "")
    candidate_type = "unit_alias" if raw_candidate_type == "unit" else "classification_alias"
    unit_code = _query_alias_text(candidate.get("unit_code")) if raw_candidate_type == "unit" else ""
    unit_name = _query_alias_text(candidate.get("unit_name") or candidate.get("matched_text")) if unit_code else ""
    review_focus = (
        "검증된 표현이 특정 능력단위로 해석됩니다. alias_text가 같은 의미인지 확인하세요."
        if unit_code
        else "검증된 표현이 NCS 분류 범위로 해석됩니다. alias_text가 같은 범위를 가리키는지 확인하세요."
    )
    return {
        "order": order,
        "alias_text": alias_text,
        "normalized_query": normalized_query,
        "candidate_type": candidate_type,
        "major_code": _query_alias_text(candidate.get("major_code")),
        "major_name": _query_alias_text(candidate.get("major_name")),
        "middle_code": _query_alias_text(candidate.get("middle_code")),
        "middle_name": _query_alias_text(candidate.get("middle_name")),
        "small_code": _query_alias_text(candidate.get("small_code")),
        "small_name": _query_alias_text(candidate.get("small_name")),
        "sub_code": _query_alias_text(candidate.get("sub_code")),
        "sub_name": _query_alias_text(candidate.get("sub_name")),
        "unit_code": unit_code,
        "unit_name": unit_name,
        "confidence_score": float(candidate.get("confidence_score") or 0.0),
        "source_method": "query_resolution_gap_report",
        "source_artifact": str(source_gap_report),
        "source_fingerprint": source_fingerprint or "",
        "source_cases": source_case_id,
        "source_roles": "query",
        "source_occurrence_count": 1,
        "initial_failure_classification": failure_classification,
        "review_focus": review_focus,
        "existing_alias_count": int(existing.get("existing_alias_count") or 0),
        "existing_alias_review_statuses": _query_alias_text(existing.get("existing_alias_review_statuses")),
        "suggested_decision_options": (
            "approve_candidate_alias | reject | revise_normalized_query | needs_domain_expert"
        ),
        "decision": "",
        "revised_normalized_query": "",
        "reviewer_id": "",
        "reviewed_at": "",
        "rationale": "",
        "status_update_allowed": False,
        "db_writes": False,
        "approval_claim": False,
    }


def build_query_alias_candidate_packet(
    conn: sqlite3.Connection,
    *,
    gap_report_path: Path,
    limit: int | None = None,
) -> dict[str, Any]:
    generated_at = datetime.now(timezone.utc).isoformat()
    findings: list[dict[str, Any]] = []
    source_fingerprint = _json_file_sha256(gap_report_path)
    source_payload_exposed = False
    try:
        gap_report_text = gap_report_path.read_text(encoding="utf-8-sig")
        gap_report = json.loads(gap_report_text)
    except FileNotFoundError:
        return {
            "schema": "ncs_query_alias_candidate_packet_v1",
            "generated_at": generated_at,
            "ok": False,
            "report_only": True,
            "db_writes": False,
            "status_update_allowed": False,
            "approval_claim": False,
            "human_decision_required": True,
            "source_gap_report": str(gap_report_path),
            "source_fingerprint": source_fingerprint,
            "source_payload_exposed": False,
            "row_count": 0,
            "blank_decision_count": 0,
            "existing_alias_collision_count": 0,
            "rows": [],
            "findings": [
                {
                    "severity": "blocker",
                    "code": "gap_report_missing",
                    "message": "Query resolution gap report does not exist.",
                }
            ],
            "blocker_count": 1,
        }
    except json.JSONDecodeError as exc:
        return {
            "schema": "ncs_query_alias_candidate_packet_v1",
            "generated_at": generated_at,
            "ok": False,
            "report_only": True,
            "db_writes": False,
            "status_update_allowed": False,
            "approval_claim": False,
            "human_decision_required": True,
            "source_gap_report": str(gap_report_path),
            "source_fingerprint": source_fingerprint,
            "source_payload_exposed": False,
            "row_count": 0,
            "blank_decision_count": 0,
            "existing_alias_collision_count": 0,
            "rows": [],
            "findings": [
                {
                    "severity": "blocker",
                    "code": "gap_report_invalid_json",
                    "message": "Query resolution gap report could not be parsed.",
                    "detail": str(exc),
                }
            ],
            "blocker_count": 1,
        }

    if not isinstance(gap_report, dict):
        cases: list[Any] = []
        findings.append(
            {
                "severity": "blocker",
                "code": "gap_report_not_object",
                "message": "Query resolution gap report must be a JSON object.",
            }
        )
    else:
        findings_from_source, source_payload_exposed = _query_alias_gap_report_source_findings(
            gap_report,
            source_text=gap_report_text,
        )
        findings.extend(findings_from_source)
        raw_cases = gap_report.get("cases")
        cases = raw_cases if isinstance(raw_cases, list) else []
        if gap_report.get("report_only") is not True:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "gap_report_report_only_not_true",
                    "message": "Source gap report must explicitly be report_only=true.",
                }
            )
        if not isinstance(raw_cases, list):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "gap_report_cases_missing",
                    "message": "Source gap report must contain a cases list.",
                }
            )
        for key in ("db_writes", "status_update_allowed", "approval_claim"):
            if gap_report.get(key) is not False:
                findings.append(
                    {
                        "severity": "blocker",
                        "code": f"gap_report_{key}_not_false",
                        "message": "Source gap report must be report-only and cannot claim writes or approval.",
                    }
                )

    rows_by_key: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    max_rows = max(0, limit) if limit is not None else None
    for case in cases:
        if max_rows is not None and len(rows_by_key) >= max_rows:
            break
        if not isinstance(case, dict):
            continue
        classification = _query_alias_text(case.get("classification"))
        if case.get("validated_ok") is not True:
            continue
        if (
            case.get("initial_ok") is not False
            and classification != "candidate_not_promoted_to_execution_scope"
        ):
            continue
        if classification == "output_shape_mismatch_not_recommendation_failure":
            continue
        case_id = _query_alias_text(case.get("case_id")) or f"case_{len(rows_by_key) + 1}"
        pairs = _query_alias_expression_pairs(
            case.get("requested_expression"),
            case.get("validated_expression"),
        )
        if not pairs:
            continue
        for pair in pairs:
            if max_rows is not None and len(rows_by_key) >= max_rows:
                break
            resolution = resolve_ncs_query_scope(conn, pair["normalized_query"], limit=5)
            candidate = _query_alias_candidate_from_resolution(resolution)
            if candidate is None:
                findings.append(
                    {
                        "severity": "review",
                        "code": "validated_query_has_no_alias_candidate",
                        "case_id": case_id,
                        "alias_text": pair["alias_text"],
                        "normalized_query": pair["normalized_query"],
                        "message": "Validated expression did not resolve to a classification or unit candidate.",
                    }
                )
                continue
            drift_finding = _query_alias_resolution_drift_finding(
                case_id=case_id,
                pair=pair,
                stored_snapshot=_query_alias_validated_snapshot_for_role(
                    case,
                    _query_alias_text(pair.get("role")) or "query",
                ),
                current_candidate=candidate,
            )
            if drift_finding:
                findings.append(drift_finding)
            existing = _query_alias_existing_alias_summary(
                conn,
                alias_text=pair["alias_text"],
                normalized_query=pair["normalized_query"],
            )
            if existing.get("lookup_error"):
                findings.append(
                    {
                        "severity": "review",
                        "code": "existing_alias_lookup_failed",
                        "case_id": case_id,
                        "detail": existing.get("lookup_error"),
                    }
                )
            key = (
                _query_alias_norm(pair["alias_text"]),
                _query_alias_norm(pair["normalized_query"]),
                _query_alias_text(candidate.get("unit_code")),
                _query_alias_text(candidate.get("sub_code")),
            )
            if key in rows_by_key:
                row = rows_by_key[key]
                source_cases = [
                    value.strip()
                    for value in str(row.get("source_cases") or "").split(",")
                    if value.strip()
                ]
                if case_id not in source_cases:
                    source_cases.append(case_id)
                    row["source_cases"] = ", ".join(source_cases)
                source_roles = [
                    value.strip()
                    for value in str(row.get("source_roles") or "").split(",")
                    if value.strip()
                ]
                role = _query_alias_text(pair.get("role")) or "query"
                if role not in source_roles:
                    source_roles.append(role)
                    row["source_roles"] = ", ".join(source_roles)
                row["source_occurrence_count"] = int(row.get("source_occurrence_count") or 0) + 1
                classifications = [
                    value.strip()
                    for value in str(row.get("initial_failure_classification") or "").split(",")
                    if value.strip()
                ]
                if classification and classification not in classifications:
                    classifications.append(classification)
                    row["initial_failure_classification"] = ", ".join(classifications)
                continue
            rows_by_key[key] = _query_alias_candidate_row(
                order=len(rows_by_key) + 1,
                alias_text=pair["alias_text"],
                normalized_query=pair["normalized_query"],
                candidate=candidate,
                existing=existing,
                source_gap_report=gap_report_path,
                source_fingerprint=source_fingerprint,
                source_case_id=case_id,
                failure_classification=classification,
            )
            rows_by_key[key]["source_roles"] = _query_alias_text(pair.get("role")) or "query"

    rows = list(rows_by_key.values())
    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    return {
        "schema": "ncs_query_alias_candidate_packet_v1",
        "generated_at": generated_at,
        "ok": blocker_count == 0,
        "report_only": True,
        "db_writes": False,
        "status_update_allowed": False,
        "approval_claim": False,
        "human_decision_required": True,
        "source_gap_report": str(gap_report_path),
        "source_fingerprint": source_fingerprint,
        "source_payload_exposed": source_payload_exposed,
        "row_count": len(rows),
        "blank_decision_count": sum(1 for row in rows if not row.get("decision")),
        "existing_alias_collision_count": sum(1 for row in rows if int(row.get("existing_alias_count") or 0) > 0),
        "review_policy": {
            "candidate_packet_is_not_alias_import": True,
            "do_not_write_human_reviewed_accepted_reviewed": True,
            "operator_must_fill_decision_before_any_guarded_import_plan": True,
            "raw_ncs_tables_not_mutated": True,
        },
        "decision_sheet_fields": list(QUERY_ALIAS_CANDIDATE_DECISION_SHEET_FIELDS),
        "rows": rows,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
    }


def write_query_alias_candidate_decision_sheet_csv(report: dict[str, Any], out_path: Path) -> None:
    def _csv_cell(value: Any) -> str:
        text = "" if value is None else str(value)
        stripped = text.lstrip()
        if text[:1] == "\t" or stripped[:1] in {"=", "+", "-", "@"}:
            return "'" + text
        return text

    rows = [row for row in report.get("rows") or [] if isinstance(row, dict)]
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with out_path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=QUERY_ALIAS_CANDIDATE_DECISION_SHEET_FIELDS)
        writer.writeheader()
        for row in rows:
            writable = {field: row.get(field, "") for field in QUERY_ALIAS_CANDIDATE_DECISION_SHEET_FIELDS}
            for field in ("status_update_allowed", "db_writes", "approval_claim"):
                writable[field] = "false" if row.get(field) is False else str(row.get(field) or "")
            writable = {field: _csv_cell(value) for field, value in writable.items()}
            writer.writerow(writable)


def write_query_alias_candidate_packet_markdown(report: dict[str, Any], out_path: Path) -> None:
    def _md_cell(value: Any) -> str:
        return str(value if value is not None else "").replace("|", "\\|").replace("\n", " ")

    lines = [
        "# Query Alias Candidate Packet",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- source_gap_report: `{_md_cell(report.get('source_gap_report'))}`",
        f"- source_fingerprint: `{_md_cell(report.get('source_fingerprint'))}`",
        f"- source_payload_exposed: {report.get('source_payload_exposed')}",
        f"- row_count: {report.get('row_count')}",
        f"- blank_decision_count: {report.get('blank_decision_count')}",
        f"- existing_alias_collision_count: {report.get('existing_alias_collision_count')}",
        f"- report_only: {report.get('report_only')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- human_decision_required: {report.get('human_decision_required')}",
        "",
        "This packet proposes query-alias review candidates only. It does not import aliases and does not mark any row as reviewed.",
        "",
        "| order | alias_text | normalized_query | type | scope | unit | confidence | existing aliases | decision |",
        "|---:|---|---|---|---|---|---:|---:|---|",
    ]
    for row in report.get("rows") or []:
        if not isinstance(row, dict):
            continue
        scope = " > ".join(
            part
            for part in [
                _md_cell(row.get("major_name") or row.get("major_code")),
                _md_cell(row.get("middle_name") or row.get("middle_code")),
                _md_cell(row.get("small_name") or row.get("small_code")),
                _md_cell(row.get("sub_name") or row.get("sub_code")),
            ]
            if part
        )
        unit = row.get("unit_name") or row.get("unit_code") or ""
        lines.append(
            "| "
            f"{row.get('order')} | "
            f"{_md_cell(row.get('alias_text'))} | "
            f"{_md_cell(row.get('normalized_query'))} | "
            f"{_md_cell(row.get('candidate_type'))} | "
            f"{scope} | "
            f"{_md_cell(unit)} | "
            f"{float(row.get('confidence_score') or 0.0):.2f} | "
            f"{row.get('existing_alias_count')} | "
            f"{_md_cell(row.get('decision'))} |"
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{_md_cell(finding.get('message') or finding.get('detail'))}"
            )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            f"- candidate_packet_is_not_alias_import: {policy.get('candidate_packet_is_not_alias_import')}",
            f"- do_not_write_human_reviewed_accepted_reviewed: {policy.get('do_not_write_human_reviewed_accepted_reviewed')}",
            f"- operator_must_fill_decision_before_any_guarded_import_plan: {policy.get('operator_must_fill_decision_before_any_guarded_import_plan')}",
            f"- raw_ncs_tables_not_mutated: {policy.get('raw_ncs_tables_not_mutated')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _query_resolution_gap_case_findings(
    payload: Any,
    *,
    source_text: str,
) -> tuple[list[dict[str, Any]], bool]:
    findings: list[dict[str, Any]] = []
    if not isinstance(payload, dict):
        findings.append(
            {
                "severity": "blocker",
                "code": "cases_payload_not_object",
                "message": "Query resolution gap cases input must be a JSON object.",
            }
        )
        return findings, bool(_aihr_packet_artifact_sensitive_markers(source_text))
    schema = _query_alias_text(payload.get("schema"))
    if schema and "framework_reference" in schema.lower():
        findings.append(
            {
                "severity": "blocker",
                "code": "cases_schema_framework_reference",
                "message": "Framework-reference case inputs cannot be used as operational gap evidence.",
            }
        )
    source_kind = _query_alias_text(
        payload.get("source_kind")
        or payload.get("source_type")
        or payload.get("guide_role")
    )
    if source_kind.lower() == "framework_reference":
        findings.append(
            {
                "severity": "blocker",
                "code": "cases_framework_reference_source",
                "message": "Framework-reference case inputs cannot be used as operational gap evidence.",
            }
        )
    framework_markers = _query_alias_gap_report_framework_reference_markers(payload)
    if framework_markers:
        findings.append(
            {
                "severity": "blocker",
                "code": "cases_framework_reference_marker",
                "markers": framework_markers[:20],
                "message": "Cases input contains framework-reference markers.",
            }
        )
    sensitive_markers = _aihr_packet_artifact_sensitive_markers(source_text)
    source_payload_exposed = bool(sensitive_markers)
    if source_payload_exposed:
        findings.append(
            {
                "severity": "blocker",
                "code": "cases_sensitive_payload_marker",
                "sensitive_markers": sensitive_markers,
                "message": "Cases input exposes sensitive raw payload markers.",
            }
        )
    if not isinstance(payload.get("cases"), list):
        findings.append(
            {
                "severity": "blocker",
                "code": "cases_list_missing",
                "message": "Cases input must contain a cases list.",
            }
        )
    return findings, source_payload_exposed


def _query_resolution_gap_top_candidate(resolution: dict[str, Any]) -> dict[str, Any]:
    for candidate in resolution.get("candidates") or []:
        if isinstance(candidate, dict):
            return candidate
    return {}


def _query_resolution_gap_resolve_expression(
    conn: sqlite3.Connection,
    expression: Any,
) -> dict[str, Any]:
    parts = _query_alias_expression_parts(expression)
    rows: list[dict[str, Any]] = []
    for index, part in enumerate(parts):
        role = "query"
        if len(parts) == 2:
            role = "current" if index == 0 else "target"
        resolution = resolve_ncs_query_scope(conn, part, limit=5)
        top = _query_resolution_gap_top_candidate(resolution)
        rows.append(
            {
                "role": role,
                "query": part,
                "ok": bool(resolution.get("ok")),
                "candidate_count": len(resolution.get("candidates") or []),
                "top_candidate_type": top.get("candidate_type"),
                "top_candidate_text": (
                    top.get("matched_text")
                    or top.get("unit_name")
                    or top.get("sub_name")
                    or top.get("major_name")
                ),
                "top_unit_code": top.get("unit_code"),
                "top_major_code": top.get("major_code"),
                "top_sub_code": top.get("sub_code"),
            }
        )
    return {
        "ok": bool(rows) and all(row.get("ok") for row in rows),
        "part_count": len(rows),
        "parts": rows,
    }


def _query_resolution_gap_classification(
    *,
    requested_expression: Any,
    validated_expression: Any,
    requested_resolution: dict[str, Any],
    validated_resolution: dict[str, Any],
    explicit_classification: Any = None,
) -> str:
    explicit = _query_alias_text(explicit_classification)
    if explicit:
        return explicit
    requested_ok = bool(requested_resolution.get("ok"))
    validated_ok = bool(validated_resolution.get("ok"))
    if requested_ok and validated_ok:
        if _query_alias_norm(requested_expression) == _query_alias_norm(validated_expression):
            return "output_shape_mismatch_not_recommendation_failure"
        return "resolved_but_normalized_expression_differs"
    if not requested_ok and validated_ok:
        requested_parts = _query_alias_expression_parts(requested_expression)
        validated_parts = _query_alias_expression_parts(validated_expression)
        if len(requested_parts) == 2 and len(validated_parts) == 2:
            requested_role_ok = {
                row.get("role"): bool(row.get("ok"))
                for row in requested_resolution.get("parts") or []
            }
            if not requested_role_ok.get("current", False):
                return "current_scope_normalization_gap"
            if not requested_role_ok.get("target", False):
                return "target_scope_normalization_gap"
        validated_parts_payload = [
            row for row in validated_resolution.get("parts") or [] if isinstance(row, dict)
        ]
        if len(validated_parts_payload) == 1 and validated_parts_payload[0].get("top_candidate_type") == "unit":
            return "candidate_not_promoted_to_execution_scope"
        return "alias_or_scope_normalization_gap"
    if requested_ok and not validated_ok:
        return "validated_expression_unresolved"
    return "unresolved_or_needs_manual_diagnosis"


def _query_resolution_gap_route_fingerprint(payload: dict[str, Any]) -> str:
    stable = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(stable.encode("utf-8")).hexdigest()


def build_query_resolution_gap_report(
    conn: sqlite3.Connection,
    *,
    cases_path: Path,
    limit: int | None = None,
) -> dict[str, Any]:
    generated_at = datetime.now(timezone.utc).isoformat()
    source_fingerprint = _json_file_sha256(cases_path)
    try:
        source_text = cases_path.read_text(encoding="utf-8-sig")
        payload = json.loads(source_text)
    except FileNotFoundError:
        return {
            "schema": "query_resolution_gap_report_v1",
            "source_kind": "explicit_operational_cases",
            "generated_at": generated_at,
            "ok": False,
            "report_only": True,
            "db_writes": False,
            "status_update_allowed": False,
            "approval_claim": False,
            "source_cases_path": str(cases_path),
            "source_fingerprint": source_fingerprint,
            "source_payload_exposed": False,
            "case_count": 0,
            "cases": [],
            "findings": [
                {
                    "severity": "blocker",
                    "code": "cases_file_missing",
                    "message": "Query resolution gap cases input does not exist.",
                }
            ],
            "blocker_count": 1,
        }
    except json.JSONDecodeError as exc:
        return {
            "schema": "query_resolution_gap_report_v1",
            "source_kind": "explicit_operational_cases",
            "generated_at": generated_at,
            "ok": False,
            "report_only": True,
            "db_writes": False,
            "status_update_allowed": False,
            "approval_claim": False,
            "source_cases_path": str(cases_path),
            "source_fingerprint": source_fingerprint,
            "source_payload_exposed": False,
            "case_count": 0,
            "cases": [],
            "findings": [
                {
                    "severity": "blocker",
                    "code": "cases_file_invalid_json",
                    "message": "Query resolution gap cases input could not be parsed.",
                    "detail": str(exc),
                }
            ],
            "blocker_count": 1,
        }

    findings, source_payload_exposed = _query_resolution_gap_case_findings(
        payload,
        source_text=source_text,
    )
    raw_cases = payload.get("cases") if isinstance(payload, dict) else []
    selected_cases = raw_cases if isinstance(raw_cases, list) else []
    if limit is not None:
        selected_cases = selected_cases[: max(0, limit)]

    cases: list[dict[str, Any]] = []
    for index, case in enumerate(selected_cases, start=1):
        if not isinstance(case, dict):
            findings.append(
                {
                    "severity": "review",
                    "code": "case_not_object",
                    "case_index": index,
                    "message": "Case row is not a JSON object.",
                }
            )
            continue
        requested_expression = case.get("requested_expression")
        validated_expression = case.get("validated_expression")
        case_id = _query_alias_text(case.get("case_id")) or f"case_{index}"
        if not _query_alias_text(requested_expression) or not _query_alias_text(validated_expression):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "case_expression_missing",
                    "case_id": case_id,
                    "message": "Case must include requested_expression and validated_expression.",
                }
            )
            continue
        requested_resolution = _query_resolution_gap_resolve_expression(conn, requested_expression)
        validated_resolution = _query_resolution_gap_resolve_expression(conn, validated_expression)
        classification = _query_resolution_gap_classification(
            requested_expression=requested_expression,
            validated_expression=validated_expression,
            requested_resolution=requested_resolution,
            validated_resolution=validated_resolution,
            explicit_classification=case.get("classification"),
        )
        route_fingerprint_payload = {
            "case_id": case_id,
            "requested_expression": _query_alias_text(requested_expression),
            "validated_expression": _query_alias_text(validated_expression),
            "requested_resolution_summary": requested_resolution,
            "validated_resolution_summary": validated_resolution,
        }
        cases.append(
            {
                "case_id": case_id,
                "initial_ok": bool(requested_resolution.get("ok")),
                "validated_ok": bool(validated_resolution.get("ok")),
                "requested_expression": _query_alias_text(requested_expression),
                "validated_expression": _query_alias_text(validated_expression),
                "classification": classification,
                "initial_route": requested_resolution,
                "validated_route": validated_resolution,
                "requested_resolution_summary": requested_resolution,
                "validated_resolution_summary": validated_resolution,
                "validated_resolution_top_candidate": (
                    (validated_resolution.get("parts") or [{}])[0]
                    if isinstance(validated_resolution.get("parts"), list)
                    else {}
                ),
                "validated_resolution_candidate_count": sum(
                    int(part.get("candidate_count") or 0)
                    for part in validated_resolution.get("parts") or []
                    if isinstance(part, dict)
                ),
                "route_fingerprint": _query_resolution_gap_route_fingerprint(route_fingerprint_payload),
                "case_source_artifact": str(cases_path),
                "case_source_fingerprint": source_fingerprint,
            }
        )

    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    report = {
        "schema": "query_resolution_gap_report_v1",
        "source_kind": "explicit_operational_cases",
        "generated_at": generated_at,
        "ok": blocker_count == 0,
        "report_only": True,
        "db_writes": False,
        "status_update_allowed": False,
        "approval_claim": False,
        "source_cases_path": str(cases_path),
        "source_fingerprint": source_fingerprint,
        "source_payload_exposed": source_payload_exposed,
        "case_count": len(cases),
        "initial_failure_count": sum(1 for case in cases if not case.get("initial_ok")),
        "validated_success_count": sum(1 for case in cases if case.get("validated_ok")),
        "alias_candidate_case_count": sum(
            1
            for case in cases
            if case.get("initial_ok") is False
            and case.get("validated_ok") is True
            and case.get("classification") != "output_shape_mismatch_not_recommendation_failure"
        ),
        "classification_counts": {
            classification: sum(1 for case in cases if case.get("classification") == classification)
            for classification in sorted({str(case.get("classification")) for case in cases})
        },
        "cases": cases,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
        "review_policy": {
            "report_only_gap_diagnostic": True,
            "feeds_query_alias_candidate_packet_only": True,
            "do_not_write_human_reviewed_accepted_reviewed": True,
            "framework_reference_is_not_operational_evidence": True,
            "raw_ncs_tables_not_mutated": True,
        },
    }
    return report


def write_query_resolution_gap_report_markdown(report: dict[str, Any], out_path: Path) -> None:
    lines = [
        "# Query Resolution Gap Report",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- source_kind: {report.get('source_kind')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- source_cases_path: `{_non_hr_smoke_md_cell(report.get('source_cases_path'))}`",
        f"- source_fingerprint: `{_non_hr_smoke_md_cell(report.get('source_fingerprint'))}`",
        f"- source_payload_exposed: {report.get('source_payload_exposed')}",
        f"- case_count: {report.get('case_count')}",
        f"- initial_failure_count: {report.get('initial_failure_count')}",
        f"- validated_success_count: {report.get('validated_success_count')}",
        f"- alias_candidate_case_count: {report.get('alias_candidate_case_count')}",
        f"- report_only: {report.get('report_only')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- approval_claim: {report.get('approval_claim')}",
        "",
        "| case | initial | validated | classification | requested | validated expression |",
        "|---|---|---|---|---|---|",
    ]
    for case in report.get("cases") or []:
        if not isinstance(case, dict):
            continue
        lines.append(
            "| "
            f"{_non_hr_smoke_md_cell(case.get('case_id'))} | "
            f"{case.get('initial_ok')} | "
            f"{case.get('validated_ok')} | "
            f"{_non_hr_smoke_md_cell(case.get('classification'))} | "
            f"{_non_hr_smoke_md_cell(case.get('requested_expression'))} | "
            f"{_non_hr_smoke_md_cell(case.get('validated_expression'))} |"
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{_non_hr_smoke_md_cell(finding.get('message') or finding.get('detail'))}"
            )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            f"- report_only_gap_diagnostic: {policy.get('report_only_gap_diagnostic')}",
            f"- feeds_query_alias_candidate_packet_only: {policy.get('feeds_query_alias_candidate_packet_only')}",
            f"- do_not_write_human_reviewed_accepted_reviewed: {policy.get('do_not_write_human_reviewed_accepted_reviewed')}",
            f"- framework_reference_is_not_operational_evidence: {policy.get('framework_reference_is_not_operational_evidence')}",
            f"- raw_ncs_tables_not_mutated: {policy.get('raw_ncs_tables_not_mutated')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


DEFAULT_NON_HR_QUERY_SMOKE_CASES = [
    {"id": "major17_chemical_analysis", "unit_code": "1701010101_23v3", "major_code": "17"},
    {"id": "major20_video_security_incident", "unit_code": "2001060908_21v1", "major_code": "20"},
    {"id": "major23_water_pollution_analysis", "unit_code": "2301010101_22v4", "major_code": "23"},
    {"id": "major13_food_hygiene", "unit_code": "1301010001_21v1", "major_code": "13"},
    {"id": "major15_machine_requirements", "unit_code": "1501010101_21v3", "major_code": "15"},
    {"id": "major14_construction_concept", "unit_code": "1401010101_14v1", "major_code": "14"},
    {"id": "major19_hydro_power_design", "unit_code": "1901010101_14v1", "major_code": "19"},
    {"id": "major22_publication_planning", "unit_code": "2201010101_16v3", "major_code": "22"},
]


def _non_hr_smoke_text(value: Any) -> str:
    return "" if value is None else str(value)


def _non_hr_smoke_md_cell(value: Any) -> str:
    return _non_hr_smoke_text(value).replace("|", "\\|").replace("\n", " ")


def _non_hr_smoke_recommendation_tier(recommendation: dict[str, Any]) -> str:
    tier = recommendation.get("recommendation_tier")
    if isinstance(tier, dict):
        return _non_hr_smoke_text(tier.get("tier"))
    return _non_hr_smoke_text(tier or recommendation.get("display_tier"))


def _non_hr_smoke_course_name(recommendation: dict[str, Any]) -> str:
    course = recommendation.get("training_course")
    if not isinstance(course, dict):
        return ""
    return _non_hr_smoke_text(
        course.get("compe_unit_name")
        or course.get("course_name")
        or course.get("ncs_cl_cd")
    )


def _non_hr_smoke_legacy_source_flags(payload: dict[str, Any]) -> dict[str, bool]:
    audit = payload.get("audit") if isinstance(payload, dict) else {}
    if isinstance(audit, dict):
        return {
            "sqf_used": bool(audit.get("sqf_used")),
            "learning_modules_used": bool(audit.get("learning_modules_used")),
        }
    summary = payload.get("recommendation_summary") if isinstance(payload, dict) else {}
    sources = []
    if isinstance(summary, dict):
        sources = [str(item).lower() for item in summary.get("supplemental_data_sources_used") or []]
    source_text = " ".join(sources)
    return {
        "sqf_used": "sqf" in source_text,
        "learning_modules_used": (
            "learning_module" in source_text
            or "study_module" in source_text
            or "학습모듈" in source_text
        ),
    }


def build_non_hr_query_smoke_report(
    conn: sqlite3.Connection,
    *,
    cases: list[dict[str, Any]] | None = None,
    case_limit: int | None = None,
    recommendation_limit: int = 3,
) -> dict[str, Any]:
    selected_cases = list(cases or DEFAULT_NON_HR_QUERY_SMOKE_CASES)
    if case_limit is not None:
        selected_cases = selected_cases[: max(0, case_limit)]
    generated_at = datetime.now(timezone.utc).isoformat()
    rows: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []

    for index, case in enumerate(selected_cases, start=1):
        case_id = _non_hr_smoke_text(case.get("id") or f"case_{index}")
        unit_code = _non_hr_smoke_text(case.get("unit_code"))
        major_code = _non_hr_smoke_text(case.get("major_code"))
        row: dict[str, Any] = {
            "id": case_id,
            "unit_code": unit_code,
            "major_code": major_code,
            "ok": False,
            "resolve_ok": False,
            "recommend_ok": False,
            "status_update_allowed": False,
            "db_writes": False,
            "approval_claim": False,
        }
        if not unit_code:
            row["error"] = "unit_code_missing"
            findings.append(
                {
                    "severity": "blocker",
                    "code": "unit_code_missing",
                    "case_id": case_id,
                    "message": "Non-HR smoke case is missing unit_code.",
                }
            )
            rows.append(row)
            continue

        try:
            recommendation = recommend_training_for_task(
                conn,
                unit_code=unit_code,
                major_code=major_code or None,
                limit=recommendation_limit,
                save=False,
            )
        except Exception as exc:  # pragma: no cover - defensive report path
            row["error"] = f"recommendation_exception:{type(exc).__name__}"
            row["detail"] = str(exc)
            findings.append(
                {
                    "severity": "blocker",
                    "code": "recommendation_exception",
                    "case_id": case_id,
                    "message": str(exc),
                }
            )
            rows.append(row)
            continue

        source_task = recommendation.get("source_task") if isinstance(recommendation, dict) else {}
        if not isinstance(source_task, dict):
            source_task = {}
        classification = source_task.get("classification") if isinstance(source_task.get("classification"), dict) else {}
        recommendations = [
            item for item in (recommendation.get("recommendations") or []) if isinstance(item, dict)
        ] if isinstance(recommendation, dict) else []
        summary = recommendation.get("recommendation_summary") if isinstance(recommendation, dict) else {}
        if not isinstance(summary, dict):
            summary = {}
        unit_name = _non_hr_smoke_text(source_task.get("unit_name"))

        resolution: dict[str, Any] = {}
        if unit_name:
            try:
                resolution = resolve_ncs_query_scope(
                    conn,
                    unit_name,
                    major_code=major_code or None,
                    limit=5,
                )
            except Exception as exc:  # pragma: no cover - defensive report path
                resolution = {
                    "ok": False,
                    "error": f"resolve_exception:{type(exc).__name__}",
                    "detail": str(exc),
                }
        candidates = [
            item for item in (resolution.get("candidates") or []) if isinstance(item, dict)
        ]
        top_candidate = candidates[0] if candidates else {}
        top_courses = [_non_hr_smoke_course_name(item) for item in recommendations[:recommendation_limit]]
        top_tiers = [_non_hr_smoke_recommendation_tier(item) for item in recommendations[:recommendation_limit]]
        top_confidence = [
            round(float(item.get("confidence_score") or 0.0), 3)
            for item in recommendations[:recommendation_limit]
        ]
        legacy_flags = _non_hr_smoke_legacy_source_flags(recommendation if isinstance(recommendation, dict) else {})
        recommend_ok = bool(isinstance(recommendation, dict) and recommendation.get("ok"))
        resolve_ok = bool(resolution.get("ok")) if resolution else False
        row.update(
            {
                "query": unit_name,
                "major_name": classification.get("major_name"),
                "sub_name": classification.get("sub_name"),
                "recommend_ok": recommend_ok,
                "resolve_ok": resolve_ok,
                "resolved_candidate_count": len(candidates),
                "top_resolved_candidate": (
                    top_candidate.get("matched_text")
                    or top_candidate.get("unit_name")
                    or top_candidate.get("sub_name")
                ),
                "top_resolved_candidate_type": top_candidate.get("candidate_type"),
                "scope_match_level": (recommendation.get("resolved_scope") or {}).get("match_level")
                if isinstance(recommendation, dict) and isinstance(recommendation.get("resolved_scope"), dict)
                else None,
                "source_task_unit_name": unit_name,
                "source_task_major_name": classification.get("major_name"),
                "recommended_course_count": len(recommendations),
                "primary_recommendation_count": int(summary.get("primary_recommendation_count") or 0),
                "adjacent_recommendation_count": int(summary.get("adjacent_recommendation_count") or 0),
                "top_courses": [name for name in top_courses if name],
                "top_course_tiers": top_tiers,
                "top_course_confidence": top_confidence,
                **legacy_flags,
            }
        )
        row["ok"] = (
            recommend_ok
            and resolve_ok
            and len(recommendations) > 0
            and not row["sqf_used"]
            and not row["learning_modules_used"]
        )
        if not row["ok"]:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "non_hr_smoke_case_failed",
                    "case_id": case_id,
                    "recommend_ok": recommend_ok,
                    "resolve_ok": resolve_ok,
                    "recommended_course_count": len(recommendations),
                    "sqf_used": row["sqf_used"],
                    "learning_modules_used": row["learning_modules_used"],
                }
            )
        rows.append(row)

    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    report: dict[str, Any] = {
        "schema": "ncs_non_hr_query_smoke_v1",
        "generated_at": generated_at,
        "ok": blocker_count == 0,
        "report_only": True,
        "db_writes": False,
        "status_update_allowed": False,
        "approval_claim": False,
        "human_decision_required": False,
        "case_count": len(rows),
        "ok_count": sum(1 for row in rows if row.get("ok")),
        "failed_count": sum(1 for row in rows if not row.get("ok")),
        "major_codes": sorted({_non_hr_smoke_text(row.get("major_code")) for row in rows if row.get("major_code")}),
        "recommendation_limit": recommendation_limit,
        "rows": rows,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_policy": {
            "report_only_smoke_check": True,
            "uses_readonly_sqlite_connection": True,
            "recommendation_calls_use_save_false": True,
            "do_not_write_human_reviewed_accepted_reviewed": True,
            "recommendations_are_not_official_approval": True,
            "sqf_and_learning_modules_must_not_be_active_sources": True,
            "raw_ncs_tables_not_mutated": True,
        },
    }
    sensitive_markers = _aihr_packet_artifact_sensitive_markers(
        json.dumps(report, ensure_ascii=False)
    )
    report["source_payload_exposed"] = bool(sensitive_markers)
    report["sensitive_markers"] = sensitive_markers
    if sensitive_markers:
        report["ok"] = False
        report["findings"].append(
            {
                "severity": "blocker",
                "code": "non_hr_smoke_sensitive_marker_exposed",
                "sensitive_markers": sensitive_markers,
                "message": "Non-HR smoke artifact exposes sensitive source payload markers.",
            }
        )
        report["blocker_count"] = int(report.get("blocker_count") or 0) + 1
        report["failed_count"] = max(
            int(report.get("failed_count") or 0),
            int(report.get("case_count") or 0) - int(report.get("ok_count") or 0),
            1,
        )
    return report


def write_non_hr_query_smoke_markdown(report: dict[str, Any], out_path: Path) -> None:
    lines = [
        "# Non-HR Query Smoke",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- case_count: {report.get('case_count')}",
        f"- ok_count: {report.get('ok_count')}",
        f"- failed_count: {report.get('failed_count')}",
        f"- report_only: {report.get('report_only')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- source_payload_exposed: {report.get('source_payload_exposed')}",
        "",
        "| case | major | query | unit | resolve | recommend | courses | top courses | legacy sources |",
        "|---|---:|---|---|---|---|---:|---|---|",
    ]
    for row in report.get("rows") or []:
        if not isinstance(row, dict):
            continue
        lines.append(
            "| "
            f"{_non_hr_smoke_md_cell(row.get('id'))} | "
            f"{_non_hr_smoke_md_cell(row.get('major_code'))} | "
            f"{_non_hr_smoke_md_cell(row.get('query'))} | "
            f"{_non_hr_smoke_md_cell(row.get('unit_code'))} | "
            f"{row.get('resolve_ok')} | "
            f"{row.get('recommend_ok')} | "
            f"{row.get('recommended_course_count')} | "
            f"{_non_hr_smoke_md_cell(', '.join(str(item) for item in row.get('top_courses') or []))} | "
            f"sqf={row.get('sqf_used')}, lm={row.get('learning_modules_used')} |"
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{_non_hr_smoke_md_cell(finding.get('message') or finding.get('case_id'))}"
            )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Policy",
            "",
            f"- report_only_smoke_check: {policy.get('report_only_smoke_check')}",
            f"- uses_readonly_sqlite_connection: {policy.get('uses_readonly_sqlite_connection')}",
            f"- recommendation_calls_use_save_false: {policy.get('recommendation_calls_use_save_false')}",
            f"- do_not_write_human_reviewed_accepted_reviewed: {policy.get('do_not_write_human_reviewed_accepted_reviewed')}",
            f"- recommendations_are_not_official_approval: {policy.get('recommendations_are_not_official_approval')}",
            f"- sqf_and_learning_modules_must_not_be_active_sources: {policy.get('sqf_and_learning_modules_must_not_be_active_sources')}",
            f"- raw_ncs_tables_not_mutated: {policy.get('raw_ncs_tables_not_mutated')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


