def _non_hr_transition_scope_text(scope: Any) -> str:
    if not isinstance(scope, dict):
        return ""
    return _non_hr_smoke_text(
        scope.get("match_text")
        or scope.get("unit_name")
        or scope.get("sub_name")
        or scope.get("major_name")
    )


def build_non_hr_transition_smoke_report(
    conn: sqlite3.Connection,
    *,
    cases: list[dict[str, Any]] | None = None,
    case_limit: int | None = None,
    recommendation_limit: int = 3,
) -> dict[str, Any]:
    selected_cases = list(cases or DEFAULT_NON_HR_TRANSITION_SMOKE_CASES)
    if case_limit is not None:
        selected_cases = selected_cases[: max(0, case_limit)]
    generated_at = datetime.now(timezone.utc).isoformat()
    rows: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []

    for index, case in enumerate(selected_cases, start=1):
        case_id = _non_hr_smoke_text(case.get("id") or f"case_{index}")
        current_query = _non_hr_smoke_text(case.get("current_query"))
        target_query = _non_hr_smoke_text(case.get("target_query"))
        row: dict[str, Any] = {
            "id": case_id,
            "current_query": current_query,
            "target_query": target_query,
            "current_major_code": _non_hr_smoke_text(case.get("current_major_code")),
            "target_major_code": _non_hr_smoke_text(case.get("target_major_code")),
            "ok": False,
            "recommend_ok": False,
            "status_update_allowed": False,
            "db_writes": False,
            "approval_claim": False,
        }
        if not current_query or not target_query:
            row["error"] = "transition_query_missing"
            findings.append(
                {
                    "severity": "blocker",
                    "code": "transition_query_missing",
                    "case_id": case_id,
                    "message": "Transition smoke case requires current_query and target_query.",
                }
            )
            rows.append(row)
            continue

        try:
            result = recommend_training_transition(
                conn,
                current_query=current_query,
                target_query=target_query,
                current_major_code=row["current_major_code"] or None,
                target_major_code=row["target_major_code"] or None,
                limit=recommendation_limit,
                save=False,
            )
        except Exception as exc:  # pragma: no cover - defensive report path
            row["error"] = f"recommendation_exception:{type(exc).__name__}"
            row["detail"] = str(exc)
            findings.append(
                {
                    "severity": "blocker",
                    "code": "recommendation_exception",
                    "case_id": case_id,
                    "message": str(exc),
                }
            )
            rows.append(row)
            continue

        recommendations = [
            item for item in (result.get("recommendations") or []) if isinstance(item, dict)
        ] if isinstance(result, dict) else []
        summary = result.get("recommendation_summary") if isinstance(result, dict) else {}
        if not isinstance(summary, dict):
            summary = {}
        legacy_flags = _non_hr_smoke_legacy_source_flags(result if isinstance(result, dict) else {})
        top_courses = [_non_hr_smoke_course_name(item) for item in recommendations[:recommendation_limit]]
        top_tiers = [_non_hr_smoke_recommendation_tier(item) for item in recommendations[:recommendation_limit]]
        top_confidence = [
            round(float(item.get("confidence_score") or 0.0), 3)
            for item in recommendations[:recommendation_limit]
        ]
        current_scope = result.get("current_scope") or result.get("resolved_current_scope")
        target_scope = result.get("target_scope") or result.get("resolved_target_scope")
        row.update(
            {
                "recommend_ok": bool(isinstance(result, dict) and result.get("ok")),
                "current_scope": _non_hr_transition_scope_text(current_scope),
                "target_scope": _non_hr_transition_scope_text(target_scope),
                "recommended_course_count": len(recommendations),
                "primary_recommendation_count": int(summary.get("primary_recommendation_count") or 0),
                "adjacent_recommendation_count": int(summary.get("adjacent_recommendation_count") or 0),
                "gap_ksa_concepts_used": int(summary.get("gap_ksa_concepts_used") or 0),
                "training_sequence_stage_count": int(summary.get("training_sequence_stage_count") or 0),
                "top_courses": [name for name in top_courses if name],
                "top_course_tiers": top_tiers,
                "top_course_confidence": top_confidence,
                **legacy_flags,
            }
        )
        row["ok"] = (
            row["recommend_ok"]
            and len(recommendations) > 0
            and not row["sqf_used"]
            and not row["learning_modules_used"]
        )
        if not row["ok"]:
            error = result.get("error") if isinstance(result, dict) and isinstance(result.get("error"), dict) else {}
            row["error_code"] = error.get("code")
            row["error_message"] = error.get("message")
            findings.append(
                {
                    "severity": "blocker",
                    "code": "non_hr_transition_smoke_case_failed",
                    "case_id": case_id,
                    "recommend_ok": row["recommend_ok"],
                    "recommended_course_count": len(recommendations),
                    "sqf_used": row["sqf_used"],
                    "learning_modules_used": row["learning_modules_used"],
                    "error_code": row.get("error_code"),
                    "message": row.get("error_message"),
                }
            )
        rows.append(row)

    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    report: dict[str, Any] = {
        "schema": "ncs_non_hr_transition_smoke_v1",
        "generated_at": generated_at,
        "ok": blocker_count == 0,
        "report_only": True,
        "db_writes": False,
        "status_update_allowed": False,
        "approval_claim": False,
        "human_decision_required": False,
        "case_count": len(rows),
        "ok_count": sum(1 for row in rows if row.get("ok")),
        "failed_count": sum(1 for row in rows if not row.get("ok")),
        "major_codes": sorted(
            {
                code
                for row in rows
                for code in [row.get("current_major_code"), row.get("target_major_code")]
                if code
            }
        ),
        "recommendation_limit": recommendation_limit,
        "rows": rows,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_policy": {
            "report_only_smoke_check": True,
            "uses_readonly_sqlite_connection": True,
            "recommendation_calls_use_save_false": True,
            "do_not_write_human_reviewed_accepted_reviewed": True,
            "recommendations_are_not_official_approval": True,
            "sqf_and_learning_modules_must_not_be_active_sources": True,
            "raw_ncs_tables_not_mutated": True,
        },
    }
    sensitive_markers = _aihr_packet_artifact_sensitive_markers(
        json.dumps(report, ensure_ascii=False)
    )
    report["source_payload_exposed"] = bool(sensitive_markers)
    report["sensitive_markers"] = sensitive_markers
    if sensitive_markers:
        report["ok"] = False
        report["findings"].append(
            {
                "severity": "blocker",
                "code": "non_hr_transition_smoke_sensitive_marker_exposed",
                "sensitive_markers": sensitive_markers,
                "message": "Non-HR transition smoke artifact exposes sensitive source payload markers.",
            }
        )
        report["blocker_count"] = int(report.get("blocker_count") or 0) + 1
        report["failed_count"] = max(
            int(report.get("failed_count") or 0),
            int(report.get("case_count") or 0) - int(report.get("ok_count") or 0),
            1,
        )
    return report


def write_non_hr_transition_smoke_markdown(report: dict[str, Any], out_path: Path) -> None:
    lines = [
        "# Non-HR Transition Smoke",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- case_count: {report.get('case_count')}",
        f"- ok_count: {report.get('ok_count')}",
        f"- failed_count: {report.get('failed_count')}",
        f"- report_only: {report.get('report_only')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- source_payload_exposed: {report.get('source_payload_exposed')}",
        "",
        "| case | majors | transition | recommend | courses | top courses | legacy sources |",
        "|---|---|---|---|---:|---|---|",
    ]
    for row in report.get("rows") or []:
        if not isinstance(row, dict):
            continue
        majors = f"{row.get('current_major_code')} -> {row.get('target_major_code')}"
        transition = f"{row.get('current_query')} -> {row.get('target_query')}"
        lines.append(
            "| "
            f"{_non_hr_smoke_md_cell(row.get('id'))} | "
            f"{_non_hr_smoke_md_cell(majors)} | "
            f"{_non_hr_smoke_md_cell(transition)} | "
            f"{row.get('recommend_ok')} | "
            f"{row.get('recommended_course_count')} | "
            f"{_non_hr_smoke_md_cell(', '.join(str(item) for item in row.get('top_courses') or []))} | "
            f"sqf={row.get('sqf_used')}, lm={row.get('learning_modules_used')} |"
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{_non_hr_smoke_md_cell(finding.get('message') or finding.get('case_id'))}"
            )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Policy",
            "",
            f"- report_only_smoke_check: {policy.get('report_only_smoke_check')}",
            f"- uses_readonly_sqlite_connection: {policy.get('uses_readonly_sqlite_connection')}",
            f"- recommendation_calls_use_save_false: {policy.get('recommendation_calls_use_save_false')}",
            f"- do_not_write_human_reviewed_accepted_reviewed: {policy.get('do_not_write_human_reviewed_accepted_reviewed')}",
            f"- recommendations_are_not_official_approval: {policy.get('recommendations_are_not_official_approval')}",
            f"- sqf_and_learning_modules_must_not_be_active_sources: {policy.get('sqf_and_learning_modules_must_not_be_active_sources')}",
            f"- raw_ncs_tables_not_mutated: {policy.get('raw_ncs_tables_not_mutated')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _non_hr_education_plan_course_name(row: dict[str, Any]) -> str:
    course_link = row.get("course_link") if isinstance(row.get("course_link"), dict) else {}
    course_fit = row.get("course_fit") if isinstance(row.get("course_fit"), dict) else {}
    return _non_hr_smoke_text(
        row.get("course_name")
        or course_link.get("course_name")
        or course_fit.get("course_name")
        or row.get("training_course_name")
        or row.get("training_course_id")
    )


def _non_hr_education_plan_route_summary(route: Any) -> dict[str, Any]:
    if not isinstance(route, dict):
        return {
            "query_route_schema": None,
            "query_route_tool": None,
            "query_route_fingerprint": None,
            "query_route_expected_tool_chain": [],
            "query_route_contract_schema": None,
            "query_route_contract_primary_tool": None,
            "query_route_contract_fingerprint": None,
            "query_route_guard_flags": [],
        }
    contract = route.get("route_contract") if isinstance(route.get("route_contract"), dict) else {}
    return {
        "query_route_schema": route.get("schema"),
        "query_route_tool": route.get("tool"),
        "query_route_fingerprint": route.get("route_fingerprint"),
        "query_route_expected_tool_chain": route.get("expected_tool_chain") or [],
        "query_route_contract_schema": contract.get("schema"),
        "query_route_contract_primary_tool": contract.get("primary_tool"),
        "query_route_contract_fingerprint": contract.get("route_fingerprint"),
        "query_route_guard_flags": [
            flag.get("code")
            for flag in route.get("guard_flags", [])
            if isinstance(flag, dict) and flag.get("code")
        ],
    }


def build_non_hr_education_plan_smoke_report(
    conn: sqlite3.Connection,
    *,
    cases: list[dict[str, Any]] | None = None,
    case_limit: int | None = None,
    recommendation_limit: int = 3,
    preferred_max_hours: int | None = None,
    preferred_methods: list[str] | None = None,
    preferred_facilities: list[str] | None = None,
    plan_objective: str | None = None,
    target_population: str | None = None,
    scenario: str | None = None,
) -> dict[str, Any]:
    selected_cases = list(cases or DEFAULT_NON_HR_TRANSITION_SMOKE_CASES)
    if case_limit is not None:
        selected_cases = selected_cases[: max(0, case_limit)]
    generated_at = datetime.now(timezone.utc).isoformat()
    rows: list[dict[str, Any]] = []
    findings: list[dict[str, Any]] = []

    for index, case in enumerate(selected_cases, start=1):
        case_id = _non_hr_smoke_text(case.get("id") or f"case_{index}")
        current_query = _non_hr_smoke_text(case.get("current_query"))
        target_query = _non_hr_smoke_text(case.get("target_query"))
        row: dict[str, Any] = {
            "id": case_id,
            "current_query": current_query,
            "target_query": target_query,
            "current_major_code": _non_hr_smoke_text(case.get("current_major_code")),
            "target_major_code": _non_hr_smoke_text(case.get("target_major_code")),
            "ok": False,
            "recommend_ok": False,
            "plan_ok": False,
            "status_update_allowed": False,
            "db_writes": False,
            "approval_claim": False,
        }
        if not current_query or not target_query:
            row["error"] = "education_plan_query_missing"
            findings.append(
                {
                    "severity": "blocker",
                    "code": "education_plan_query_missing",
                    "case_id": case_id,
                    "message": "Education-plan smoke case requires current_query and target_query.",
                }
            )
            rows.append(row)
            continue

        try:
            result = recommend_training_transition(
                conn,
                current_query=current_query,
                target_query=target_query,
                current_major_code=row["current_major_code"] or None,
                target_major_code=row["target_major_code"] or None,
                mode="all",
                preferred_max_hours=preferred_max_hours,
                preferred_methods=preferred_methods or [],
                preferred_facilities=preferred_facilities or [],
                limit=recommendation_limit,
                save=False,
            )
            plan = compact_ncs_education_plan_response(
                result,
                plan_objective=plan_objective,
                target_population=target_population,
                scenario=scenario,
                recommendation_limit=recommendation_limit,
            )
            route_evidence = _aihr_public_route_evidence(current_query, target_query)
            plan["query_route"] = route_evidence
            plan["route_contract_schema"] = (
                route_evidence.get("route_contract", {}).get("schema")
                if isinstance(route_evidence.get("route_contract"), dict)
                else route_evidence.get("schema")
            )
            plan["route_fingerprint"] = route_evidence.get("route_fingerprint")
        except Exception as exc:  # pragma: no cover - defensive report path
            row["error"] = f"education_plan_exception:{type(exc).__name__}"
            row["detail"] = str(exc)
            findings.append(
                {
                    "severity": "blocker",
                    "code": "education_plan_exception",
                    "case_id": case_id,
                    "message": str(exc),
                }
            )
            rows.append(row)
            continue

        matrix_rows = plan.get("training_system_matrix") if isinstance(plan.get("training_system_matrix"), list) else []
        recommended_path = plan.get("recommended_path") if isinstance(plan.get("recommended_path"), list) else []
        guide_trace = (
            plan.get("training_system_guide_trace")
            if isinstance(plan.get("training_system_guide_trace"), dict)
            else {}
        )
        route = plan.get("query_route") if isinstance(plan.get("query_route"), dict) else {}
        missing_matrix_fields = _missing_aihr_matrix_fields(matrix_rows)
        missing_plan_fields = _missing_aihr_plan_fields(plan)
        missing_guide_trace_fields = _missing_aihr_guide_trace_fields(plan)
        missing_query_route_fields = _missing_aihr_query_route_fields(plan)
        legacy_flags = _non_hr_smoke_legacy_source_flags(result if isinstance(result, dict) else {})
        top_courses = [
            _non_hr_education_plan_course_name(item)
            for item in matrix_rows[:recommendation_limit]
            if isinstance(item, dict)
        ]
        row.update(
            {
                "recommend_ok": bool(isinstance(result, dict) and result.get("ok")),
                "plan_ok": bool(plan.get("ok") is True and plan.get("view") == "ncs_education_plan"),
                "view": plan.get("view"),
                "matrix_rows": len(matrix_rows),
                "recommended_path_stage_count": len(recommended_path),
                "guide_trace_schema": guide_trace.get("schema"),
                "guide_trace_check_count": len(
                    guide_trace.get("checks") if isinstance(guide_trace.get("checks"), list) else []
                ),
                "guide_trace_check_codes": sorted(
                    {
                        str(check.get("code") or check.get("check"))
                        for check in (
                            guide_trace.get("checks")
                            if isinstance(guide_trace.get("checks"), list)
                            else []
                        )
                        if isinstance(check, dict) and (check.get("code") or check.get("check"))
                    }
                ),
                "guide_workflow_stage_codes": sorted(
                    {
                        str(stage.get("code"))
                        for stage in (
                            guide_trace.get("guide_workflow_stages")
                            if isinstance(guide_trace.get("guide_workflow_stages"), list)
                            else []
                        )
                        if isinstance(stage, dict) and stage.get("code")
                    }
                ),
                "training_system_summary_keys": sorted(
                    str(key)
                    for key in (
                        plan.get("training_system_summary").keys()
                        if isinstance(plan.get("training_system_summary"), dict)
                        else []
                    )
                ),
                "top_courses": [name for name in top_courses if name],
                "missing_matrix_fields": missing_matrix_fields,
                "missing_plan_fields": missing_plan_fields,
                "missing_guide_trace_fields": missing_guide_trace_fields,
                "missing_query_route_fields": missing_query_route_fields,
                **_non_hr_education_plan_route_summary(route),
                **legacy_flags,
            }
        )
        row["ok"] = (
            row["recommend_ok"]
            and row["plan_ok"]
            and row["matrix_rows"] > 0
            and row["recommended_path_stage_count"] > 0
            and not row["missing_matrix_fields"]
            and not row["missing_plan_fields"]
            and not row["missing_guide_trace_fields"]
            and not row["missing_query_route_fields"]
            and not row["sqf_used"]
            and not row["learning_modules_used"]
        )
        if not row["ok"]:
            error = result.get("error") if isinstance(result, dict) and isinstance(result.get("error"), dict) else {}
            findings.append(
                {
                    "severity": "blocker",
                    "code": "non_hr_education_plan_smoke_case_failed",
                    "case_id": case_id,
                    "recommend_ok": row["recommend_ok"],
                    "plan_ok": row["plan_ok"],
                    "matrix_rows": row["matrix_rows"],
                    "recommended_path_stage_count": row["recommended_path_stage_count"],
                    "missing_matrix_fields": missing_matrix_fields[:20],
                    "missing_plan_fields": missing_plan_fields[:20],
                    "missing_guide_trace_fields": missing_guide_trace_fields[:20],
                    "missing_query_route_fields": missing_query_route_fields[:20],
                    "sqf_used": row["sqf_used"],
                    "learning_modules_used": row["learning_modules_used"],
                    "error_code": error.get("code"),
                    "message": error.get("message"),
                }
            )
        rows.append(row)

    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    report: dict[str, Any] = {
        "schema": "ncs_non_hr_education_plan_smoke_v1",
        "generated_at": generated_at,
        "ok": blocker_count == 0,
        "report_only": True,
        "db_writes": False,
        "status_update_allowed": False,
        "approval_claim": False,
        "human_decision_required": False,
        "case_count": len(rows),
        "ok_count": sum(1 for row in rows if row.get("ok")),
        "failed_count": sum(1 for row in rows if not row.get("ok")),
        "major_codes": sorted(
            {
                code
                for row in rows
                for code in [row.get("current_major_code"), row.get("target_major_code")]
                if code
            }
        ),
        "recommendation_limit": recommendation_limit,
        "preferred_max_hours": preferred_max_hours,
        "preferred_methods": preferred_methods or [],
        "preferred_facilities": preferred_facilities or [],
        "rows": rows,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_policy": {
            "report_only_smoke_check": True,
            "uses_readonly_sqlite_connection": True,
            "recommendation_calls_use_save_false": True,
            "education_plan_compaction_only": True,
            "do_not_write_human_reviewed_accepted_reviewed": True,
            "recommendations_are_not_official_approval": True,
            "sqf_and_learning_modules_must_not_be_active_sources": True,
            "raw_ncs_tables_not_mutated": True,
        },
    }
    sensitive_markers = _aihr_packet_artifact_sensitive_markers(
        json.dumps(report, ensure_ascii=False)
    )
    report["source_payload_exposed"] = bool(sensitive_markers)
    report["sensitive_markers"] = sensitive_markers
    if sensitive_markers:
        report["ok"] = False
        report["findings"].append(
            {
                "severity": "blocker",
                "code": "non_hr_education_plan_smoke_sensitive_marker_exposed",
                "sensitive_markers": sensitive_markers,
                "message": "Non-HR education-plan smoke artifact exposes sensitive source payload markers.",
            }
        )
        report["blocker_count"] = int(report.get("blocker_count") or 0) + 1
        report["failed_count"] = max(
            int(report.get("failed_count") or 0),
            int(report.get("case_count") or 0) - int(report.get("ok_count") or 0),
            1,
        )
    return report


def write_non_hr_education_plan_smoke_markdown(report: dict[str, Any], out_path: Path) -> None:
    lines = [
        "# Non-HR Education Plan Smoke",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- generated_at: {report.get('generated_at')}",
        f"- case_count: {report.get('case_count')}",
        f"- ok_count: {report.get('ok_count')}",
        f"- failed_count: {report.get('failed_count')}",
        f"- report_only: {report.get('report_only')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- source_payload_exposed: {report.get('source_payload_exposed')}",
        "",
        "| case | majors | transition | plan | rows | path | missing | route | top courses | legacy sources |",
        "|---|---|---|---|---:|---:|---|---|---|---|",
    ]
    for row in report.get("rows") or []:
        if not isinstance(row, dict):
            continue
        majors = f"{row.get('current_major_code')} -> {row.get('target_major_code')}"
        transition = f"{row.get('current_query')} -> {row.get('target_query')}"
        missing_counts = (
            f"matrix={len(row.get('missing_matrix_fields') or [])}, "
            f"plan={len(row.get('missing_plan_fields') or [])}, "
            f"trace={len(row.get('missing_guide_trace_fields') or [])}, "
            f"route={len(row.get('missing_query_route_fields') or [])}"
        )
        route = f"{row.get('query_route_tool')}:{row.get('query_route_fingerprint')}"
        lines.append(
            "| "
            f"{_non_hr_smoke_md_cell(row.get('id'))} | "
            f"{_non_hr_smoke_md_cell(majors)} | "
            f"{_non_hr_smoke_md_cell(transition)} | "
            f"{row.get('plan_ok')} | "
            f"{row.get('matrix_rows')} | "
            f"{row.get('recommended_path_stage_count')} | "
            f"{_non_hr_smoke_md_cell(missing_counts)} | "
            f"{_non_hr_smoke_md_cell(route)} | "
            f"{_non_hr_smoke_md_cell(', '.join(str(item) for item in row.get('top_courses') or []))} | "
            f"sqf={row.get('sqf_used')}, lm={row.get('learning_modules_used')} |"
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{_non_hr_smoke_md_cell(finding.get('message') or finding.get('case_id'))}"
            )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Policy",
            "",
            f"- report_only_smoke_check: {policy.get('report_only_smoke_check')}",
            f"- uses_readonly_sqlite_connection: {policy.get('uses_readonly_sqlite_connection')}",
            f"- recommendation_calls_use_save_false: {policy.get('recommendation_calls_use_save_false')}",
            f"- education_plan_compaction_only: {policy.get('education_plan_compaction_only')}",
            f"- do_not_write_human_reviewed_accepted_reviewed: {policy.get('do_not_write_human_reviewed_accepted_reviewed')}",
            f"- recommendations_are_not_official_approval: {policy.get('recommendations_are_not_official_approval')}",
            f"- sqf_and_learning_modules_must_not_be_active_sources: {policy.get('sqf_and_learning_modules_must_not_be_active_sources')}",
            f"- raw_ncs_tables_not_mutated: {policy.get('raw_ncs_tables_not_mutated')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _as_optional_int(value: Any) -> int | None:
    try:
        if value is None or str(value).strip() == "":
            return None
        return int(value)
    except (TypeError, ValueError):
        return None


def _seedpack_scope_clause(
    *,
    alias: str,
    major_code: str | None,
    middle_code: str | None,
    small_code: str | None,
    sub_code: str | None,
) -> tuple[str, list[Any]]:
    clauses: list[str] = []
    params: list[Any] = []
    for column, value in (
        ("major_code", major_code),
        ("middle_code", middle_code),
        ("small_code", small_code),
        ("sub_code", sub_code),
    ):
        if value:
            clauses.append(f"{alias}.{column} = ?")
            params.append(value)
    if not clauses:
        return "", []
    return " AND " + " AND ".join(clauses), params


def _add_aihr_seedpack_item(items: list[dict[str, Any]], item: dict[str, Any], created_at: str) -> None:
    item.update(
        {
            "schema": "aihr_plan_review_seedpack_item_v1",
            "created_at": created_at,
            "approval_claim": False,
            "db_writes": False,
            "allowed_decisions": _aihr_plan_review_allowed_decisions(),
            "human_decision_required": True,
        }
    )
    items.append(item)


def _aihr_seedpack_scope_metadata(scope_fit: dict[str, Any], target_scope: dict[str, Any]) -> dict[str, Any]:
    course_scope = (
        scope_fit.get("course_scope") if isinstance(scope_fit.get("course_scope"), dict) else {}
    )
    direct_unit_codes = scope_fit.get("direct_unit_codes") if isinstance(scope_fit.get("direct_unit_codes"), list) else []
    direct_unit_code = next((str(code).strip() for code in direct_unit_codes if str(code).strip()), "")
    metadata: dict[str, Any] = {}
    if direct_unit_code:
        metadata["ncs_cl_cd"] = direct_unit_code
    for key in ("major_code", "middle_code", "small_code", "sub_code"):
        value = target_scope.get(key) or course_scope.get(key)
        if value not in (None, ""):
            metadata[key] = value
    return metadata


def _aihr_enrich_plan_contexts_with_course_meta(
    contexts: list[dict[str, Any]],
    course_meta_by_id: dict[int, dict[str, Any]],
) -> list[dict[str, Any]]:
    enriched: list[dict[str, Any]] = []
    for context in contexts:
        normalized = dict(context)
        course_id = _as_optional_int(normalized.get("course_id"))
        metadata = course_meta_by_id.get(course_id or -1, {})
        for key, value in metadata.items():
            if value not in (None, "") and normalized.get(key) in (None, ""):
                normalized[key] = value
        enriched.append(normalized)
    return enriched


def _aihr_enrich_plan_contexts_with_review_basis(
    contexts: list[dict[str, Any]],
    review_basis_by_course_id: dict[int, dict[str, Any]],
) -> list[dict[str, Any]]:
    enriched: list[dict[str, Any]] = []
    for context in contexts:
        normalized = dict(context)
        course_id = _as_optional_int(normalized.get("course_id"))
        basis = review_basis_by_course_id.get(course_id or -1, {})
        for key in (
            "learning_module_review_basis",
            "ncs_report_review_basis",
            "review_basis_sources",
        ):
            if basis.get(key) not in (None, "", [], {}) and normalized.get(key) in (None, "", [], {}):
                normalized[key] = basis[key]
        enriched.append(normalized)
    return enriched


def _aihr_seedpack_first_context_values(
    contexts: list[dict[str, Any]],
    keys: tuple[str, ...] = ("ncs_cl_cd", "major_code", "middle_code", "small_code", "sub_code"),
) -> dict[str, Any]:
    values: dict[str, Any] = {}
    for key in keys:
        value = next(
            (
                context.get(key)
                for context in contexts
                if isinstance(context, dict) and context.get(key) not in (None, "")
            ),
            None,
        )
        if value not in (None, ""):
            values[key] = value
    return values


def _aihr_review_status_counts(rows: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        status = str(row.get("review_status") or "unknown")
        counts[status] = counts.get(status, 0) + 1
    return dict(sorted(counts.items()))


def _aihr_text_summary(value: Any, limit: int = 180) -> str:
    text = " ".join(str(value or "").split())
    if len(text) <= limit:
        return text
    if limit <= 3:
        return text[:limit]
    return f"{text[: limit - 3].rstrip()}..."


def _aihr_text_summary_fields(value: Any, limit: int = 180) -> dict[str, Any]:
    text = " ".join(str(value or "").split())
    return {
        "evidence_summary": _aihr_text_summary(text, limit=limit),
        "evidence_summary_truncated": len(text) > limit,
        "evidence_summary_original_length": len(text),
        "evidence_summary_limit": limit,
    }


AIHR_REVIEW_BASIS_COUNTS_MEANING = (
    "Existing upstream evidence review-state counts only; not approval of this row."
)
AIHR_LEGACY_UPSTREAM_STATUS_DISPLAY_PREFIX = (
    "legacy_upstream_state_not_current_approval"
)


def _aihr_legacy_upstream_status_display(value: Any) -> str | None:
    status = str(value or "").strip()
    if not status:
        return None
    return f"{AIHR_LEGACY_UPSTREAM_STATUS_DISPLAY_PREFIX}:{status}"


AIHR_REVIEW_BASIS_BLOCKED_KEYS = {
    "source_payload",
    "raw_payload",
    "raw_response",
    "source_json",
    "source_rows",
    "authKey",
    "auth_key",
    "serviceKey",
    "service_key",
    "apiKey",
    "api_key",
    "access_token",
    "token",
    "secret",
    "password",
    "certKey",
    "NCS_SERVICE_KEY",
    "NCS_TRAINING_COURSE_SERVICE_KEY",
    "NCS_QUALIFICATION_SERVICE_KEY",
    "NCS_JOB_BASE_SERVICE_KEY",
    "Authorization",
    "Bearer",
}
AIHR_REVIEW_BASIS_BLOCKED_KEYS_LOWER = {
    key.lower() for key in AIHR_REVIEW_BASIS_BLOCKED_KEYS
}
AIHR_REVIEW_BASIS_FORCE_FALSE_KEYS_LOWER = {
    "approval_claim",
    "db_writes",
    "status_update_allowed",
    "active_scoring_source",
}
AIHR_REVIEW_BASIS_FORCE_TRUE_KEYS_LOWER = {
    "review_only",
    "non_scoring",
}
AIHR_REVIEW_BASIS_TEXT_REDACTION_MARKERS = sorted(
    AIHR_REVIEW_BASIS_BLOCKED_KEYS | AIHR_PACKET_ARTIFACT_SENSITIVE_MARKERS,
    key=len,
    reverse=True,
)


def _aihr_review_only_basis_policy() -> dict[str, Any]:
    return {
        "review_only": True,
        "non_scoring": True,
        "review_status_counts_meaning": AIHR_REVIEW_BASIS_COUNTS_MEANING,
        "approval_claim": False,
        "db_writes": False,
        "status_update_allowed": False,
        "active_scoring_source": False,
    }


def _aihr_sanitize_review_basis_value(value: Any) -> Any:
    if isinstance(value, dict):
        result: dict[str, Any] = {}
        for key, child in value.items():
            key_lower = str(key).lower()
            if key_lower in AIHR_REVIEW_BASIS_BLOCKED_KEYS_LOWER:
                continue
            if key_lower in AIHR_REVIEW_BASIS_FORCE_FALSE_KEYS_LOWER:
                result[key] = False
                continue
            if key_lower in AIHR_REVIEW_BASIS_FORCE_TRUE_KEYS_LOWER:
                result[key] = True
                continue
            result[key] = _aihr_sanitize_review_basis_value(child)
        return result
    if isinstance(value, list):
        return [_aihr_sanitize_review_basis_value(child) for child in value]
    if isinstance(value, str):
        sanitized = value
        for marker in AIHR_REVIEW_BASIS_TEXT_REDACTION_MARKERS:
            pattern = re.compile(
                rf"{re.escape(marker)}\s*[=:]\s*[^&\s,;]+",
                re.IGNORECASE,
            )
            sanitized = pattern.sub("[REDACTED]", sanitized)
            marker_pattern = re.compile(re.escape(marker), re.IGNORECASE)
            sanitized = marker_pattern.sub("[REDACTED]", sanitized)
        return sanitized
    return value


def _aihr_review_basis_with_policy(basis: dict[str, Any]) -> dict[str, Any]:
    result = _aihr_sanitize_review_basis_value(dict(basis))
    for key, value in _aihr_review_only_basis_policy().items():
        result[key] = value
    return result


def _aihr_review_basis_status(rows: list[dict[str, Any]], *, visible_status: str) -> str:
    if rows:
        return visible_status
    return "missing"


def _aihr_learning_module_non_official_direct_diagnostics(
    conn: sqlite3.Connection,
    *,
    ncs_code: str,
    limit: int = 5,
) -> dict[str, Any]:
    diagnostic_rows = conn.execute(
        """
        SELECT
            CASE
                WHEN lm.learn_module_seq LIKE 'REPORT-TRAINING-%'
                    THEN 'report_training_course'
                WHEN lm.learn_module_seq LIKE 'NCS-DERIVED-%'
                    THEN 'ncs_derived_learning_plan'
                ELSE 'official_learning_module'
            END AS basis_kind,
            lm.learn_module_seq,
            lm.learn_module_name,
            link.unit_code,
            link.link_method,
            link.review_status,
            link.confidence_score,
            link.evidence_text
        FROM learning_module_unit_links link
        JOIN ncs_learning_modules lm ON lm.learn_module_seq = link.learn_module_seq
        LEFT JOIN competency_units cu ON cu.unit_code = link.unit_code
        WHERE (link.unit_code = ? OR cu.base_unit_code = ? OR cu.unit_code = ?)
          AND (
            lm.learn_module_seq LIKE 'REPORT-TRAINING-%'
            OR lm.learn_module_seq LIKE 'NCS-DERIVED-%'
          )
          AND link.review_status != 'rejected'
        ORDER BY
            CASE
                WHEN lm.learn_module_seq LIKE 'NCS-DERIVED-%' THEN 0
                WHEN lm.learn_module_seq LIKE 'REPORT-TRAINING-%' THEN 1
                ELSE 2
            END,
            CASE link.review_status
                WHEN 'human_reviewed' THEN 0
                WHEN 'reviewed' THEN 1
                WHEN 'accepted' THEN 2
                ELSE 3
            END,
            link.confidence_score DESC,
            lm.learn_module_seq
        LIMIT ?
        """,
        (ncs_code, ncs_code, ncs_code, clamp_limit(limit, default=5, maximum=20)),
    ).fetchall()
    count_rows = conn.execute(
        """
        SELECT
            CASE
                WHEN lm.learn_module_seq LIKE 'REPORT-TRAINING-%'
                    THEN 'report_training_course'
                WHEN lm.learn_module_seq LIKE 'NCS-DERIVED-%'
                    THEN 'ncs_derived_learning_plan'
                ELSE 'official_learning_module'
            END AS basis_kind,
            COUNT(*) AS count
        FROM learning_module_unit_links link
        JOIN ncs_learning_modules lm ON lm.learn_module_seq = link.learn_module_seq
        LEFT JOIN competency_units cu ON cu.unit_code = link.unit_code
        WHERE (link.unit_code = ? OR cu.base_unit_code = ? OR cu.unit_code = ?)
          AND (
            lm.learn_module_seq LIKE 'REPORT-TRAINING-%'
            OR lm.learn_module_seq LIKE 'NCS-DERIVED-%'
          )
          AND link.review_status != 'rejected'
        GROUP BY basis_kind
        """,
        (ncs_code, ncs_code, ncs_code),
    ).fetchall()
    counts = {str(row["basis_kind"]): int(row["count"] or 0) for row in count_rows}
    samples = [
        {
            "basis_kind": row["basis_kind"],
            "learn_module_seq": row["learn_module_seq"],
            "learn_module_name": row["learn_module_name"],
            "unit_code": row["unit_code"],
            "link_method": row["link_method"],
            "upstream_state": row["review_status"],
            "upstream_state_display": _aihr_legacy_upstream_status_display(
                row["review_status"]
            ),
            "upstream_state_role": (
                "legacy_source_state_for_reconfirmation_only_not_current_approval"
            ),
            "confidence_score": row["confidence_score"],
            **_aihr_text_summary_fields(row["evidence_text"]),
        }
        for row in diagnostic_rows
    ]
    return {
        "direct_non_official_counts": counts,
        "direct_non_official_samples": samples,
    }


def _aihr_non_official_diagnostic_review_basis(
    conn: sqlite3.Connection,
    *,
    ncs_cl_cd: str | None,
    limit: int = 5,
) -> dict[str, Any]:
    ncs_code = str(ncs_cl_cd or "").strip()
    if not ncs_code:
        return {
            "schema": "aihr_non_official_diagnostic_basis_v1",
            "status": "missing_ncs_code",
            "basis_role": "non_official_human_review_diagnostic_only",
            "direct_non_official_counts": {},
            "direct_non_official_samples": [],
            **_aihr_review_only_basis_policy(),
        }
    try:
        diagnostic = _aihr_learning_module_non_official_direct_diagnostics(
            conn,
            ncs_code=ncs_code,
            limit=limit,
        )
    except sqlite3.OperationalError as exc:
        return {
            "schema": "aihr_non_official_diagnostic_basis_v1",
            "status": "not_available",
            "basis_role": "non_official_human_review_diagnostic_only",
            "direct_non_official_counts": {},
            "direct_non_official_samples": [],
            "error": str(exc),
            **_aihr_review_only_basis_policy(),
        }
    counts = diagnostic.get("direct_non_official_counts") or {}
    return {
        "schema": "aihr_non_official_diagnostic_basis_v1",
        "status": "diagnostic_basis_visible" if counts else "missing",
        "basis_role": "non_official_human_review_diagnostic_only",
        "ncs_cl_cd": ncs_code,
        "direct_non_official_counts": counts,
        "direct_non_official_samples": diagnostic.get("direct_non_official_samples") or [],
        "official_learning_module": False,
        "counts_as_official_learning_module": False,
        "decision_sheet_prefill_allowed": False,
        "review_gap_action": (
            "Use only as Human Review context. REPORT-TRAINING and NCS-DERIVED rows "
            "must not be treated as official learning modules or scoring evidence."
        ),
        **_aihr_review_only_basis_policy(),
    }


def _aihr_learning_module_review_basis(
    conn: sqlite3.Connection,
    *,
    ncs_cl_cd: str | None,
    limit: int = 5,
) -> dict[str, Any]:
    ncs_code = str(ncs_cl_cd or "").strip()
    if not ncs_code:
        return {
            "schema": "aihr_learning_module_review_basis_v1",
            "status": "missing_ncs_code",
            "basis_role": "auxiliary_human_review_evidence",
            "official_module_count": 0,
            "trusted_link_count": 0,
            "review_status_counts": {},
            "modules": [],
            **_aihr_review_only_basis_policy(),
        }
    try:
        rows = conn.execute(
            """
            SELECT
                lm.learn_module_seq,
                lm.learn_module_name,
                link.unit_code,
                link.link_method,
                link.review_status,
                link.confidence_score,
                link.evidence_text
            FROM learning_module_unit_links link
            JOIN ncs_learning_modules lm ON lm.learn_module_seq = link.learn_module_seq
            LEFT JOIN competency_units cu ON cu.unit_code = link.unit_code
            WHERE (link.unit_code = ? OR cu.base_unit_code = ? OR cu.unit_code = ?)
              AND lm.learn_module_seq NOT LIKE 'REPORT-TRAINING-%'
              AND lm.learn_module_seq NOT LIKE 'NCS-DERIVED-%'
              AND link.review_status != 'rejected'
            ORDER BY
                CASE link.review_status
                    WHEN 'human_reviewed' THEN 0
                    WHEN 'reviewed' THEN 1
                    WHEN 'accepted' THEN 2
                    ELSE 3
                END,
                link.confidence_score DESC,
                lm.learn_module_seq
            LIMIT ?
            """,
            (ncs_code, ncs_code, ncs_code, clamp_limit(limit, default=5, maximum=20)),
        ).fetchall()
        non_official_diagnostic = _aihr_learning_module_non_official_direct_diagnostics(
            conn,
            ncs_code=ncs_code,
            limit=limit,
        )
    except sqlite3.OperationalError as exc:
        return {
            "schema": "aihr_learning_module_review_basis_v1",
            "status": "not_available",
            "basis_role": "auxiliary_human_review_evidence",
            "official_module_count": 0,
            "trusted_link_count": 0,
            "review_status_counts": {},
            "modules": [],
            "error": str(exc),
            **_aihr_review_only_basis_policy(),
        }
    modules = [
        {
            "learn_module_seq": row["learn_module_seq"],
            "learn_module_name": row["learn_module_name"],
            "unit_code": row["unit_code"],
            "link_method": row["link_method"],
            "review_status": row["review_status"],
            "review_status_display": _aihr_legacy_upstream_status_display(
                row["review_status"]
            ),
            "review_status_role": (
                "legacy_source_state_for_reconfirmation_only_not_current_approval"
            ),
            "confidence_score": row["confidence_score"],
            **_aihr_text_summary_fields(row["evidence_text"]),
        }
        for row in rows
    ]
    trusted_count = sum(
        1
        for row in modules
        if row.get("review_status") in {"human_reviewed", "reviewed", "accepted"}
    )
    non_official_counts = non_official_diagnostic.get("direct_non_official_counts") or {}
    if modules:
        gap_reason = None
    elif non_official_counts:
        gap_reason = (
            "no_official_direct_learning_module_link_but_report_or_derived_basis_exists"
        )
    else:
        gap_reason = "no_official_direct_learning_module_link"
    return {
        "schema": "aihr_learning_module_review_basis_v1",
        "status": _aihr_review_basis_status(
            modules,
            visible_status="official_learning_module_link_visible",
        ),
        "basis_role": "auxiliary_human_review_evidence",
        "ncs_cl_cd": ncs_code,
        "official_module_count": len(modules),
        "trusted_link_count": trusted_count,
        "review_status_counts": _aihr_review_status_counts(modules),
        "modules": modules,
        "gap_reason": gap_reason,
        "direct_non_official_counts": non_official_counts,
        "review_gap_action": (
            "Use NCS report/reference evidence for human review when official learning "
            "module links are absent; do not treat report-derived or generated plans as "
            "official learning modules or scoring evidence."
        ),
        **_aihr_review_only_basis_policy(),
    }


def _aihr_ncs_report_review_basis(
    conn: sqlite3.Connection,
    *,
    ncs_cl_cd: str | None,
    limit: int = 5,
) -> dict[str, Any]:
    ncs_code = str(ncs_cl_cd or "").strip()
    if not ncs_code:
        return {
            "schema": "aihr_ncs_report_review_basis_v1",
            "status": "missing_ncs_code",
            "basis_role": "human_review_methodology_and_auxiliary_course_evidence",
            "report_training_course_count": 0,
            "reference_link_count": 0,
            "report_training_courses": [],
            "reference_chunks": [],
            **_aihr_review_only_basis_policy(),
        }
    try:
        report_module_rows = conn.execute(
            """
            SELECT
                lm.learn_module_seq,
                lm.learn_module_name,
                link.unit_code,
                link.link_method,
                link.review_status,
                link.confidence_score,
                link.evidence_text
            FROM learning_module_unit_links link
            JOIN ncs_learning_modules lm ON lm.learn_module_seq = link.learn_module_seq
            LEFT JOIN competency_units cu ON cu.unit_code = link.unit_code
            WHERE (link.unit_code = ? OR cu.base_unit_code = ? OR cu.unit_code = ?)
              AND lm.learn_module_seq LIKE 'REPORT-TRAINING-%'
              AND link.review_status != 'rejected'
            ORDER BY
                CASE link.review_status
                    WHEN 'human_reviewed' THEN 0
                    WHEN 'reviewed' THEN 1
                    WHEN 'accepted' THEN 2
                    ELSE 3
                END,
                link.confidence_score DESC,
                lm.learn_module_seq
            LIMIT ?
            """,
            (ncs_code, ncs_code, ncs_code, clamp_limit(limit, default=5, maximum=20)),
        ).fetchall()
        reference_rows = conn.execute(
            """
            SELECT
                l.link_id,
                e.entity_type,
                e.entity_text,
                l.review_status,
                l.confidence_score,
                l.evidence_summary,
                c.chunk_id,
                c.page_start,
                c.page_end,
                d.document_id,
                d.title
            FROM ncs_reference_entity_links l
            JOIN ncs_reference_entities e ON e.entity_id = l.entity_id
            JOIN ncs_reference_chunks c ON c.chunk_id = e.chunk_id
            JOIN ncs_reference_documents d ON d.document_id = c.document_id
            LEFT JOIN competency_units cu ON cu.unit_code = l.target_id
            WHERE l.target_type = 'ncs_competency_unit'
              AND (l.target_id = ? OR cu.base_unit_code = ? OR cu.unit_code = ?)
              AND l.review_status != 'rejected'
            ORDER BY l.confidence_score DESC, l.link_id
            LIMIT ?
            """,
            (ncs_code, ncs_code, ncs_code, clamp_limit(limit, default=5, maximum=20)),
        ).fetchall()
    except sqlite3.OperationalError as exc:
        return {
            "schema": "aihr_ncs_report_review_basis_v1",
            "status": "not_available",
            "basis_role": "human_review_methodology_and_auxiliary_course_evidence",
            "report_training_course_count": 0,
            "reference_link_count": 0,
            "report_training_courses": [],
            "reference_chunks": [],
            "error": str(exc),
            **_aihr_review_only_basis_policy(),
        }
    report_training_courses = [
        {
            "learn_module_seq": row["learn_module_seq"],
            "learn_module_name": row["learn_module_name"],
            "unit_code": row["unit_code"],
            "link_method": row["link_method"],
            "review_status": row["review_status"],
            "confidence_score": row["confidence_score"],
            **_aihr_text_summary_fields(row["evidence_text"]),
        }
        for row in report_module_rows
    ]
    reference_chunks = [
        {
            "link_id": row["link_id"],
            "document_id": row["document_id"],
            "document_title": row["title"],
            "chunk_id": row["chunk_id"],
            "page_start": row["page_start"],
            "page_end": row["page_end"],
            "entity_type": row["entity_type"],
            "entity_text": row["entity_text"],
            "review_status": row["review_status"],
            "confidence_score": row["confidence_score"],
            **_aihr_text_summary_fields(row["evidence_summary"]),
        }
        for row in reference_rows
    ]
    visible = bool(report_training_courses or reference_chunks)
    return {
        "schema": "aihr_ncs_report_review_basis_v1",
        "status": "report_basis_visible" if visible else "missing",
        "basis_role": "human_review_methodology_and_auxiliary_course_evidence",
        "ncs_cl_cd": ncs_code,
        "report_training_course_count": len(report_training_courses),
        "reference_link_count": len(reference_chunks),
        "report_training_course_status_counts": _aihr_review_status_counts(report_training_courses),
        "reference_link_status_counts": _aihr_review_status_counts(reference_chunks),
        "report_training_courses": report_training_courses,
        "reference_chunks": reference_chunks,
        **_aihr_review_only_basis_policy(),
    }


def _aihr_review_basis_sources(
    learning_basis: dict[str, Any],
    report_basis: dict[str, Any],
    non_official_diagnostic_basis: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    sources: list[dict[str, Any]] = []
    if learning_basis:
        sources.append(
            {
                "source": "ncs_learning_modules",
                "role": learning_basis.get("basis_role"),
                "status": learning_basis.get("status"),
                "visible_count": learning_basis.get("official_module_count", 0),
                "trusted_count": learning_basis.get("trusted_link_count", 0),
                "gap_reason": learning_basis.get("gap_reason"),
                **_aihr_review_only_basis_policy(),
            }
        )
    if non_official_diagnostic_basis:
        sources.append(
            {
                "source": "non_official_learning_module_diagnostics",
                "role": non_official_diagnostic_basis.get("basis_role"),
                "status": non_official_diagnostic_basis.get("status"),
                "visible_count": sum(
                    int(value or 0)
                    for value in (
                        non_official_diagnostic_basis.get("direct_non_official_counts") or {}
                    ).values()
                ),
                "trusted_count": 0,
                "direct_non_official_counts": (
                    non_official_diagnostic_basis.get("direct_non_official_counts") or {}
                ),
                "official_learning_module": False,
                "counts_as_official_learning_module": False,
                **_aihr_review_only_basis_policy(),
            }
        )
    if report_basis:
        sources.append(
            {
                "source": "ncs_reference_documents",
                "role": report_basis.get("basis_role"),
                "status": report_basis.get("status"),
                "visible_count": int(report_basis.get("report_training_course_count") or 0)
                + int(report_basis.get("reference_link_count") or 0),
                **_aihr_review_only_basis_policy(),
            }
        )
    return sources


def build_aihr_plan_review_seedpack(
    *,
    demo_json_paths: list[Path],
    db_path: Path,
    major_code: str | None = None,
    middle_code: str | None = None,
    small_code: str | None = None,
    sub_code: str | None = None,
    concept_limit: int = 80,
    goal_link_limit: int = 80,
    relation_limit: int = 40,
) -> dict[str, Any]:
    findings: list[dict[str, Any]] = []
    plans: list[tuple[Path, dict[str, Any]]] = []
    for path in demo_json_paths:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "demo_json_missing",
                    "path": str(path),
                    "message": "AI-HR demo JSON artifact is missing.",
                }
            )
            continue
        except json.JSONDecodeError as exc:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "demo_json_invalid",
                    "path": str(path),
                    "message": "AI-HR demo JSON artifact could not be parsed.",
                    "detail": str(exc),
                }
            )
            continue
        if not isinstance(payload, dict):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "demo_json_not_object",
                    "path": str(path),
                    "message": "AI-HR demo JSON artifact must contain an object.",
                }
            )
            continue
        plans.append((path, payload))

    created_at = datetime.now(timezone.utc).isoformat()
    if any(finding.get("severity") == "blocker" for finding in findings):
        return {
            "ok": False,
            "schema": "aihr_plan_review_seedpack_v1",
            "created_at": created_at,
            "source_artifacts": [str(path) for path in demo_json_paths],
            "item_count": 0,
            "item_type_counts": {},
            "approval_claim": False,
            "db_writes": False,
            "status_update_allowed": False,
            "human_decision_required": True,
            "findings": findings,
            "blocker_count": sum(1 for item in findings if item.get("severity") == "blocker"),
            "review_finding_count": 0,
        }

    course_context: dict[int, list[dict[str, Any]]] = {}
    concept_context: dict[str, list[dict[str, Any]]] = {}
    course_ids: set[int] = set()
    concept_names: set[str] = set()
    derived_scopes: list[dict[str, Any]] = []
    for path, payload in plans:
        matrix = payload.get("training_system_matrix")
        if not isinstance(matrix, list):
            continue
        for row in matrix:
            if not isinstance(row, dict):
                continue
            course_id = _as_optional_int(row.get("training_course_id"))
            course_link = row.get("course_link") if isinstance(row.get("course_link"), dict) else {}
            scope_fit = (
                course_link.get("course_scope_fit")
                if isinstance(course_link.get("course_scope_fit"), dict)
                else {}
            )
            target_scope = (
                scope_fit.get("target_scope")
                if isinstance(scope_fit.get("target_scope"), dict)
                else row.get("target_scope")
                if isinstance(row.get("target_scope"), dict)
                else {}
            )
            scope_metadata = _aihr_seedpack_scope_metadata(scope_fit, target_scope)
            task_ksa_basis = (
                row.get("task_ksa_basis") if isinstance(row.get("task_ksa_basis"), dict) else {}
            )
            if target_scope:
                derived_scopes.append(target_scope)
            if course_id is not None:
                course_ids.add(course_id)
                directness = (
                    course_link.get("evidence_directness")
                    if isinstance(course_link.get("evidence_directness"), dict)
                    else {}
                )
                required_basis = (
                    row.get("required_optional_basis")
                    if isinstance(row.get("required_optional_basis"), dict)
                    else {}
                )
                career_path_review_basis = (
                    row.get("career_path_review_basis")
                    if isinstance(row.get("career_path_review_basis"), dict)
                    else {}
                )
                transition_review_basis = (
                    row.get("transition_review_basis")
                    if isinstance(row.get("transition_review_basis"), dict)
                    else {}
                )
                delivery_operation = (
                    row.get("delivery_operation")
                    if isinstance(row.get("delivery_operation"), dict)
                    else {}
                )
                facility_constraint_fit = (
                    row.get("facility_constraint_fit")
                    if isinstance(row.get("facility_constraint_fit"), dict)
                    else delivery_operation.get("facility_constraint_fit")
                    if isinstance(delivery_operation.get("facility_constraint_fit"), dict)
                    else {}
                )
                course_fit = (
                    row.get("course_fit") if isinstance(row.get("course_fit"), dict) else {}
                )
                course_context.setdefault(course_id, []).append(
                    {
                        "source_artifact": str(path),
                        "course_id": course_id,
                        "rank": row.get("rank"),
                        "course_name": row.get("course_name"),
                        "required_optional": required_basis.get("code") or row.get("required_optional"),
                        "evidence_directness": directness.get("code"),
                        "course_scope_relation": scope_fit.get("relation"),
                        **scope_metadata,
                        "task_ksa_basis": task_ksa_basis,
                        "career_path_review_basis": career_path_review_basis,
                        "transition_review_basis": transition_review_basis,
                        "delivery_operation": delivery_operation,
                        "facility_constraint_fit": facility_constraint_fit,
                        "course_fit": course_fit,
                        "review_flags": row.get("review_flags") or [],
                        "human_review": row.get("human_review") if isinstance(row.get("human_review"), dict) else {},
                    }
                )
            for bucket in ("target_scope_ksa", "gap_ksa", "training_goal_ksa"):
                for name in task_ksa_basis.get(bucket) or []:
                    if not isinstance(name, str) or not name.strip():
                        continue
                    concept_name = name.strip()
                    concept_names.add(concept_name)
                    required_basis = (
                        row.get("required_optional_basis")
                        if isinstance(row.get("required_optional_basis"), dict)
                        else {}
                    )
                    delivery_operation = (
                        row.get("delivery_operation")
                        if isinstance(row.get("delivery_operation"), dict)
                        else {}
                    )
                    facility_constraint_fit = (
                        row.get("facility_constraint_fit")
                        if isinstance(row.get("facility_constraint_fit"), dict)
                        else delivery_operation.get("facility_constraint_fit")
                        if isinstance(delivery_operation.get("facility_constraint_fit"), dict)
                        else {}
                    )
                    concept_context.setdefault(concept_name, []).append(
                        {
                            "source_artifact": str(path),
                            "course_id": course_id,
                            "course_name": row.get("course_name"),
                            "rank": row.get("rank"),
                            "bucket": bucket,
                            "required_optional": required_basis.get("code") or row.get("required_optional"),
                            **scope_metadata,
                            "career_path_review_basis": (
                                row.get("career_path_review_basis")
                                if isinstance(row.get("career_path_review_basis"), dict)
                                else {}
                            ),
                            "transition_review_basis": (
                                row.get("transition_review_basis")
                                if isinstance(row.get("transition_review_basis"), dict)
                                else {}
                            ),
                            "delivery_operation": delivery_operation,
                            "facility_constraint_fit": facility_constraint_fit,
                            "course_fit": row.get("course_fit") if isinstance(row.get("course_fit"), dict) else {},
                            "review_flags": row.get("review_flags") or [],
                        }
                    )

    first_scope = next((scope for scope in derived_scopes if isinstance(scope, dict)), {})
    effective_major_code = major_code or first_scope.get("major_code")
    effective_middle_code = middle_code or first_scope.get("middle_code")
    effective_small_code = small_code or first_scope.get("small_code")
    effective_sub_code = sub_code or first_scope.get("sub_code")
    max_concepts = clamp_limit(concept_limit, default=80, maximum=500)
    max_goal_links = clamp_limit(goal_link_limit, default=80, maximum=500)
    max_relations = clamp_limit(relation_limit, default=40, maximum=500)
    sorted_course_ids = sorted(course_ids)
    sorted_concept_names = sorted(concept_names)
    items: list[dict[str, Any]] = []
    course_meta_by_id: dict[int, dict[str, Any]] = {}
    course_review_basis_by_id: dict[int, dict[str, Any]] = {}

    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        for course_id in sorted_course_ids:
            course = conn.execute(
                """
                SELECT
                    training_course_id,
                    compe_unit_name,
                    ncs_cl_cd,
                    train_time,
                    meth_name,
                    fac_name,
                    train_goal,
                    ncs_lclas_cd,
                    ncs_mclas_cd,
                    ncs_sclas_cd,
                    ncs_subd_cd
                FROM ncs_training_courses
                WHERE training_course_id = ?
                """,
                (course_id,),
            ).fetchone()
            if not course:
                continue
            course_metadata = {
                "ncs_cl_cd": course["ncs_cl_cd"],
                "major_code": course["ncs_lclas_cd"],
                "middle_code": course["ncs_mclas_cd"],
                "small_code": course["ncs_sclas_cd"],
                "sub_code": course["ncs_subd_cd"],
            }
            course_meta_by_id[course_id] = {
                key: value for key, value in course_metadata.items() if value not in (None, "")
            }
            learning_module_review_basis = _aihr_learning_module_review_basis(
                conn,
                ncs_cl_cd=course["ncs_cl_cd"],
            )
            non_official_diagnostic_basis = _aihr_non_official_diagnostic_review_basis(
                conn,
                ncs_cl_cd=course["ncs_cl_cd"],
            )
            ncs_report_review_basis = _aihr_ncs_report_review_basis(
                conn,
                ncs_cl_cd=course["ncs_cl_cd"],
            )
            review_basis_sources = _aihr_review_basis_sources(
                learning_module_review_basis,
                ncs_report_review_basis,
                non_official_diagnostic_basis,
            )
            course_review_basis_by_id[course_id] = {
                "learning_module_review_basis": learning_module_review_basis,
                "non_official_diagnostic_basis": non_official_diagnostic_basis,
                "ncs_report_review_basis": ncs_report_review_basis,
                "review_basis_sources": review_basis_sources,
            }
            contexts = _aihr_enrich_plan_contexts_with_course_meta(
                course_context.get(course_id, []),
                course_meta_by_id,
            )
            contexts = [
                {
                    **context,
                    "learning_module_review_basis": learning_module_review_basis,
                    "non_official_diagnostic_basis": non_official_diagnostic_basis,
                    "ncs_report_review_basis": ncs_report_review_basis,
                    "review_basis_sources": review_basis_sources,
                }
                for context in contexts
            ]
            course_context[course_id] = contexts
            flags = sorted(
                {
                    str(flag)
                    for context in contexts
                    for flag in context.get("review_flags") or []
                    if str(flag).strip()
                }
            )
            task_ksa_basis_context = next(
                (
                    context.get("task_ksa_basis")
                    for context in contexts
                    if isinstance(context.get("task_ksa_basis"), dict)
                    and context.get("task_ksa_basis")
                ),
                {},
            )
            _add_aihr_seedpack_item(
                items,
                {
                    "item_type": "training_system_row_review",
                    "target_table": "ncs_training_courses",
                    "target_id": course_id,
                    "course_name": course["compe_unit_name"],
                    "ncs_cl_cd": course["ncs_cl_cd"],
                    "major_code": course["ncs_lclas_cd"],
                    "middle_code": course["ncs_mclas_cd"],
                    "small_code": course["ncs_sclas_cd"],
                    "sub_code": course["ncs_subd_cd"],
                    "review_question": (
                        "Confirm whether this course should remain in the education-system "
                        "matrix and whether its required/optional grouping is correct."
                    ),
                    "review_focus": [
                        "course_inclusion",
                        "required_optional",
                        "delivery_fit",
                        "scope_specificity",
                    ],
                    "current_evidence": {
                        "ncs_cl_cd": course["ncs_cl_cd"],
                        "major_code": course["ncs_lclas_cd"],
                        "middle_code": course["ncs_mclas_cd"],
                        "small_code": course["ncs_sclas_cd"],
                        "sub_code": course["ncs_subd_cd"],
                        "train_goal": course["train_goal"],
                        "hours": course["train_time"],
                        "methods": course["meth_name"],
                        "facilities": course["fac_name"],
                        "task_ksa_basis": task_ksa_basis_context,
                        "learning_module_review_basis": learning_module_review_basis,
                        "non_official_diagnostic_basis": non_official_diagnostic_basis,
                        "ncs_report_review_basis": ncs_report_review_basis,
                        "review_basis_sources": review_basis_sources,
                        "contexts": contexts,
                        "review_flags": flags,
                    },
                    "risk_note": (
                        "This seedpack prepares human review only; it does not approve course "
                        "links or write review status."
                    ),
                },
                created_at,
            )

        concept_ids: set[int] = set()
        if sorted_concept_names:
            placeholders = ",".join("?" for _ in sorted_concept_names)
            concept_rows = conn.execute(
                f"""
                SELECT
                    concept_id,
                    concept_name,
                    concept_type,
                    definition_status,
                    definition_source,
                    review_status
                FROM ontology_concepts
                WHERE concept_name IN ({placeholders})
                ORDER BY concept_name, concept_type, concept_id
                LIMIT ?
                """,
                (*sorted_concept_names, max_concepts),
            ).fetchall()
            for row in concept_rows:
                concept_ids.add(int(row["concept_id"]))
                plan_contexts = _aihr_enrich_plan_contexts_with_course_meta(
                    concept_context.get(row["concept_name"]) or [],
                    course_meta_by_id,
                )
                plan_contexts = _aihr_enrich_plan_contexts_with_review_basis(
                    plan_contexts,
                    course_review_basis_by_id,
                )
                scope_fields = _aihr_seedpack_first_context_values(plan_contexts)
                _add_aihr_seedpack_item(
                    items,
                    {
                        "item_type": "ontology_concept_review",
                        "target_table": "ontology_concepts",
                        "target_id": row["concept_id"],
                        "concept_name": row["concept_name"],
                        "concept_type": row["concept_type"],
                        **scope_fields,
                        "current_review_status": row["review_status"],
                        "definition_status": row["definition_status"],
                        "definition_source": row["definition_source"],
                        "review_question": (
                            "Confirm whether this KSA concept is valid, specific enough, "
                            "and correctly represented for the planner evidence."
                        ),
                        "review_focus": [
                            "concept_definition",
                            "concept_specificity",
                            "alias_or_merge_need",
                        ],
                        "current_evidence": {
                            **scope_fields,
                            "plan_contexts": plan_contexts,
                        },
                        "risk_note": (
                            "Do not mark human_reviewed unless a reviewer confirms definition "
                            "and concept scope."
                        ),
                    },
                    created_at,
                )

        if sorted_course_ids and sorted_concept_names:
            course_placeholders = ",".join("?" for _ in sorted_course_ids)
            name_placeholders = ",".join("?" for _ in sorted_concept_names)
            goal_rows = conn.execute(
                f"""
                SELECT
                    gl.link_id,
                    gl.training_course_id,
                    gl.concept_id,
                    gl.link_method,
                    gl.confidence_score,
                    gl.review_status,
                    tc.compe_unit_name,
                    tc.ncs_cl_cd,
                    tc.train_goal,
                    oc.concept_name,
                    oc.concept_type
                FROM training_goal_concept_links gl
                JOIN ncs_training_courses tc ON tc.training_course_id = gl.training_course_id
                JOIN ontology_concepts oc ON oc.concept_id = gl.concept_id
                WHERE gl.training_course_id IN ({course_placeholders})
                  AND oc.concept_name IN ({name_placeholders})
                  AND gl.review_status != 'human_reviewed'
                  AND gl.review_status != 'rejected'
                ORDER BY
                    gl.training_course_id,
                    CASE gl.link_method
                        WHEN 'training_goal_concept_text' THEN 0
                        WHEN 'training_goal_concept_token' THEN 1
                        ELSE 2
                    END,
                    gl.confidence_score DESC,
                    gl.link_id
                LIMIT ?
                """,
                (*sorted_course_ids, *sorted_concept_names, max_goal_links),
            ).fetchall()
            for row in goal_rows:
                course_metadata = course_meta_by_id.get(int(row["training_course_id"]), {})
                goal_scope_fields = {
                    **course_metadata,
                    "ncs_cl_cd": row["ncs_cl_cd"],
                }
                concept_plan_contexts = _aihr_enrich_plan_contexts_with_course_meta(
                    concept_context.get(row["concept_name"]) or [],
                    course_meta_by_id,
                )
                concept_plan_contexts = _aihr_enrich_plan_contexts_with_review_basis(
                    concept_plan_contexts,
                    course_review_basis_by_id,
                )
                _add_aihr_seedpack_item(
                    items,
                    {
                        "item_type": "training_goal_concept_link_review",
                        "target_table": "training_goal_concept_links",
                        "target_id": row["link_id"],
                        "training_course_id": row["training_course_id"],
                        "course_name": row["compe_unit_name"],
                        "ncs_cl_cd": row["ncs_cl_cd"],
                        "major_code": goal_scope_fields.get("major_code"),
                        "middle_code": goal_scope_fields.get("middle_code"),
                        "small_code": goal_scope_fields.get("small_code"),
                        "sub_code": goal_scope_fields.get("sub_code"),
                        "concept_id": row["concept_id"],
                        "concept_name": row["concept_name"],
                        "concept_type": row["concept_type"],
                        "current_review_status": row["review_status"],
                        "link_method": row["link_method"],
                        "confidence_score": row["confidence_score"],
                        "review_question": (
                            "Confirm whether the training goal directly covers this KSA "
                            "concept or whether it is only token/indirect overlap."
                        ),
                        "review_focus": [
                            "training_goal_directness",
                            "course_link_validity",
                            "generic_match_risk",
                        ],
                        "current_evidence": {
                            **goal_scope_fields,
                            "train_goal": row["train_goal"],
                            "plan_contexts": course_context.get(int(row["training_course_id"])) or [],
                            "concept_contexts": concept_plan_contexts,
                        },
                        "risk_note": (
                            "Token or inherited links should not be promoted without human "
                            "confirmation."
                        ),
                    },
                    created_at,
                )

        if concept_ids:
            id_placeholders = ",".join("?" for _ in concept_ids)
            scope_clause, scope_params = _seedpack_scope_clause(
                alias="c",
                major_code=effective_major_code,
                middle_code=effective_middle_code,
                small_code=effective_small_code,
                sub_code=effective_sub_code,
            )
            relation_rows = conn.execute(
                f"""
                SELECT
                    r.relation_id,
                    r.relation_type,
                    r.confidence_score,
                    r.review_status,
                    src.concept_name AS source_concept_name,
                    src.concept_type AS source_concept_type,
                    tgt.concept_name AS target_concept_name,
                    tgt.concept_type AS target_concept_type,
                    pc.criteria_text_raw,
                    ce.element_name_raw,
                    cu.unit_code,
                    cu.unit_name_raw,
                    c.major_code,
                    c.middle_code,
                    c.small_code,
                    c.sub_code
                FROM task_ksa_concept_relations r
                JOIN ontology_concepts src ON src.concept_id = r.source_concept_id
                JOIN ontology_concepts tgt ON tgt.concept_id = r.target_concept_id
                JOIN competency_elements ce ON ce.element_id = r.element_id
                JOIN competency_units cu ON cu.unit_code = ce.unit_code
                JOIN classifications c ON c.classification_id = cu.classification_id
                JOIN performance_criteria pc ON pc.criteria_id = r.criteria_id
                WHERE (
                    r.source_concept_id IN ({id_placeholders})
                    OR r.target_concept_id IN ({id_placeholders})
                )
                  {scope_clause}
                  AND r.review_status != 'human_reviewed'
                  AND r.review_status != 'rejected'
                ORDER BY
                    CASE r.relation_type
                        WHEN 'co_required_in_element' THEN 0
                        ELSE 1
                    END,
                    r.confidence_score,
                    r.relation_id
                LIMIT ?
                """,
                (*concept_ids, *concept_ids, *scope_params, max_relations),
            ).fetchall()
            for row in relation_rows:
                source_contexts = _aihr_enrich_plan_contexts_with_course_meta(
                    concept_context.get(row["source_concept_name"]) or [],
                    course_meta_by_id,
                )
                source_contexts = _aihr_enrich_plan_contexts_with_review_basis(
                    source_contexts,
                    course_review_basis_by_id,
                )
                target_contexts = _aihr_enrich_plan_contexts_with_course_meta(
                    concept_context.get(row["target_concept_name"]) or [],
                    course_meta_by_id,
                )
                target_contexts = _aihr_enrich_plan_contexts_with_review_basis(
                    target_contexts,
                    course_review_basis_by_id,
                )
                relation_scope_fields = {
                    "ncs_cl_cd": row["unit_code"],
                    "major_code": row["major_code"],
                    "middle_code": row["middle_code"],
                    "small_code": row["small_code"],
                    "sub_code": row["sub_code"],
                }
                relation_scope_fields = {
                    key: value for key, value in relation_scope_fields.items() if value not in (None, "")
                }
                _add_aihr_seedpack_item(
                    items,
                    {
                        "item_type": "task_ksa_concept_relation_review",
                        "target_table": "task_ksa_concept_relations",
                        "target_id": row["relation_id"],
                        "relation_type": row["relation_type"],
                        "confidence_score": row["confidence_score"],
                        "current_review_status": row["review_status"],
                        "source_concept": {
                            "name": row["source_concept_name"],
                            "type": row["source_concept_type"],
                        },
                        "target_concept": {
                            "name": row["target_concept_name"],
                            "type": row["target_concept_type"],
                        },
                        "unit_code": row["unit_code"],
                        "unit_name": row["unit_name_raw"],
                        "element_name": row["element_name_raw"],
                        "performance_criterion": row["criteria_text_raw"],
                        **relation_scope_fields,
                        "review_question": (
                            "Confirm whether this KSA relation is task-essential rather than "
                            "co-occurrence noise."
                        ),
                        "review_focus": [
                            "task_ksa_necessity",
                            "relation_type_validity",
                            "co_occurrence_noise",
                        ],
                        "current_evidence": {
                            **relation_scope_fields,
                            "source_contexts": source_contexts,
                            "target_contexts": target_contexts,
                        },
                        "risk_note": (
                            "Task-KSA relations are candidates until a human confirms the "
                            "task-essential relation."
                        ),
                    },
                    created_at,
                )
    finally:
        conn.close()

    item_type_counts: dict[str, int] = {}
    for item in items:
        item_type = str(item.get("item_type") or "unknown")
        item_type_counts[item_type] = item_type_counts.get(item_type, 0) + 1
    if not items:
        findings.append(
            {
                "severity": "review",
                "code": "empty_seedpack",
                "message": "No review seedpack items were generated from the supplied demo artifacts.",
            }
        )
    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    return {
        "ok": blocker_count == 0,
        "schema": "aihr_plan_review_seedpack_v1",
        "created_at": created_at,
        "source_artifacts": [str(path) for path, _payload in plans],
        "db_path": str(db_path),
        "scope": {
            "major_code": effective_major_code,
            "middle_code": effective_middle_code,
            "small_code": effective_small_code,
            "sub_code": effective_sub_code,
        },
        "item_count": len(items),
        "item_type_counts": item_type_counts,
        "course_ids": sorted_course_ids,
        "concept_name_count": len(sorted_concept_names),
        "concept_limit": max_concepts,
        "goal_link_limit": max_goal_links,
        "relation_limit": max_relations,
        "approval_claim": False,
        "db_writes": False,
        "status_update_allowed": False,
        "human_decision_required": True,
        "review_policy": {
            "human_decision_required_for_approval": True,
            "allowed_decisions": _aihr_plan_review_allowed_decisions(),
            "no_status_updates_performed": True,
            "framework_reference_only": True,
        },
        "items": items,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
    }


def write_aihr_plan_review_seedpack_jsonl(report: dict[str, Any], out_path: Path) -> None:
    out_path.parent.mkdir(parents=True, exist_ok=True)
    items = [item for item in report.get("items") or [] if isinstance(item, dict)]
    text = "\n".join(json.dumps(item, ensure_ascii=False) for item in items)
    out_path.write_text(text + ("\n" if text else ""), encoding="utf-8")


def write_aihr_plan_review_seedpack_markdown(report: dict[str, Any], out_path: Path) -> None:
    lines = [
        "# AI-HR Plan Review Seedpack",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- created_at: {report.get('created_at')}",
        f"- item_count: {report.get('item_count')}",
        f"- item_type_counts: {report.get('item_type_counts')}",
        f"- course_ids: {report.get('course_ids')}",
        f"- concept_name_count: {report.get('concept_name_count')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- db_writes: {report.get('db_writes')}",
        "",
        "| # | type | target | focus | question |",
        "|---:|---|---|---|---|",
    ]
    for index, item in enumerate(report.get("items") or [], start=1):
        if not isinstance(item, dict):
            continue
        target = f"{item.get('target_table')}:{item.get('target_id')}"
        if item.get("course_name"):
            target += f" / {item.get('course_name')}"
        elif item.get("concept_name"):
            target += f" / {item.get('concept_name')}"
        elif item.get("unit_name"):
            target += f" / {item.get('unit_name')}"
        focus = ", ".join(str(value) for value in item.get("review_focus") or [])
        lines.append(
            "| "
            f"{index} | "
            f"{item.get('item_type')} | "
            f"{target} | "
            f"{focus} | "
            f"{item.get('review_question') or ''} |"
        )
    lines.extend(["", "## Findings", ""])
    for finding in report.get("findings") or []:
        if not isinstance(finding, dict):
            continue
        lines.append(
            "- "
            f"{finding.get('severity')}:{finding.get('code')} "
            f"{finding.get('message')}"
        )
    policy = report.get("review_policy") if isinstance(report.get("review_policy"), dict) else {}
    lines.extend(
        [
            "",
            "## Review Policy",
            "",
            "- Human decision required before any approval/status update.",
            "- This seedpack performs no DB writes.",
            "- The 2026 guide is used as framework reference only.",
            f"- allowed_decisions: {policy.get('allowed_decisions')}",
        ]
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


AIHR_PLAN_REVIEW_ORDER_POLICY = [
    "training_system_required_first",
    "ontology_concepts",
    "training_goal_links",
    "task_ksa_relations",
]

AIHR_PLAN_REVIEW_ITEM_TYPE_PRIORITY = {
    "training_system_row_review": 0,
    "ontology_concept_review": 1,
    "training_goal_concept_link_review": 2,
    "task_ksa_concept_relation_review": 3,
}


def _aihr_seedpack_review_contexts(item: dict[str, Any]) -> list[dict[str, Any]]:
    evidence = item.get("current_evidence") if isinstance(item.get("current_evidence"), dict) else {}
    contexts: list[dict[str, Any]] = []
    for key in ("contexts", "plan_contexts", "source_contexts", "target_contexts"):
        for context in evidence.get(key) or []:
            if isinstance(context, dict):
                normalized = dict(context)
                normalized.setdefault("context_kind", key)
                contexts.append(normalized)
    return contexts


def _aihr_seedpack_min_rank(contexts: list[dict[str, Any]]) -> int:
    ranks = [_as_optional_int(context.get("rank")) for context in contexts]
    concrete_ranks = [rank for rank in ranks if rank is not None]
    return min(concrete_ranks) if concrete_ranks else 999


def _aihr_seedpack_required_priority(item: dict[str, Any], contexts: list[dict[str, Any]]) -> int:
    if item.get("item_type") == "task_ksa_concept_relation_review":
        return 3
    groups = {str(context.get("required_optional") or "").strip() for context in contexts}
    if "required" in groups:
        return 0
    if "optional" in groups or "supporting" in groups or "supporting_or_adjacent" in groups:
        return 1
    return 2


def _aihr_seedpack_target_label(item: dict[str, Any]) -> str:
    for key in ("course_name", "concept_name", "unit_name"):
        value = item.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    target_concept = item.get("target_concept") if isinstance(item.get("target_concept"), dict) else {}
    source_concept = item.get("source_concept") if isinstance(item.get("source_concept"), dict) else {}
    for value in (target_concept.get("name"), source_concept.get("name")):
        if isinstance(value, str) and value.strip():
            return value.strip()
    return ""


