def _aihr_artifact_sidecar_path(path_value: Any, fallback: Path) -> Path:
    if path_value in (None, ""):
        return fallback
    path = Path(str(path_value))
    if path.is_absolute():
        return path
    if path.parent == Path("."):
        return fallback.parent / path
    artifact_relative_path = fallback.parent / path
    if artifact_relative_path.exists() and not path.exists():
        return artifact_relative_path
    return path


def _aihr_packet_index_artifact_path(payload: dict[str, Any], key: str, fallback: Path) -> Path:
    value = payload.get(key)
    return _aihr_artifact_sidecar_path(value, fallback)


def _aihr_packet_artifact_sensitive_markers(text: str) -> list[str]:
    lowered_text = text.lower()
    markers: set[str] = set()
    for marker in AIHR_PACKET_ARTIFACT_SENSITIVE_MARKERS:
        marker_lower = marker.lower()
        if marker in {"source_payload", "raw_payload", "raw_response"}:
            if re.search(rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])", text):
                markers.add(marker)
            continue
        if marker_lower in lowered_text:
            markers.add(marker)
    return sorted(markers)


def _aihr_scan_packet_artifact_texts_for_sensitive_markers(
    artifact_paths: dict[str, str | Path],
) -> tuple[bool, list[dict[str, Any]]]:
    source_payload_exposed = False
    findings: list[dict[str, Any]] = []
    seen_paths: set[str] = set()
    for label, path_value in artifact_paths.items():
        path = Path(path_value)
        path_key = str(path.resolve(strict=False))
        if path_key in seen_paths:
            continue
        seen_paths.add(path_key)
        try:
            text = path.read_text(encoding="utf-8")
        except OSError:
            continue
        sensitive_markers = _aihr_packet_artifact_sensitive_markers(text)
        if sensitive_markers:
            source_payload_exposed = True
            findings.append(
                {
                    "severity": "blocker",
                    "code": f"{label}_source_payload_exposed",
                    "path": str(path),
                    "sensitive_markers": sensitive_markers,
                    "message": f"{label} artifact exposes a sensitive source payload marker.",
                }
            )
    return source_payload_exposed, findings


def _aihr_text_exposes_source_payload(text: str) -> bool:
    return bool(_aihr_packet_artifact_sensitive_markers(text))


AIHR_HUMAN_REVIEW_PACKET_CONTEXT_MODULE_ROLE_LABELS = {
    "current_query": "current_query_context_module",
    "target_query": "target_query_context_module",
    "expected_course": "expected_course_context_module",
    "recommended_course": "recommended_course_context_module",
}


def _aihr_bare_context_module_role_counts(text: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for role in AIHR_HUMAN_REVIEW_PACKET_CONTEXT_MODULE_ROLE_LABELS:
        pattern = re.compile(rf"(?<![A-Za-z0-9_]){re.escape(role)}(?![A-Za-z0-9_])")
        counts[role] = len(pattern.findall(text))
    return counts


def _aihr_replace_bare_context_module_roles(text: str) -> tuple[str, dict[str, int]]:
    repaired_text = text
    replacement_counts: dict[str, int] = {}
    for old_role, new_role in AIHR_HUMAN_REVIEW_PACKET_CONTEXT_MODULE_ROLE_LABELS.items():
        pattern = re.compile(rf"(?<![A-Za-z0-9_]){re.escape(old_role)}(?![A-Za-z0-9_])")
        repaired_text, replacement_count = pattern.subn(new_role, repaired_text)
        replacement_counts[old_role] = replacement_count
    return repaired_text, replacement_counts


def _aihr_ensure_context_module_policy_note(text: str) -> tuple[str, bool]:
    marker = 'data-contract="context_module_label_policy"'
    if marker in text:
        return text, False
    note = (
        '<div class="policy" data-contract="context_module_label_policy">'
        "Role labels ending in <b>_context_module</b> point to official NCS "
        "learning-module PDFs used only as Human Review context. They are not "
        "training-course recommendations, scoring evidence, or approval signals."
        "</div>"
    )
    first_policy_end = text.find("</div>", text.find('<div class="policy"'))
    if first_policy_end >= 0:
        insert_at = first_policy_end + len("</div>")
        return text[:insert_at] + "\n" + note + text[insert_at:], True
    body_start_end = text.find("<body>")
    if body_start_end >= 0:
        insert_at = body_start_end + len("<body>")
        return text[:insert_at] + "\n" + note + text[insert_at:], True
    return note + "\n" + text, True


def repair_aihr_human_review_packet_labels(
    *,
    html_path: Path,
    write: bool = True,
) -> dict[str, Any]:
    created_at = datetime.now(timezone.utc).isoformat()
    findings: list[dict[str, Any]] = []
    if not html_path.exists():
        findings.append(
            {
                "severity": "blocker",
                "code": "html_missing",
                "path": str(html_path),
                "message": "Human Review packet HTML does not exist.",
            }
        )
        return {
            "schema": "aihr_human_review_packet_label_contract_v1",
            "created_at": created_at,
            "html_path": str(html_path),
            "write": write,
            "ok": False,
            "findings": findings,
        }
    try:
        original_text = html_path.read_text(encoding="utf-8")
    except OSError as exc:
        findings.append(
            {
                "severity": "blocker",
                "code": "html_unreadable",
                "path": str(html_path),
                "message": "Human Review packet HTML could not be read.",
                "detail": str(exc),
            }
        )
        return {
            "schema": "aihr_human_review_packet_label_contract_v1",
            "created_at": created_at,
            "html_path": str(html_path),
            "write": write,
            "ok": False,
            "findings": findings,
        }

    bare_counts_before = _aihr_bare_context_module_role_counts(original_text)
    repaired_text, replacement_counts = _aihr_replace_bare_context_module_roles(original_text)
    repaired_text, policy_note_added = _aihr_ensure_context_module_policy_note(repaired_text)
    bare_counts_after = _aihr_bare_context_module_role_counts(repaired_text)
    context_module_counts = {
        new_role: len(
            re.findall(rf"(?<![A-Za-z0-9_]){re.escape(new_role)}(?![A-Za-z0-9_])", repaired_text)
        )
        for new_role in AIHR_HUMAN_REVIEW_PACKET_CONTEXT_MODULE_ROLE_LABELS.values()
    }
    sensitive_markers = _aihr_packet_artifact_sensitive_markers(repaired_text)
    if sensitive_markers:
        findings.append(
            {
                "severity": "blocker",
                "code": "source_payload_exposed",
                "path": str(html_path),
                "sensitive_markers": sensitive_markers,
                "message": "Human Review packet HTML exposes a sensitive source payload marker.",
            }
        )
    residual_problem_roles = [
        role
        for role in ("expected_course", "recommended_course")
        if bare_counts_after.get(role, 0) > 0
    ]
    if residual_problem_roles:
        findings.append(
            {
                "severity": "blocker",
                "code": "bare_course_role_labels_remaining",
                "path": str(html_path),
                "roles": residual_problem_roles,
                "message": "Packet still contains bare course role labels for learning-module context.",
            }
        )
    changed = repaired_text != original_text
    if write and changed and not residual_problem_roles:
        html_path.write_text(repaired_text, encoding="utf-8")
    elif write and changed and residual_problem_roles:
        findings.append(
            {
                "severity": "blocker",
                "code": "html_not_written_due_to_residual_labels",
                "path": str(html_path),
                "message": "HTML was not rewritten because residual bare course role labels remain.",
            }
        )
    return {
        "schema": "aihr_human_review_packet_label_contract_v1",
        "created_at": created_at,
        "html_path": str(html_path),
        "write": write,
        "changed": changed,
        "policy_note_added": policy_note_added,
        "bare_role_counts_before": bare_counts_before,
        "bare_role_counts_after": bare_counts_after,
        "context_module_counts": context_module_counts,
        "replacement_counts": replacement_counts,
        "approval_claim": False,
        "db_writes": False,
        "status_update_allowed": False,
        "review_policy": {
            "learning_modules_are_auxiliary_review_reference": True,
            "context_module_labels_are_not_training_recommendations": True,
            "non_scoring": True,
            "approval_claim": False,
            "db_writes": False,
            "status_update_allowed": False,
        },
        "source_payload_exposed": bool(sensitive_markers),
        "sensitive_markers": sensitive_markers,
        "ok": not findings,
        "findings": findings,
    }


def write_aihr_human_review_packet_label_contract_markdown(
    report: dict[str, Any],
    out_path: Path,
) -> None:
    lines = [
        "# AI-HR Human Review Packet Label Contract",
        "",
        f"- ok: {report.get('ok')}",
        f"- html_path: {report.get('html_path')}",
        f"- changed: {report.get('changed')}",
        f"- policy_note_added: {report.get('policy_note_added')}",
        f"- source_payload_exposed: {report.get('source_payload_exposed')}",
        "",
        "## Bare Role Counts After",
    ]
    for role, count in (report.get("bare_role_counts_after") or {}).items():
        lines.append(f"- {role}: {count}")
    lines.extend(["", "## Context Module Counts"])
    for role, count in (report.get("context_module_counts") or {}).items():
        lines.append(f"- {role}: {count}")
    findings = report.get("findings") or []
    if findings:
        lines.extend(["", "## Findings"])
        for finding in findings:
            lines.append(
                f"- {finding.get('severity')}: {finding.get('code')} - {finding.get('message')}"
            )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def _aihr_artifact_href(path_value: Any, out_path: Path) -> str:
    if path_value in (None, ""):
        return ""
    path = Path(str(path_value))
    if path.is_absolute():
        target = path
    else:
        root_candidate = ROOT / path
        base_candidate = out_path.parent / path
        if root_candidate.exists() or str(path).replace("\\", "/").startswith("reports/"):
            target = root_candidate
        else:
            target = base_candidate
    try:
        href = os.path.relpath(target.resolve(strict=False), out_path.parent.resolve(strict=False))
    except OSError:
        href = str(path)
    return href.replace("\\", "/")


def _aihr_markdown_artifact_link(path_value: Any, out_path: Path) -> str:
    if path_value in (None, ""):
        return ""
    label = str(path_value)
    href = _aihr_artifact_href(path_value, out_path)
    return f"[{label}]({href})"


def _aihr_markdown_action_link(label: str, path_value: Any, out_path: Path) -> str:
    if path_value in (None, ""):
        return ""
    href = _aihr_artifact_href(path_value, out_path)
    return f"[{label}]({href})"


def _aihr_packet_index_link(
    *,
    label: str,
    path: Path,
    findings: list[dict[str, Any]],
) -> dict[str, Any]:
    exists = path.exists()
    size_bytes = path.stat().st_size if exists else 0
    source_payload_exposed = False
    sensitive_markers: list[str] = []
    if not exists or size_bytes <= 0:
        findings.append(
            {
                "severity": "blocker",
                "code": "packet_index_link_missing_or_empty",
                "label": label,
                "path": str(path),
                "message": "Packet index link target must exist and be non-empty.",
            }
        )
    else:
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError as exc:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "packet_index_link_unreadable",
                    "label": label,
                    "path": str(path),
                    "message": "Packet index link target could not be read.",
                    "detail": str(exc),
                }
            )
            text = ""
        sensitive_markers = _aihr_packet_artifact_sensitive_markers(text)
        source_payload_exposed = bool(sensitive_markers)
        if source_payload_exposed:
            findings.append(
                {
                    "severity": "blocker",
                    "code": "source_payload_exposed",
                    "label": label,
                    "path": str(path),
                    "sensitive_markers": sensitive_markers,
                    "message": "Packet index target exposes a sensitive source payload marker.",
                }
            )
    return {
        "label": label,
        "path": str(path),
        "exists": exists,
        "size_bytes": size_bytes,
        "non_empty": size_bytes > 0,
        "source_payload_exposed": source_payload_exposed,
        "sensitive_markers": sensitive_markers if source_payload_exposed else [],
    }


def build_aihr_plan_review_packet_index(
    *,
    next_request_path: Path,
    decision_sheet_path: Path,
    group_packet_paths: list[Path],
    basis_coverage_path: Path | None = None,
    unit_evidence_packet_path: Path | None = None,
    official_learning_module_gap_audit_path: Path | None = None,
    evidence_gap_triage_path: Path | None = None,
    require_full_group_coverage: bool = False,
) -> dict[str, Any]:
    created_at = datetime.now(timezone.utc).isoformat()
    findings: list[dict[str, Any]] = []
    date_suffix = _aihr_artifact_date_suffix(next_request_path)
    if basis_coverage_path is None:
        derived_basis_coverage = next_request_path.parent / f"aihr_plan_review_basis_coverage{date_suffix}.json"
        if derived_basis_coverage.exists():
            basis_coverage_path = derived_basis_coverage
    if unit_evidence_packet_path is None:
        derived_unit_evidence = next_request_path.parent / f"aihr_plan_review_unit_evidence_packet{date_suffix}.json"
        if derived_unit_evidence.exists():
            unit_evidence_packet_path = derived_unit_evidence
    if official_learning_module_gap_audit_path is None:
        derived_official_lm_gap = next_request_path.parent / f"aihr_official_learning_module_gap_audit{date_suffix}.json"
        if derived_official_lm_gap.exists():
            official_learning_module_gap_audit_path = derived_official_lm_gap
    if evidence_gap_triage_path is None:
        derived_evidence_gap_triage = (
            next_request_path.parent / f"aihr_plan_review_evidence_gap_triage{date_suffix}.json"
        )
        if derived_evidence_gap_triage.exists():
            evidence_gap_triage_path = derived_evidence_gap_triage
    next_request = _load_json_artifact(next_request_path, "next_request", findings)
    decision_sheet = _load_json_artifact(decision_sheet_path, "decision_sheet", findings)
    basis_coverage = (
        _load_json_artifact(basis_coverage_path, "basis_coverage", findings)
        if basis_coverage_path is not None
        else {}
    )
    unit_evidence_packet = (
        _load_json_artifact(unit_evidence_packet_path, "unit_evidence_packet", findings)
        if unit_evidence_packet_path is not None
        else {}
    )
    official_learning_module_gap_audit = (
        _load_json_artifact(
            official_learning_module_gap_audit_path,
            "official_learning_module_gap_audit",
            findings,
        )
        if official_learning_module_gap_audit_path is not None
        else {}
    )
    evidence_gap_triage = (
        _load_json_artifact(evidence_gap_triage_path, "evidence_gap_triage", findings)
        if evidence_gap_triage_path is not None
        else {}
    )
    group_packets = [
        _load_json_artifact(path, f"group_packet_{index}", findings)
        for index, path in enumerate(group_packet_paths, start=1)
    ]
    if next_request:
        _artifact_claims_no_approval_or_db_writes(next_request, "next_request", findings)
    if decision_sheet:
        _artifact_claims_no_approval_or_db_writes(decision_sheet, "decision_sheet", findings)
    if basis_coverage:
        _artifact_claims_no_approval_or_db_writes(basis_coverage, "basis_coverage", findings)
    if unit_evidence_packet:
        _artifact_claims_no_approval_or_db_writes(
            unit_evidence_packet,
            "unit_evidence_packet",
            findings,
        )
    if official_learning_module_gap_audit:
        _artifact_claims_no_approval_or_db_writes(
            official_learning_module_gap_audit,
            "official_learning_module_gap_audit",
            findings,
        )
    if evidence_gap_triage:
        _artifact_claims_no_approval_or_db_writes(
            evidence_gap_triage,
            "evidence_gap_triage",
            findings,
        )
    for index, packet in enumerate(group_packets, start=1):
        if packet:
            _artifact_claims_no_approval_or_db_writes(packet, f"group_packet_{index}", findings)

    links: list[dict[str, Any]] = []
    links.append(
        _aihr_packet_index_link(
            label="next_request_json",
            path=next_request_path,
            findings=findings,
        )
    )
    links.append(
        _aihr_packet_index_link(
            label="next_request_markdown",
            path=next_request_path.with_suffix(".md"),
            findings=findings,
        )
    )
    links.append(
        _aihr_packet_index_link(
            label="next_request_html",
            path=next_request_path.with_suffix(".html"),
            findings=findings,
        )
    )
    decision_sheet_csv = _aihr_packet_index_artifact_path(
        decision_sheet,
        "csv_path",
        decision_sheet_path.with_suffix(".csv"),
    )
    decision_sheet_html = _aihr_packet_index_artifact_path(
        decision_sheet,
        "html_path",
        decision_sheet_path.with_suffix(".html"),
    )
    links.append(
        _aihr_packet_index_link(
            label="decision_sheet_json",
            path=decision_sheet_path,
            findings=findings,
        )
    )
    links.append(
        _aihr_packet_index_link(
            label="decision_sheet_csv",
            path=decision_sheet_csv,
            findings=findings,
        )
    )
    links.append(
        _aihr_packet_index_link(
            label="decision_sheet_html",
            path=decision_sheet_html,
            findings=findings,
        )
    )
    decision_sheet_json_rows = _as_optional_int(decision_sheet.get("row_count"))
    decision_sheet_csv_rows: int | None = None
    try:
        decision_sheet_csv_rows = len(_read_aihr_plan_review_decision_sheet_rows(decision_sheet_csv))
    except FileNotFoundError:
        findings.append(
            {
                "severity": "blocker",
                "code": "decision_sheet_csv_missing",
                "path": str(decision_sheet_csv),
                "message": "Decision-sheet CSV is required for packet-index row coverage checks.",
            }
        )
    except (OSError, csv.Error, UnicodeDecodeError) as exc:
        findings.append(
            {
                "severity": "blocker",
                "code": "decision_sheet_csv_unreadable",
                "path": str(decision_sheet_csv),
                "message": "Decision-sheet CSV could not be read for packet-index row coverage checks.",
                "detail": str(exc),
            }
        )
    if (
        decision_sheet_json_rows is not None
        and decision_sheet_csv_rows is not None
        and decision_sheet_json_rows != decision_sheet_csv_rows
    ):
        findings.append(
            {
                "severity": "blocker",
                "code": "decision_sheet_csv_row_count_mismatch",
                "decision_sheet_json_rows": decision_sheet_json_rows,
                "decision_sheet_csv_rows": decision_sheet_csv_rows,
                "message": "Decision-sheet JSON row_count must match the linked CSV row count.",
            }
        )
    if basis_coverage_path is not None:
        links.append(
            _aihr_packet_index_link(
                label="basis_coverage_json",
                path=basis_coverage_path,
                findings=findings,
            )
        )
        links.append(
            _aihr_packet_index_link(
                label="basis_coverage_markdown",
                path=basis_coverage_path.with_suffix(".md"),
                findings=findings,
            )
        )
    if unit_evidence_packet_path is not None:
        links.append(
            _aihr_packet_index_link(
                label="unit_evidence_packet_json",
                path=unit_evidence_packet_path,
                findings=findings,
            )
        )
        links.append(
            _aihr_packet_index_link(
                label="unit_evidence_packet_markdown",
                path=unit_evidence_packet_path.with_suffix(".md"),
                findings=findings,
            )
        )
    if official_learning_module_gap_audit_path is not None:
        links.append(
            _aihr_packet_index_link(
                label="official_learning_module_gap_audit_json",
                path=official_learning_module_gap_audit_path,
                findings=findings,
            )
        )
        links.append(
            _aihr_packet_index_link(
                label="official_learning_module_gap_audit_markdown",
                path=official_learning_module_gap_audit_path.with_suffix(".md"),
                findings=findings,
            )
        )
    if evidence_gap_triage_path is not None:
        links.append(
            _aihr_packet_index_link(
                label="evidence_gap_triage_json",
                path=evidence_gap_triage_path,
                findings=findings,
            )
        )
        links.append(
            _aihr_packet_index_link(
                label="evidence_gap_triage_markdown",
                path=evidence_gap_triage_path.with_suffix(".md"),
                findings=findings,
            )
        )

    packet_rows: list[dict[str, Any]] = []
    for path, packet in zip(group_packet_paths, group_packets):
        row = {
            "kind": "group_packet",
            "major_code": packet.get("major_code"),
            "item_type": packet.get("item_type"),
            "row_count": _as_optional_int(packet.get("row_count")) or 0,
            "pending_count": _as_optional_int(packet.get("pending_count")) or 0,
            "json_path": str(path),
            "markdown_path": str(path.with_suffix(".md")),
            "html_path": str(path.with_suffix(".html")),
            "approval_claim": packet.get("approval_claim"),
            "db_writes": packet.get("db_writes"),
        }
        packet_rows.append(row)
        for label, link_path in (
            (f"group_{packet.get('major_code')}_{packet.get('item_type')}_json", path),
            (f"group_{packet.get('major_code')}_{packet.get('item_type')}_markdown", path.with_suffix(".md")),
            (f"group_{packet.get('major_code')}_{packet.get('item_type')}_html", path.with_suffix(".html")),
        ):
            links.append(
                _aihr_packet_index_link(
                    label=label,
                    path=link_path,
                    findings=findings,
                )
            )

    decision_sheet_rows = (
        decision_sheet_csv_rows
        if decision_sheet_csv_rows is not None
        else decision_sheet_json_rows or 0
    )
    group_packet_rows = sum(_as_optional_int(packet.get("row_count")) or 0 for packet in group_packets)
    group_packet_pending_rows = sum(_as_optional_int(packet.get("pending_count")) or 0 for packet in group_packets)
    if require_full_group_coverage and decision_sheet_rows != group_packet_rows:
        findings.append(
            {
                "severity": "blocker",
                "code": "packet_index_group_coverage_mismatch",
                "decision_sheet_rows": decision_sheet_rows,
                "group_packet_rows": group_packet_rows,
                "message": "Group packet row total must match decision-sheet row_count.",
            }
        )

    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    return {
        "ok": blocker_count == 0,
        "schema": "aihr_plan_review_packet_index_v1",
        "created_at": created_at,
        "next_request": {
            "path": str(next_request_path),
            "html_path": str(next_request_path.with_suffix(".html")),
            "has_next_request": next_request.get("has_next_request"),
            "order": next_request.get("order"),
            "target_table": next_request.get("target_table"),
            "target_id": next_request.get("target_id"),
            "target_label": next_request.get("target_label"),
            "item_type": next_request.get("item_type"),
            "major_code": next_request.get("major_code"),
        },
        "decision_sheet": {
            "path": str(decision_sheet_path),
            "csv_path": str(decision_sheet_csv),
            "html_path": str(decision_sheet_html),
            "row_count": decision_sheet_rows,
            "json_row_count": decision_sheet_json_rows,
            "csv_row_count": decision_sheet_csv_rows,
        },
        "basis_coverage": {
            "path": str(basis_coverage_path) if basis_coverage_path is not None else None,
            "markdown_path": (
                str(basis_coverage_path.with_suffix(".md")) if basis_coverage_path is not None else None
            ),
            "item_count": _as_optional_int(basis_coverage.get("item_count")),
            "learning_module_visible_items": _as_optional_int(
                basis_coverage.get("learning_module_visible_items")
            ),
            "learning_module_direct_visible_items": _as_optional_int(
                basis_coverage.get("learning_module_direct_visible_items")
            ),
            "learning_module_context_visible_items": _as_optional_int(
                basis_coverage.get("learning_module_context_visible_items")
            ),
            "learning_module_unique_visible_sources": _as_optional_int(
                basis_coverage.get("learning_module_unique_visible_sources")
            ),
            "learning_module_duplicate_visible_sources": _as_optional_int(
                basis_coverage.get("learning_module_duplicate_visible_sources")
            ),
            "learning_module_global_unique_visible_sources": _as_optional_int(
                basis_coverage.get("learning_module_global_unique_visible_sources")
            ),
            "ncs_report_visible_items": _as_optional_int(basis_coverage.get("ncs_report_visible_items")),
            "ncs_report_direct_visible_items": _as_optional_int(
                basis_coverage.get("ncs_report_direct_visible_items")
            ),
            "ncs_report_context_visible_items": _as_optional_int(
                basis_coverage.get("ncs_report_context_visible_items")
            ),
            "ncs_report_unique_visible_sources": _as_optional_int(
                basis_coverage.get("ncs_report_unique_visible_sources")
            ),
            "ncs_report_duplicate_visible_sources": _as_optional_int(
                basis_coverage.get("ncs_report_duplicate_visible_sources")
            ),
            "ncs_report_global_unique_visible_sources": _as_optional_int(
                basis_coverage.get("ncs_report_global_unique_visible_sources")
            ),
            "both_missing_items": _as_optional_int(basis_coverage.get("both_missing_items")),
            "adjacent_both_missing_group_count": _as_optional_int(
                basis_coverage.get("adjacent_both_missing_group_count")
            ),
            "review_policy": (
                basis_coverage.get("review_policy")
                if isinstance(basis_coverage.get("review_policy"), dict)
                else {}
            ),
        },
        "unit_evidence_packet": {
            "path": str(unit_evidence_packet_path) if unit_evidence_packet_path is not None else None,
            "markdown_path": (
                str(unit_evidence_packet_path.with_suffix(".md"))
                if unit_evidence_packet_path is not None
                else None
            ),
            "schema": unit_evidence_packet.get("schema"),
            "unit_count": _as_optional_int(unit_evidence_packet.get("unit_count")),
            "item_count": _as_optional_int(unit_evidence_packet.get("item_count")),
            "review_policy": (
                unit_evidence_packet.get("review_policy")
                if isinstance(unit_evidence_packet.get("review_policy"), dict)
                else {}
            ),
        },
        "official_learning_module_gap_audit": {
            "path": (
                str(official_learning_module_gap_audit_path)
                if official_learning_module_gap_audit_path is not None
                else None
            ),
            "markdown_path": (
                str(official_learning_module_gap_audit_path.with_suffix(".md"))
                if official_learning_module_gap_audit_path is not None
                else None
            ),
            "schema": official_learning_module_gap_audit.get("schema"),
            "unit_count": _as_optional_int(official_learning_module_gap_audit.get("unit_count")),
            "official_direct_unit_count": _as_optional_int(
                official_learning_module_gap_audit.get("official_direct_unit_count")
            ),
            "official_direct_missing_unit_count": _as_optional_int(
                official_learning_module_gap_audit.get("official_direct_missing_unit_count")
            ),
            "gap_reason_counts": official_learning_module_gap_audit.get("gap_reason_counts") or {},
            "review_policy": (
                official_learning_module_gap_audit.get("review_policy")
                if isinstance(official_learning_module_gap_audit.get("review_policy"), dict)
                else {}
            ),
            "collection_policy": _aihr_reviewer_collection_policy(
                official_learning_module_gap_audit.get("collection_policy")
            ),
        },
        "evidence_gap_triage": {
            "path": str(evidence_gap_triage_path) if evidence_gap_triage_path is not None else None,
            "markdown_path": (
                str(evidence_gap_triage_path.with_suffix(".md"))
                if evidence_gap_triage_path is not None
                else None
            ),
            "schema": evidence_gap_triage.get("schema"),
            "item_count": _as_optional_int(evidence_gap_triage.get("item_count")),
            "unit_count": _as_optional_int(evidence_gap_triage.get("unit_count")),
            "summary": evidence_gap_triage.get("summary") or {},
            "next_request_triage": (
                evidence_gap_triage.get("next_request_triage")
                if isinstance(evidence_gap_triage.get("next_request_triage"), dict)
                else {}
            ),
            "review_policy": (
                evidence_gap_triage.get("review_policy")
                if isinstance(evidence_gap_triage.get("review_policy"), dict)
                else {}
            ),
        },
        "group_packets": packet_rows,
        "counts": {
            "group_packet_count": len(packet_rows),
            "decision_sheet_rows": decision_sheet_rows,
            "decision_sheet_json_rows": decision_sheet_json_rows,
            "decision_sheet_csv_rows": decision_sheet_csv_rows,
            "group_packet_rows": group_packet_rows,
            "group_packet_pending_rows": group_packet_pending_rows,
            "link_count": len(links),
            "missing_or_empty_link_count": sum(1 for link in links if not link.get("non_empty")),
            "source_payload_exposed_count": sum(1 for link in links if link.get("source_payload_exposed")),
        },
        "links": links,
        "require_full_group_coverage": require_full_group_coverage,
        "approval_claim": False,
        "db_writes": False,
        "status_update_allowed": False,
        "human_decision_required": True,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
    }


def write_aihr_plan_review_packet_index_markdown(report: dict[str, Any], out_path: Path) -> None:
    next_request = report.get("next_request") if isinstance(report.get("next_request"), dict) else {}
    decision_sheet = report.get("decision_sheet") if isinstance(report.get("decision_sheet"), dict) else {}
    basis_coverage = report.get("basis_coverage") if isinstance(report.get("basis_coverage"), dict) else {}
    unit_evidence_packet = (
        report.get("unit_evidence_packet")
        if isinstance(report.get("unit_evidence_packet"), dict)
        else {}
    )
    official_lm_gap = (
        report.get("official_learning_module_gap_audit")
        if isinstance(report.get("official_learning_module_gap_audit"), dict)
        else {}
    )
    evidence_gap_triage = (
        report.get("evidence_gap_triage")
        if isinstance(report.get("evidence_gap_triage"), dict)
        else {}
    )
    counts = report.get("counts") if isinstance(report.get("counts"), dict) else {}
    lines = [
        "# AI-HR Human Review Packet Index",
        "",
        f"- ok: {report.get('ok')}",
        f"- schema: {report.get('schema')}",
        f"- created_at: {report.get('created_at')}",
        f"- decision_sheet_rows: {counts.get('decision_sheet_rows')}",
        f"- group_packet_rows: {counts.get('group_packet_rows')}",
        f"- group_packet_pending_rows: {counts.get('group_packet_pending_rows')}",
        f"- source_payload_exposed_count: {counts.get('source_payload_exposed_count')}",
        f"- approval_claim: {report.get('approval_claim')}",
        f"- db_writes: {report.get('db_writes')}",
        f"- status_update_allowed: {report.get('status_update_allowed')}",
        "",
        "Human review only. No DB writes, no approval claim, no status update.",
        (
            "Legacy collection commands are out-of-band operator work; do not run "
            "collection from this packet index."
        ),
        (
            "Start here: 1) open basis coverage, "
            + (
                "2) open the unit evidence packet, 3) review the next request, "
                "4) record the action in the decision sheet."
                if unit_evidence_packet.get("path")
                else "2) review the next request, 3) record the action in the decision sheet."
            )
        ),
        "",
        "## Primary Files",
        "",
        "| purpose | rows | file | note |",
        "|---|---:|---|---|",
    ]
    if basis_coverage.get("path"):
        lines.append(
            "| basis coverage | "
            f"{basis_coverage.get('item_count')} | "
            f"{_aihr_markdown_action_link('Open basis coverage', basis_coverage.get('markdown_path'), out_path)} | "
            "check learning-module and NCS report/reference evidence before deciding |"
        )
    if unit_evidence_packet.get("path"):
        lines.append(
            "| unit evidence packet | "
            f"{unit_evidence_packet.get('unit_count')} | "
            f"{_aihr_markdown_action_link('Open unit evidence packet', unit_evidence_packet.get('markdown_path'), out_path)} | "
            "unit-level official learning module, report/reference, and diagnostic evidence |"
        )
    if official_lm_gap.get("path"):
        lines.append(
            "| official learning-module gap audit | "
            f"{official_lm_gap.get('unit_count')} | "
            f"{_aihr_markdown_action_link('Open official learning-module gap audit', official_lm_gap.get('markdown_path'), out_path)} | "
            "official EDU direct-link gaps, same-classification coverage, and query/collection hints |"
        )
    if evidence_gap_triage.get("path"):
        lines.append(
            "| evidence gap triage | "
            f"{evidence_gap_triage.get('unit_count')} | "
            f"{_aihr_markdown_action_link('Open evidence gap triage', evidence_gap_triage.get('markdown_path'), out_path)} | "
            "unit evidence tiers, weak/adjacent cleanup, and next-request review focus |"
        )
    lines.extend(
        [
            (
                "| next request | 1 | "
                f"{_aihr_markdown_action_link('Open next request', next_request.get('html_path'), out_path)} | "
                f"{next_request.get('target_table')}:{next_request.get('target_id')} / {next_request.get('target_label')} |"
            ),
            (
                "| decision sheet | "
                f"{decision_sheet.get('row_count')} | "
                f"{_aihr_markdown_action_link('Open decision sheet', decision_sheet.get('html_path'), out_path)} | "
                "record include_in_draft, exclude_from_draft, or defer; not approval evidence |"
            ),
        ]
    )
    for packet in report.get("group_packets") or []:
        if not isinstance(packet, dict):
            continue
        lines.append(
            "| "
            f"{packet.get('item_type')} | "
            f"{packet.get('row_count')} | "
            f"{_aihr_markdown_action_link('Open group packet', packet.get('html_path'), out_path)} | "
            f"major_code={packet.get('major_code')}, pending={packet.get('pending_count')} |"
        )
    if basis_coverage.get("path"):
        policy = (
            basis_coverage.get("review_policy")
            if isinstance(basis_coverage.get("review_policy"), dict)
            else {}
        )
        lines.extend(
            [
                "",
                "## Basis Coverage",
                "",
                (
                    "Count legend: `visible_items` counts review rows with visible basis; "
                    "`unique_visible_sources` is row-summed per-item deduplication; "
                    "`global_unique_visible_sources` is deduplicated across all review rows; "
                    "`duplicate_visible_sources` counts repeated visible references."
                ),
                "",
                f"- learning_module_visible_items: {basis_coverage.get('learning_module_visible_items')}",
                f"- learning_module_direct_visible_items: {basis_coverage.get('learning_module_direct_visible_items')}",
                f"- learning_module_context_visible_items: {basis_coverage.get('learning_module_context_visible_items')}",
                f"- learning_module_unique_visible_sources: {basis_coverage.get('learning_module_unique_visible_sources')}",
                f"- learning_module_duplicate_visible_sources: {basis_coverage.get('learning_module_duplicate_visible_sources')}",
                f"- learning_module_global_unique_visible_sources: {basis_coverage.get('learning_module_global_unique_visible_sources')}",
                f"- ncs_report_visible_items: {basis_coverage.get('ncs_report_visible_items')}",
                f"- ncs_report_direct_visible_items: {basis_coverage.get('ncs_report_direct_visible_items')}",
                f"- ncs_report_context_visible_items: {basis_coverage.get('ncs_report_context_visible_items')}",
                f"- ncs_report_unique_visible_sources: {basis_coverage.get('ncs_report_unique_visible_sources')}",
                f"- ncs_report_duplicate_visible_sources: {basis_coverage.get('ncs_report_duplicate_visible_sources')}",
                f"- ncs_report_global_unique_visible_sources: {basis_coverage.get('ncs_report_global_unique_visible_sources')}",
                f"- both_missing_items: {basis_coverage.get('both_missing_items')}",
                f"- adjacent_both_missing_group_count: {basis_coverage.get('adjacent_both_missing_group_count')}",
                f"- review_only: {policy.get('review_only')}",
                f"- non_scoring: {policy.get('non_scoring')}",
                f"- human_decision_required: {policy.get('human_decision_required')}",
            ]
        )
    findings = [finding for finding in report.get("findings") or [] if isinstance(finding, dict)]
    if official_lm_gap.get("path"):
        policy = (
            official_lm_gap.get("review_policy")
            if isinstance(official_lm_gap.get("review_policy"), dict)
            else {}
        )
        collection_policy = (
            official_lm_gap.get("collection_policy")
            if isinstance(official_lm_gap.get("collection_policy"), dict)
            else {}
        )
        lines.extend(
            [
                "",
                "## Official Learning Module Gap Audit",
                "",
                f"- unit_count: {official_lm_gap.get('unit_count')}",
                f"- official_direct_unit_count: {official_lm_gap.get('official_direct_unit_count')}",
                f"- official_direct_missing_unit_count: {official_lm_gap.get('official_direct_missing_unit_count')}",
                f"- gap_reason_counts: {json.dumps(official_lm_gap.get('gap_reason_counts') or {}, ensure_ascii=False, sort_keys=True)}",
                f"- review_only: {policy.get('review_only')}",
                f"- non_scoring: {policy.get('non_scoring')}",
                "- legacy_diagnostic_collection: out_of_band_operator_workflow_only",
                "- do_not_call_api_from_reviewer_artifact: true",
                "- separate_operator_workflow_required: true",
                "- collection_command_operator_note: command withheld from reviewer packet; do not run collection from this review packet.",
                f"- scoped_lookup_rule: {collection_policy.get('scoped_lookup_rule')}",
            ]
        )
    if evidence_gap_triage.get("path"):
        summary = (
            evidence_gap_triage.get("summary")
            if isinstance(evidence_gap_triage.get("summary"), dict)
            else {}
        )
        next_triage = (
            evidence_gap_triage.get("next_request_triage")
            if isinstance(evidence_gap_triage.get("next_request_triage"), dict)
            else {}
        )
        unit_triage = (
            next_triage.get("unit_triage")
            if isinstance(next_triage.get("unit_triage"), dict)
            else {}
        )
        policy = (
            evidence_gap_triage.get("review_policy")
            if isinstance(evidence_gap_triage.get("review_policy"), dict)
            else {}
        )
        lines.extend(
            [
                "",
                "## Evidence Gap Triage",
                "",
                f"- item_count: {evidence_gap_triage.get('item_count')}",
                f"- unit_count: {evidence_gap_triage.get('unit_count')}",
                f"- evidence_tier_counts: {json.dumps(summary.get('evidence_tier_counts') or {}, ensure_ascii=False, sort_keys=True)}",
                f"- official_direct_missing_unit_count: {summary.get('official_direct_missing_unit_count')}",
                f"- ocr_context_unit_count: {summary.get('ocr_context_unit_count')}",
                f"- display_context_unit_count: {summary.get('display_context_unit_count')}",
                f"- source_artifact_needs_regeneration: {summary.get('source_artifact_needs_regeneration')}",
                f"- next_request_severity: {unit_triage.get('severity')}",
                f"- next_request_evidence_tier: {unit_triage.get('evidence_tier')}",
                f"- decision_sheet_prefill_allowed: {summary.get('decision_sheet_prefill_allowed')}",
                f"- review_only: {policy.get('review_only')}",
                f"- non_scoring: {policy.get('non_scoring')}",
            ]
        )
    if findings:
        lines.extend(["", "## Findings", ""])
        for finding in findings:
            lines.append(
                "- "
                f"{finding.get('severity')}:{finding.get('code')} "
                f"{finding.get('message')}"
            )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


