AIHR_REVIEW_BASIS_MISSING_STATUSES = {"", "missing", "missing_ncs_code", "not_available"}


def _aihr_item_review_basis_candidates(
    item: dict[str, Any],
    key: str,
    *,
    include_direct: bool = True,
    include_context: bool = True,
) -> list[dict[str, Any]]:
    evidence = item.get("current_evidence") if isinstance(item.get("current_evidence"), dict) else {}
    candidates: list[dict[str, Any]] = []
    if include_direct and isinstance(evidence.get(key), dict) and evidence.get(key):
        candidates.append(evidence[key])
    if include_context:
        for context in _aihr_seedpack_review_contexts(item):
            if isinstance(context.get(key), dict) and context.get(key):
                candidates.append(context[key])
    normalized = [
        _aihr_review_basis_with_policy(candidate)
        for candidate in candidates
        if isinstance(candidate, dict)
    ]
    return normalized


def _aihr_item_review_basis(
    item: dict[str, Any],
    key: str,
    *,
    include_direct: bool = True,
    include_context: bool = True,
) -> dict[str, Any]:
    normalized = _aihr_item_review_basis_candidates(
        item,
        key,
        include_direct=include_direct,
        include_context=include_context,
    )
    visible = [
        (index, candidate)
        for index, candidate in enumerate(normalized)
        if str(candidate.get("status") or "").strip()
        not in AIHR_REVIEW_BASIS_MISSING_STATUSES
    ]
    if visible:
        return max(
            visible,
            key=lambda indexed: _aihr_review_basis_candidate_score(indexed[1], key, indexed[0]),
        )[1]
    if normalized:
        return normalized[0]
    if key == "learning_module_review_basis":
        schema = "aihr_learning_module_review_basis_v1"
        role = "auxiliary_human_review_evidence"
    elif key == "non_official_diagnostic_basis":
        schema = "aihr_non_official_diagnostic_basis_v1"
        role = "non_official_human_review_diagnostic_only"
    else:
        schema = "aihr_ncs_report_review_basis_v1"
        role = "human_review_methodology_and_auxiliary_course_evidence"
    return {
        "schema": schema,
        "status": "missing",
        "basis_role": role,
        **_aihr_review_only_basis_policy(),
    }


def _aihr_review_status_trusted_count(counts: Any) -> int:
    if not isinstance(counts, dict):
        return 0
    return sum(
        int(counts.get(status) or 0)
        for status in ("human_reviewed", "reviewed", "accepted")
    )


def _aihr_review_basis_candidate_score(
    basis: dict[str, Any],
    key: str,
    index: int,
) -> tuple[int, int, int]:
    if key == "learning_module_review_basis":
        trusted = int(basis.get("trusted_link_count") or 0)
        visible = int(basis.get("official_module_count") or 0)
    elif key == "non_official_diagnostic_basis":
        trusted = 0
        visible = sum(int(value or 0) for value in (basis.get("direct_non_official_counts") or {}).values())
    else:
        trusted = _aihr_review_status_trusted_count(
            basis.get("report_training_course_status_counts")
        ) + _aihr_review_status_trusted_count(basis.get("reference_link_status_counts"))
        visible = int(basis.get("report_training_course_count") or 0) + int(
            basis.get("reference_link_count") or 0
        )
    return (trusted, visible, -index)


def _aihr_review_basis_visible_count(basis: dict[str, Any], key: str) -> int:
    if key == "learning_module_review_basis":
        return int(basis.get("official_module_count") or 0)
    if key == "non_official_diagnostic_basis":
        return sum(int(value or 0) for value in (basis.get("direct_non_official_counts") or {}).values())
    return int(basis.get("report_training_course_count") or 0) + int(
        basis.get("reference_link_count") or 0
    )


def _aihr_review_basis_visible(basis: dict[str, Any]) -> bool:
    return str(basis.get("status") or "").strip() not in AIHR_REVIEW_BASIS_MISSING_STATUSES


def _aihr_review_basis_evidence_signatures(
    basis: dict[str, Any],
    key: str,
    *,
    candidate_index: int,
) -> list[tuple[str, ...]]:
    if not _aihr_review_basis_visible(basis):
        return []
    signatures: list[tuple[str, ...]] = []
    if key == "learning_module_review_basis":
        for module in basis.get("modules") or []:
            if not isinstance(module, dict):
                continue
            seq = str(module.get("learn_module_seq") or "").strip()
            name = str(module.get("learn_module_name") or "").strip()
            unit = str(module.get("unit_code") or basis.get("ncs_cl_cd") or "").strip()
            if seq or name:
                signatures.append(("learning_module", seq, name, unit))
        if signatures:
            return signatures
        count = int(basis.get("official_module_count") or 0)
        return [
            ("learning_module_count_only", str(candidate_index), str(index))
            for index in range(count)
        ]
    if key == "non_official_diagnostic_basis":
        for sample in basis.get("direct_non_official_samples") or []:
            if not isinstance(sample, dict):
                continue
            seq = str(sample.get("learn_module_seq") or "").strip()
            name = str(sample.get("learn_module_name") or "").strip()
            unit = str(sample.get("unit_code") or basis.get("ncs_cl_cd") or "").strip()
            kind = str(sample.get("basis_kind") or "").strip()
            if seq or name:
                signatures.append(("non_official_diagnostic", kind, seq, name, unit))
        if signatures:
            return signatures
        count = sum(int(value or 0) for value in (basis.get("direct_non_official_counts") or {}).values())
        return [
            ("non_official_diagnostic_count_only", str(candidate_index), str(index))
            for index in range(count)
        ]

    for course in basis.get("report_training_courses") or []:
        if not isinstance(course, dict):
            continue
        seq = str(course.get("learn_module_seq") or "").strip()
        name = str(course.get("learn_module_name") or "").strip()
        unit = str(course.get("unit_code") or basis.get("ncs_cl_cd") or "").strip()
        if seq or name:
            signatures.append(("report_training_course", seq, name, unit))
    for chunk in basis.get("reference_chunks") or []:
        if not isinstance(chunk, dict):
            continue
        link_id = str(chunk.get("link_id") or "").strip()
        chunk_id = str(chunk.get("chunk_id") or "").strip()
        document_id = str(chunk.get("document_id") or "").strip()
        entity = str(chunk.get("entity_text") or "").strip()
        page = str(chunk.get("page_start") or "").strip()
        if link_id or chunk_id or document_id or entity:
            signatures.append(("report_reference_chunk", link_id, chunk_id, document_id, entity, page))
    if signatures:
        return signatures
    count = int(basis.get("report_training_course_count") or 0) + int(
        basis.get("reference_link_count") or 0
    )
    return [
        ("report_basis_count_only", str(candidate_index), str(index))
        for index in range(count)
    ]


def _aihr_item_review_basis_unique_summary(item: dict[str, Any], key: str) -> dict[str, int]:
    candidates = _aihr_item_review_basis_candidates(item, key)
    signatures: list[tuple[str, ...]] = []
    visible_candidate_count = 0
    for index, basis in enumerate(candidates):
        basis_signatures = _aihr_review_basis_evidence_signatures(
            basis,
            key,
            candidate_index=index,
        )
        if basis_signatures:
            visible_candidate_count += 1
            signatures.extend(basis_signatures)
    unique_signatures = set(signatures)
    return {
        "unique_visible_count": len(unique_signatures),
        "duplicate_source_count": max(0, len(signatures) - len(unique_signatures)),
        "visible_candidate_count": visible_candidate_count,
    }


def _aihr_item_review_basis_visible_signatures(item: dict[str, Any], key: str) -> list[tuple[str, ...]]:
    signatures: list[tuple[str, ...]] = []
    for index, basis in enumerate(_aihr_item_review_basis_candidates(item, key)):
        signatures.extend(
            _aihr_review_basis_evidence_signatures(
                basis,
                key,
                candidate_index=index,
            )
        )
    return signatures


def _aihr_adjacent_basis_gap_groups(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[tuple[str, str], dict[str, Any]] = {}
    for row in rows:
        if row.get("basis_gap_classification") != "adjacent_same_middle_auxiliary_basis_missing":
            continue
        key = (str(row.get("ncs_cl_cd") or ""), str(row.get("target_label") or ""))
        group = grouped.setdefault(
            key,
            {
                "group_key": "|".join(key),
                "ncs_cl_cd": row.get("ncs_cl_cd"),
                "target_label": row.get("target_label"),
                "required_optional": row.get("required_optional"),
                "evidence_directness": row.get("evidence_directness"),
                "course_scope_relation": row.get("course_scope_relation"),
                "basis_gap_classification": row.get("basis_gap_classification"),
                "basis_gap_severity": row.get("basis_gap_severity"),
                "recommended_handling": (
                    "Treat as one weak adjacent-reference review item. Keep pending for "
                    "human decision if adjacent references are in scope, but do not promote "
                    "above direct HR evidence and do not auto-approve or write DB status."
                ),
                "rows": [],
                "shared_flags": [],
                "approval_claim": False,
                "db_writes": False,
                "status_update_allowed": False,
            },
        )
        group["rows"].append(
            {
                "order": row.get("order"),
                "item_type": row.get("item_type"),
                "target_table": row.get("target_table"),
                "target_id": row.get("target_id"),
                "missing_basis": row.get("missing_basis") or [],
            }
        )
        flags = set(group.get("shared_flags") or [])
        flags.update(str(flag) for flag in row.get("review_flags") or [] if str(flag).strip())
        group["shared_flags"] = sorted(flags)
    groups = list(grouped.values())
    for group in groups:
        group["row_count"] = len(group.get("rows") or [])
        group["item_types"] = sorted(
            {
                str(row.get("item_type"))
                for row in group.get("rows") or []
                if str(row.get("item_type") or "").strip()
            }
        )
    return sorted(groups, key=lambda group: (str(group.get("ncs_cl_cd") or ""), str(group.get("target_label") or "")))


def _aihr_basis_coverage_row(
    *,
    item: dict[str, Any],
    order_row: dict[str, Any],
    audit_row: dict[str, Any],
) -> dict[str, Any]:
    evidence = item.get("current_evidence") if isinstance(item.get("current_evidence"), dict) else {}
    contexts = _aihr_seedpack_review_contexts(item)
    learning_basis = _aihr_item_review_basis(item, "learning_module_review_basis")
    learning_direct_basis = _aihr_item_review_basis(
        item,
        "learning_module_review_basis",
        include_context=False,
    )
    learning_context_basis = _aihr_item_review_basis(
        item,
        "learning_module_review_basis",
        include_direct=False,
    )
    report_basis = _aihr_item_review_basis(item, "ncs_report_review_basis")
    report_direct_basis = _aihr_item_review_basis(
        item,
        "ncs_report_review_basis",
        include_context=False,
    )
    report_context_basis = _aihr_item_review_basis(
        item,
        "ncs_report_review_basis",
        include_direct=False,
    )
    learning_unique_summary = _aihr_item_review_basis_unique_summary(
        item,
        "learning_module_review_basis",
    )
    report_unique_summary = _aihr_item_review_basis_unique_summary(
        item,
        "ncs_report_review_basis",
    )
    review_flags = sorted(
        {
            str(flag)
            for context in contexts
            for flag in context.get("review_flags") or []
            if str(flag).strip()
        }
        | {
            str(flag)
            for flag in evidence.get("review_flags") or []
            if str(flag).strip()
        }
    )
    evidence_summary = _aihr_request_order_evidence_summary(item, contexts)
    missing_basis = []
    if str(learning_basis.get("status") or "") in {"missing", "missing_ncs_code", "not_available"}:
        missing_basis.append("learning_module_review_basis")
    if str(report_basis.get("status") or "") in {"missing", "missing_ncs_code", "not_available"}:
        missing_basis.append("ncs_report_review_basis")
    adjacent_reference = (
        evidence_summary.get("required_optional") == "adjacent_reference"
        or str(evidence_summary.get("course_scope_relation") or "").startswith("same_")
        or "adjacent_reference_only" in set(review_flags)
    )
    if set(missing_basis) == {"learning_module_review_basis", "ncs_report_review_basis"}:
        if adjacent_reference:
            gap_classification = "adjacent_same_middle_auxiliary_basis_missing"
            gap_severity = "expected_review_gap"
            gap_action = "collapse_as_adjacent_reference; keep pending for human review; do not treat as direct HR blocker"
        else:
            gap_classification = "direct_or_unclassified_auxiliary_basis_missing"
            gap_severity = "high_risk"
            gap_action = "review_before_using_as_direct_HR_evidence"
    elif missing_basis:
        gap_classification = "partial_auxiliary_basis_missing"
        gap_severity = "review"
        gap_action = "review visible basis and missing auxiliary evidence"
    else:
        gap_classification = "basis_visible"
        gap_severity = "none"
        gap_action = "no auxiliary basis gap"
    return {
        "order": order_row.get("order"),
        "pending": audit_row.get("pending", True) if audit_row else True,
        "item_type": item.get("item_type"),
        "target_table": item.get("target_table"),
        "target_id": item.get("target_id"),
        "target_label": order_row.get("target_label") or _aihr_seedpack_target_label(item),
        "ncs_cl_cd": item.get("ncs_cl_cd") or evidence.get("ncs_cl_cd"),
        "major_code": item.get("major_code") or evidence.get("major_code"),
        "required_optional": evidence_summary.get("required_optional"),
        "evidence_directness": evidence_summary.get("evidence_directness"),
        "course_scope_relation": evidence_summary.get("course_scope_relation"),
        "review_flags": review_flags,
        "learning_module_status": learning_basis.get("status"),
        "learning_module_direct_status": learning_direct_basis.get("status"),
        "learning_module_context_status": learning_context_basis.get("status"),
        "learning_module_visible_count": _aihr_review_basis_visible_count(
            learning_basis,
            "learning_module_review_basis",
        ),
        "learning_module_direct_visible_count": _aihr_review_basis_visible_count(
            learning_direct_basis,
            "learning_module_review_basis",
        ),
        "learning_module_context_visible_count": _aihr_review_basis_visible_count(
            learning_context_basis,
            "learning_module_review_basis",
        ),
        "learning_module_trusted_count": int(learning_basis.get("trusted_link_count") or 0),
        "learning_module_unique_visible_count": learning_unique_summary["unique_visible_count"],
        "learning_module_duplicate_source_count": learning_unique_summary["duplicate_source_count"],
        "learning_module_visible_candidate_count": learning_unique_summary["visible_candidate_count"],
        "learning_module_gap_reason": learning_basis.get("gap_reason"),
        "learning_module_direct_gap_reason": learning_direct_basis.get("gap_reason"),
        "learning_module_context_gap_reason": learning_context_basis.get("gap_reason"),
        "learning_module_direct_non_official_counts": learning_basis.get(
            "direct_non_official_counts"
        )
        or {},
        "learning_module_review_gap_action": learning_basis.get("review_gap_action"),
        "ncs_report_status": report_basis.get("status"),
        "ncs_report_direct_status": report_direct_basis.get("status"),
        "ncs_report_context_status": report_context_basis.get("status"),
        "ncs_report_visible_count": _aihr_review_basis_visible_count(
            report_basis,
            "ncs_report_review_basis",
        ),
        "ncs_report_direct_visible_count": _aihr_review_basis_visible_count(
            report_direct_basis,
            "ncs_report_review_basis",
        ),
        "ncs_report_context_visible_count": _aihr_review_basis_visible_count(
            report_context_basis,
            "ncs_report_review_basis",
        ),
        "ncs_report_unique_visible_count": report_unique_summary["unique_visible_count"],
        "ncs_report_duplicate_source_count": report_unique_summary["duplicate_source_count"],
        "ncs_report_visible_candidate_count": report_unique_summary["visible_candidate_count"],
        "missing_basis": missing_basis,
        "basis_gap_classification": gap_classification,
        "basis_gap_severity": gap_severity,
        "basis_gap_action": gap_action,
        "review_only": learning_basis.get("review_only") is True
        and report_basis.get("review_only") is True,
        "non_scoring": learning_basis.get("non_scoring") is True
        and report_basis.get("non_scoring") is True,
        "approval_claim": False,
        "db_writes": False,
    }


def build_aihr_plan_review_basis_coverage(
    *,
    seedpack_path: Path,
    request_order_path: Path | None = None,
    decision_audit_path: Path | None = None,
    sample_limit: int = 20,
) -> dict[str, Any]:
    created_at = datetime.now(timezone.utc).isoformat()
    findings: list[dict[str, Any]] = []
    seedpack = _load_json_artifact(seedpack_path, "seedpack", findings)
    request_order = (
        _load_json_artifact(request_order_path, "request_order", findings)
        if request_order_path
        else {}
    )
    decision_audit = (
        _load_json_artifact(decision_audit_path, "decision_audit", findings)
        if decision_audit_path
        else {}
    )
    for label, payload in (
        ("seedpack", seedpack),
        ("request_order", request_order),
        ("decision_audit", decision_audit),
    ):
        if payload:
            _artifact_claims_no_approval_or_db_writes(payload, label, findings)

    order_rows = {
        _aihr_review_item_key(row): row
        for row in request_order.get("queue") or []
        if isinstance(row, dict)
    }
    audit_rows = {
        _aihr_review_item_key(row): row
        for row in decision_audit.get("rows") or []
        if isinstance(row, dict)
    }
    rows: list[dict[str, Any]] = []
    learning_global_signatures: set[tuple[str, ...]] = set()
    report_global_signatures: set[tuple[str, ...]] = set()
    for item in seedpack.get("items") or []:
        if not isinstance(item, dict):
            continue
        learning_global_signatures.update(
            _aihr_item_review_basis_visible_signatures(
                item,
                "learning_module_review_basis",
            )
        )
        report_global_signatures.update(
            _aihr_item_review_basis_visible_signatures(
                item,
                "ncs_report_review_basis",
            )
        )
        key = _aihr_review_item_key(item)
        row = _aihr_basis_coverage_row(
            item=item,
            order_row=order_rows.get(key, {}),
            audit_row=audit_rows.get(key, {}),
        )
        rows.append(row)
        if not row.get("review_only") or not row.get("non_scoring"):
            findings.append(
                {
                    "severity": "blocker",
                    "code": "review_basis_policy_not_review_only",
                    "target_table": row.get("target_table"),
                    "target_id": row.get("target_id"),
                    "message": "Learning-module/report basis must be review_only and non_scoring.",
                }
            )

    by_item_type: dict[str, dict[str, Any]] = {}
    for row in rows:
        item_type = str(row.get("item_type") or "unknown")
        bucket = by_item_type.setdefault(
            item_type,
            {
                "item_count": 0,
                "learning_module_status_counts": {},
                "learning_module_direct_status_counts": {},
                "learning_module_context_status_counts": {},
                "learning_module_gap_reason_counts": {},
                "ncs_report_status_counts": {},
                "ncs_report_direct_status_counts": {},
                "ncs_report_context_status_counts": {},
                "learning_module_visible_items": 0,
                "learning_module_direct_visible_items": 0,
                "learning_module_context_visible_items": 0,
                "ncs_report_visible_items": 0,
                "ncs_report_direct_visible_items": 0,
                "ncs_report_context_visible_items": 0,
                "learning_module_unique_visible_sources": 0,
                "learning_module_duplicate_visible_sources": 0,
                "ncs_report_unique_visible_sources": 0,
                "ncs_report_duplicate_visible_sources": 0,
                "both_visible_items": 0,
                "both_missing_items": 0,
            },
        )
        bucket["item_count"] += 1
        _increment_counter(
            bucket["learning_module_status_counts"],
            str(row.get("learning_module_status") or "missing"),
        )
        _increment_counter(
            bucket["learning_module_direct_status_counts"],
            str(row.get("learning_module_direct_status") or "missing"),
        )
        _increment_counter(
            bucket["learning_module_context_status_counts"],
            str(row.get("learning_module_context_status") or "missing"),
        )
        _increment_counter(
            bucket["learning_module_gap_reason_counts"],
            str(row.get("learning_module_gap_reason") or "none"),
        )
        _increment_counter(
            bucket["ncs_report_status_counts"],
            str(row.get("ncs_report_status") or "missing"),
        )
        _increment_counter(
            bucket["ncs_report_direct_status_counts"],
            str(row.get("ncs_report_direct_status") or "missing"),
        )
        _increment_counter(
            bucket["ncs_report_context_status_counts"],
            str(row.get("ncs_report_context_status") or "missing"),
        )
        learning_visible = int(row.get("learning_module_visible_count") or 0) > 0
        learning_direct_visible = int(row.get("learning_module_direct_visible_count") or 0) > 0
        learning_context_visible = int(row.get("learning_module_context_visible_count") or 0) > 0
        report_visible = int(row.get("ncs_report_visible_count") or 0) > 0
        report_direct_visible = int(row.get("ncs_report_direct_visible_count") or 0) > 0
        report_context_visible = int(row.get("ncs_report_context_visible_count") or 0) > 0
        bucket["learning_module_unique_visible_sources"] += int(
            row.get("learning_module_unique_visible_count") or 0
        )
        bucket["learning_module_duplicate_visible_sources"] += int(
            row.get("learning_module_duplicate_source_count") or 0
        )
        bucket["ncs_report_unique_visible_sources"] += int(
            row.get("ncs_report_unique_visible_count") or 0
        )
        bucket["ncs_report_duplicate_visible_sources"] += int(
            row.get("ncs_report_duplicate_source_count") or 0
        )
        if learning_visible:
            bucket["learning_module_visible_items"] += 1
        if learning_direct_visible:
            bucket["learning_module_direct_visible_items"] += 1
        if learning_context_visible:
            bucket["learning_module_context_visible_items"] += 1
        if report_visible:
            bucket["ncs_report_visible_items"] += 1
        if report_direct_visible:
            bucket["ncs_report_direct_visible_items"] += 1
        if report_context_visible:
            bucket["ncs_report_context_visible_items"] += 1
        if learning_visible and report_visible:
            bucket["both_visible_items"] += 1
        if not learning_visible and not report_visible:
            bucket["both_missing_items"] += 1

    bounded_sample_limit = clamp_limit(sample_limit, default=20, maximum=200)
    missing_basis_rows = [row for row in rows if row.get("missing_basis")][:bounded_sample_limit]
    high_risk_missing_rows = [
        row
        for row in rows
        if row.get("missing_basis")
        and (
            row.get("review_flags")
            or str(row.get("item_type") or "") == "training_system_row_review"
        )
    ][:bounded_sample_limit]
    context_only_basis_rows = [
        row
        for row in rows
        if (
            int(row.get("learning_module_direct_visible_count") or 0) == 0
            and int(row.get("learning_module_visible_count") or 0) > 0
        )
        or (
            int(row.get("ncs_report_direct_visible_count") or 0) == 0
            and int(row.get("ncs_report_visible_count") or 0) > 0
        )
    ][:bounded_sample_limit]
    both_missing_rows = [
        row
        for row in rows
        if set(row.get("missing_basis") or [])
        == {"learning_module_review_basis", "ncs_report_review_basis"}
    ]
    adjacent_both_missing_rows = [
        row
        for row in both_missing_rows
        if row.get("required_optional") == "adjacent_reference"
        or str(row.get("course_scope_relation") or "").startswith("same_")
        or "adjacent_reference_only" in set(row.get("review_flags") or [])
    ]
    adjacent_both_missing_groups = _aihr_adjacent_basis_gap_groups(rows)
    learning_visible_items = sum(
        1 for row in rows if int(row.get("learning_module_visible_count") or 0) > 0
    )
    learning_direct_visible_items = sum(
        1 for row in rows if int(row.get("learning_module_direct_visible_count") or 0) > 0
    )
    learning_context_visible_items = sum(
        1 for row in rows if int(row.get("learning_module_context_visible_count") or 0) > 0
    )
    report_visible_items = sum(1 for row in rows if int(row.get("ncs_report_visible_count") or 0) > 0)
    report_direct_visible_items = sum(
        1 for row in rows if int(row.get("ncs_report_direct_visible_count") or 0) > 0
    )
    report_context_visible_items = sum(
        1 for row in rows if int(row.get("ncs_report_context_visible_count") or 0) > 0
    )
    learning_unique_visible_sources = sum(
        int(row.get("learning_module_unique_visible_count") or 0) for row in rows
    )
    learning_duplicate_visible_sources = sum(
        int(row.get("learning_module_duplicate_source_count") or 0) for row in rows
    )
    report_unique_visible_sources = sum(
        int(row.get("ncs_report_unique_visible_count") or 0) for row in rows
    )
    report_duplicate_visible_sources = sum(
        int(row.get("ncs_report_duplicate_source_count") or 0) for row in rows
    )
    learning_gap_reason_counts: dict[str, int] = {}
    for row in rows:
        _increment_counter(
            learning_gap_reason_counts,
            str(row.get("learning_module_gap_reason") or "none"),
        )
    blocker_count = sum(1 for finding in findings if finding.get("severity") == "blocker")
    return {
        "ok": blocker_count == 0,
        "schema": "aihr_plan_review_basis_coverage_v1",
        "created_at": created_at,
        "source_seedpack": str(seedpack_path),
        "source_request_order": str(request_order_path) if request_order_path else None,
        "source_decision_audit": str(decision_audit_path) if decision_audit_path else None,
        "item_count": len(rows),
        "basis_scope": {
            "effective": "direct_or_context_visible_preferred",
            "direct": "current_evidence only",
            "context": "contexts, plan_contexts, source_contexts, and target_contexts",
            "unique": "deduplicated direct+context evidence signatures; count-only basis uses conservative non-deduplicated fallback",
        },
        "learning_module_visible_items": learning_visible_items,
        "learning_module_direct_visible_items": learning_direct_visible_items,
        "learning_module_context_visible_items": learning_context_visible_items,
        "ncs_report_visible_items": report_visible_items,
        "ncs_report_direct_visible_items": report_direct_visible_items,
        "ncs_report_context_visible_items": report_context_visible_items,
        "learning_module_unique_visible_sources": learning_unique_visible_sources,
        "learning_module_duplicate_visible_sources": learning_duplicate_visible_sources,
        "learning_module_global_unique_visible_sources": len(learning_global_signatures),
        "learning_module_gap_reason_counts": learning_gap_reason_counts,
        "ncs_report_unique_visible_sources": report_unique_visible_sources,
        "ncs_report_duplicate_visible_sources": report_duplicate_visible_sources,
        "ncs_report_global_unique_visible_sources": len(report_global_signatures),
        "both_visible_items": sum(
            1
            for row in rows
            if int(row.get("learning_module_visible_count") or 0) > 0
            and int(row.get("ncs_report_visible_count") or 0) > 0
        ),
        "both_missing_items": sum(
            1
            for row in rows
            if int(row.get("learning_module_visible_count") or 0) == 0
            and int(row.get("ncs_report_visible_count") or 0) == 0
        ),
        "by_item_type": by_item_type,
        "missing_basis_rows": missing_basis_rows,
        "high_risk_missing_rows": high_risk_missing_rows,
        "context_only_basis_rows": context_only_basis_rows,
        "both_missing_rows": both_missing_rows[:bounded_sample_limit],
        "adjacent_both_missing_rows": adjacent_both_missing_rows[:bounded_sample_limit],
        "both_missing_row_count": len(both_missing_rows),
        "adjacent_both_missing_row_count": len(adjacent_both_missing_rows),
        "adjacent_both_missing_groups": adjacent_both_missing_groups[:bounded_sample_limit],
        "adjacent_both_missing_group_count": len(adjacent_both_missing_groups),
        "review_policy": {
            "review_only": True,
            "non_scoring": True,
            "approval_claim": False,
            "db_writes": False,
            "status_update_allowed": False,
            "human_decision_required": True,
            "review_status_counts_meaning": AIHR_REVIEW_BASIS_COUNTS_MEANING,
            "coverage_counts_meaning": (
                "visible_items are row-level coverage counts; unique_visible_sources are row-summed "
                "deduplicated source counts; global_unique_visible_sources deduplicates the same "
                "learning-module/report source across all review rows."
            ),
        },
        "approval_claim": False,
        "db_writes": False,
        "status_update_allowed": False,
        "human_decision_required": True,
        "findings": findings,
        "blocker_count": blocker_count,
        "review_finding_count": sum(1 for finding in findings if finding.get("severity") == "review"),
    }


