        f"- learning_module_duplicate_visible_sources: {report.get('learning_module_duplicate_visible_sources')}",
        f"- learning_module_global_unique_visible_sources: {report.get('learning_module_global_unique_visible_sources')}",
        f"- learning_module_gap_reason_counts: {json.dumps(report.get('learning_module_gap_reason_counts') or {}, ensure_ascii=False, sort_keys=True)}",
