        f"- ncs_report_unique_visible_sources: {report.get('ncs_report_unique_visible_sources')}",
        f"- ncs_report_duplicate_visible_sources: {report.get('ncs_report_duplicate_visible_sources')}",
        f"- ncs_report_global_unique_visible_sources: {report.get('ncs_report_global_unique_visible_sources')}",
