                not bad_queue_source_artifacts,
                (
                    "source_queue_path_matches_release_queue"
                    if not bad_queue_source_artifacts
                    else (
                        f"expected={release_readiness_queue_path}, "
                        f"bad={bad_queue_source_artifacts}"
                    )
                ),
                release_readiness_queue_path=release_readiness_queue_path,
                bad_queue_source=bad_queue_source_artifacts,
